import{aE as Oe,ak as o,ab as i,C as s,bv as Oa,N as l,n as C,D as E,du as A,c9 as Ga,e0 as Jr,e1 as qa,cA as bo,br as Yr,a as vo,b as ko,bj as So,e2 as La,e3 as Zr,cG as Ao,cV as jr,cU as To,dx as Nt,e4 as Kr,e5 as L,e6 as $o,e7 as Po,e8 as Co,e9 as Eo,dj as Qr,ea as Xr,eb as Fo,ec as Do,ed as Io}from"./index-BDWW1Y9j.js";import{i as eo}from"./rideRuleAudience-C5lhXAX_.js";import{A as R}from"./arabianHorseShow-DDL6l7NS.js";const za="2026-09-04",xo=["premium-suv-scottsdale","maybach-shuttle-sprinter-8","maybach-jet-sprinter-scottsdale","executive-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","limo-sprinter-16-scottsdale","executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"].filter(Oe),we=xo.map(e=>({slug:e,name:o[e],capacity:i[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours}));function to(e){return l(s[e].hourlyRateCents)}function ao(e,t,a){return l(Math.round(s[e].hourlyRateCents*t/a))}const Ro=[{href:"/services/wedding-transportation-scottsdale",label:"Scottsdale wedding transportation"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter van rental"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport group transportation"},{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published hourly pricing"}];function Ye(e){const t=we.find(n=>n.slug==="executive-sprinter-scottsdale"),a=we.find(n=>n.slug==="motorcoach-56");return{path:e.path,title:`${e.name} Wedding Shuttle Guide | Scottsdale Sprinters`,description:`Plan ${e.name} wedding shuttles with published vehicle capacities, hotel pickup waves, venue arrival coordination, and an end-of-night return plan.`,metaDescription:"Hotel pickup waves, vehicle sizing and the end-of-night return",updatedAt:"2026-09-18",h1:`${e.name} wedding shuttle and guest transportation`,eyebrow:"Wedding venue transportation guide",intro:`A ${e.name} shuttle from Scottsdale Sprinters works best when one transportation lead owns the guest list, every pickup has a written address, and the venue confirms the final arrival point. This guide turns that into vehicle counts, pickup waves, driver notes, and a return schedule, without inventing a gate or loading zone.`,fleetTable:!0,sections:[{heading:`What should couples know about ${e.name} before planning transportation?`,answer:`${e.name} planning starts with 3 verified details: the venue address, the contracted event space, and the arrival instructions supplied by the venue team, because a property name alone is not enough for a driver brief and public websites do not always publish a wedding-specific loading point.`,paragraphs:[`${e.name} is at ${e.address}. ${e.venueFacts} That tells a transportation planner where the property is and what kind of celebration the venue supports, but it does not replace the instructions in the couple's venue contract. The final driver sheet should use the venue's current written directions and the event-space name exactly as the coordinator provides them.`,`${e.arrivalNote} We do not label an unverified driveway, gate, porte cochere, or service entrance as the wedding drop-off. The couple or planner should ask the venue which approach is approved for the booked space, whether a vehicle may wait, and where guests with mobility needs should be delivered. Those answers belong in the dispatch note before the wedding day.`,e.venueSpecific[0],"Treat the venue source linked below as a planning reference, then reconcile it with the banquet event order. Websites can change, private-event operations can differ from hotel arrivals, and another event may affect traffic flow. One confirmed instruction shared with the reservations team, planner, and venue contact is safer than several guests forwarding different map pins."]},{heading:`Which vehicle size fits the ${e.name} wedding guest count?`,answer:`For ${e.name}, use 10 published capacity bands from a 6-passenger luxury SUV through a 56-passenger motorcoach, then reserve seats for the people actually riding rather than the total attendance; a 120-guest reception may need transportation for only 42 hotel guests while the wedding party follows a separate schedule.`,paragraphs:[`The table on this page uses the same current capacities and hourly rates shown with each vehicle. The ${t.name} seats ${t.capacity} and starts at ${l(t.hourlyRateCents)} per hour, while the ${a.name} seats ${a.capacity} and starts at ${l(a.hourlyRateCents)} per hour. Those figures update with the published fleet information rather than relying on estimates copied into the article.`,"Build the rider count from RSVPs, hotel blocks, family assignments, and accessibility needs. Do not divide the full invitation list by the largest vehicle. Some guests will drive, some will stay on property, and some may need an earlier departure. A clean manifest groups people by pickup and return wave, which can reduce empty seats without putting the ceremony at risk.",e.venueSpecific[1],"Leave operational margin. A vehicle advertised for a maximum seated capacity is not a promise that every combination of passengers, dresses, mobility devices, gifts, and personal items will fit comfortably. Tell the reservations team what the group is carrying. Luggage and gear fit should be confirmed separately whenever airport arrivals, welcome bags, decor, or vendor materials are part of the ride."]},{heading:`How should hotel pickup waves for ${e.name} be organized?`,answer:`Plan at least 2 pickup waves for ${e.name} when guests are split across hotels or readiness times: an early family and wedding-party movement with schedule padding, followed by the main guest shuttle, while one named transportation lead confirms each vehicle's manifest instead of asking chauffeurs to reconcile a changing group chat.`,paragraphs:[`${e.hotelPlan} Start with exact hotel names and street addresses, because similarly named Scottsdale resorts can appear in search results. List a lobby contact for each property and tell guests whether they should wait inside or at a venue-approved pickup point. A chauffeur should never have to circle a resort while a guest finishes packing upstairs.`,"For each wave, publish one ready time and one departure time. The ready time is when guests are fully dressed, carrying everything they need, and physically present at the pickup point. The departure time is when the vehicle rolls. Put buffer between that departure and the ceremony's guest-seating deadline, not merely the invitation time, so normal loading and traffic variation do not consume the entire margin.",e.venueSpecific[2],"A transportation lead should check names against the manifest, call the designated guest contact when someone is missing, and make the go-or-hold decision. That role should not sit with the couple. Share the lead's number with the reservations team before service and choose a backup who can answer while the primary person is in the ceremony."]},{heading:`Where should a shuttle drop guests at ${e.name}?`,answer:`Use 1 venue-confirmed arrival point for each scheduled wave, written exactly as the ${e.name} event team provides it; where the venue publishes no wedding shuttle lane we confirm the live one with them instead of naming a gate, because a guessed entrance sends a full vehicle into the wrong traffic pattern.`,paragraphs:["Send the venue the vehicle type, approximate length, arrival window, and number of passengers. Ask whether the vehicle may dwell while guests unload, whether a coordinator will meet it, and whether the same point is used after the reception. If the answer changes by event space or time of day, place both instructions in the schedule with a clear effective time.","The chauffeur follows current property signage, traffic staff, and venue instructions on arrival. A static web guide cannot see a temporary barricade, private event, construction change, or emergency route. Guests should remain seated until the vehicle is in the approved unloading position, then move together toward the venue contact instead of scattering across a drive.",e.venueSpecific[3],"For older guests or anyone using a mobility device, ask the venue about its accessible route before assigning the vehicle. Vehicle capacity and property accessibility are different questions. Tell the reservations team about boarding needs early so the proposed fleet can be checked; never assume that a capacity number by itself confirms an accessible boarding setup."]},{heading:`How should ${e.name} wedding groups use separate movements?`,answer:`Separate a ${e.name} wedding day into 3 manifests when schedules differ: wedding party, immediate family, and general guests, because one all-purpose shuttle can be delayed by portraits or pre-ceremony duties while another group still needs to reach its seating time, hotel, rehearsal meal, or reception entrance.`,paragraphs:["The wedding party often carries garments, flowers, personal items, and timing responsibilities that the general guest group does not. Give that vehicle a direct contact who understands photography and ceremony cues. If partners are getting ready at different locations, write each movement as its own trip rather than describing the day as a round trip with several implied stops.","Immediate family may need a later pre-ceremony pickup and an earlier return after formal photographs. General guests benefit from the simplest possible instruction: one pickup place, one ready time, and one venue arrival. Keeping those flows separate makes the service easier to understand and gives the planner a clean way to adjust one group without rewriting every rider's plan.",e.venueSpecific[4],"If the ceremony and reception are in different spaces on the same property, confirm whether guests walk or require a vehicle transfer. Do not assume the distance or route from a property map. If off-property movement is required, schedule it explicitly and verify that every guest who arrived by shuttle also has a seat for the next leg."]},{heading:`What is the best end-of-night return plan from ${e.name}?`,answer:`Schedule 2 or 3 return windows from ${e.name} instead of one final departure: an early option for families, a primary option after major reception moments, and a last sweep after the contracted end, with every rider told which hotels are served and who authorizes an unscheduled stop.`,paragraphs:["Return demand is rarely even. Some guests want to leave after dinner, while others stay through the final song. A single departure can either strand early riders or leave a vehicle idle for hours. Staggered waves give guests a clear choice and let the planner protect the final pickup without turning the chauffeur into an on-demand dispatcher.","Write a destination list for every return wave. If multiple hotels are served, order them before the day and tell guests that the shuttle is not a private car making individual address changes. The transportation lead should record anyone who switches waves so the final sweep does not wait for a guest who already left.",e.venueSpecific[5],"Confirm where the vehicle may wait and when it should approach the pickup point. At properties with active resort traffic, arriving too early can be as disruptive as arriving late. The driver and venue contact should have each other's current instructions through the transportation lead, while guests receive a simple meeting-place description approved by the venue."]},{heading:`When should ${e.name} wedding transportation be reserved?`,answer:`Availability varies by date and by vehicle, so no fixed lead time applies: build the ${e.name} plan in 3 passes — settle the service window and pickup addresses, freeze the first manifest once RSVPs are in, then send a final update after the venue confirms access — and we confirm in writing what is open.`,paragraphs:["The first conversation should cover date, service window, pickup addresses, approximate riders, venue, and the kind of experience the couple wants. The reservations team can then identify a sensible capacity mix. A quote is more useful when it describes actual movements than when it contains only a guest total and a broad request for a shuttle.","At the RSVP checkpoint, reconcile replies with hotel lists and identify children, mobility needs, bulky items, and guests who require the early return. Confirm the venue contact and event-space name. This is also the moment to test every phone number, eliminate duplicate guest names, and make sure the planner's schedule matches the transportation schedule.",e.venueSpecific[6],`The final update should be short: approved addresses, ready and departure times, rider counts, contact hierarchy, and venue instructions. Avoid sending a fresh narrative to the driver on the wedding morning. If a true change occurs, route it through the transportation lead and reservations team so there is one acknowledged version. ${Oa}`]},{heading:`How do couples request a precise ${e.name} shuttle quote?`,answer:`A useful ${e.name} quote request includes 7 items: event date, contracted space, every pickup address, first pickup time, final return time, rider count by wave, and a transportation contact; send those details plus special boarding considerations to the reservations team at ${C} or ${E}.`,paragraphs:["Published rates provide the starting point, but the right schedule still depends on time and routing. Tell the reservations team whether the vehicle remains with the group, returns for later waves, or performs only defined transfers. Mention any airport luggage, coolers, decor, mobility devices, or oversized personal items so fit can be confirmed before a vehicle is selected.",`Ask the venue for written transportation instructions and attach them to the request. For ${e.name}, include the contracted event space and the venue coordinator's name. If the venue has not yet finalized access, say that clearly; the quote can use a planning assumption while the final dispatch sheet waits for verified directions.`,e.venueSpecific[7],"Compare the proposed seat count with the manifest, not with a rounded attendance number. A slightly larger vehicle can simplify a wave, while two smaller vehicles can protect groups with different timelines. The best answer is the one that makes the schedule resilient and understandable, not automatically the vehicle with the lowest hourly rate."]},{heading:`What are the most common ${e.name} shuttle questions?`,answer:`Most ${e.name} plans come down to 4 questions: how many people are actually riding, which hotel or home each wave leaves from, what arrival point the venue approves, and how many return times guests need; the answers below give a practical starting point for the planner.`,paragraphs:[]}],faqs:[{question:`Can a shuttle wait at ${e.name} during the wedding?`,answer:`Waiting depends on the venue's current instructions, the contracted service plan, and available staging. Ask the ${e.name} event team where a vehicle may stand, then give that direction to the reservations team before dispatch.`},{question:"Should every invited guest receive a shuttle seat?",answer:"No. Count guests who commit to each pickup and return wave, then add operational margin. Guests staying on property or driving themselves should not inflate the vehicle count."},{question:"Can airport arrivals and the wedding shuttle use the same vehicle?",answer:"Sometimes, but only when flight timing, luggage fit, and the wedding schedule align. Keep airport movements separate on the itinerary so a delayed flight cannot quietly endanger a ceremony departure."},{question:"Who should communicate with the chauffeur?",answer:"Choose one transportation lead and one backup. The couple should not manage guest calls or access changes during portraits, the ceremony, or the reception."}],links:Ro,sources:[{label:e.sourceLabel,href:e.sourceUrl},...e.secondarySource?[e.secondarySource]:[]]}}const Mo=[Ye({path:"/guides/venues/el-chorro",name:"El Chorro",address:"5550 East Lincoln Drive, Paradise Valley, Arizona 85253",venueFacts:"Its official weddings page presents multiple indoor and outdoor event spaces between Camelback and Mummy mountains.",arrivalNote:"The official site publishes the Lincoln Drive address but does not publish a named wedding-shuttle gate, so the exact unload point must come from the venue team.",hotelPlan:"Guests may be staying across Paradise Valley and Scottsdale rather than at the venue itself, so hotel consolidation matters.",sourceLabel:"El Chorro weddings and events",sourceUrl:"https://elchorro.com/weddings-and-events/",venueSpecific:["El Chorro identifies eight event spaces on its wedding materials, with indoor and outdoor choices between Camelback and Mummy mountains. Put the contracted space on every chauffeur note; the Lincoln Drive street address gets the vehicle to the property, but the space name gives the venue team the context needed to confirm the final approach.","Eight named spaces can support very different guest plans, so count riders for the actual ceremony and reception layout instead of treating El Chorro as one generic room. Ask whether the contracted spaces share an arrival area and whether guests move on foot between them before deciding that one capacity plan covers the entire celebration.","El Chorro is not a lodging property, so every guest who uses the shuttle begins somewhere else. Consolidate Paradise Valley and Scottsdale hotel riders into a small number of documented pickups, then keep private-home pickups separate when their timing or access instructions differ. This avoids turning the Lincoln Drive arrival into the first moment the manifest is reconciled.","For the Lincoln Drive approach, the useful venue answer is the approved wedding unload point for the contracted space, not a guessed entrance based on a public map. Give El Chorro the vehicle type and arrival window, record the response verbatim, and ask whether the same point remains available when the reception ends.","A wedding party assigned to one of El Chorro’s outdoor settings may have a different readiness cue from guests entering an indoor event space. Tie each manifest to a named coordinator cue and space, then state whether portraits occur before or after that movement. The chauffeur needs a departure instruction, not the entire photography schedule.","Return waves should name the destination hotels before the first vehicle approaches El Chorro. If guests are split between Paradise Valley and Scottsdale, group compatible stops and publish which wave serves each one. The last sweep should be tied to the contracted event end and the pickup instruction the venue confirms for that evening.","At the 14-day review, repeat the full El Chorro address and every contracted space name with the venue contact. Ask whether another event affects the approach, where the transportation lead should assemble riders, and when a vehicle may be called forward. Record changes in the final schedule rather than relying on an earlier email thread.","An El Chorro quote request is strongest when it names the eight-space choice actually booked, the hotel clusters, and the guest count for each direction. Include whether the ceremony and reception use different spaces and whether any passenger needs extra boarding time. Those details matter more than sending the reservations team the invitation total alone."]}),Ye({path:"/guides/venues/clayton-house",name:"The Clayton House",address:"3719 North 75th Street, Scottsdale, Arizona 85251",venueFacts:"The official tourism listing describes separate event rooms, covered patios, and in-house catering and bar service.",arrivalNote:"The official tourism listing publishes the 75th Street address but does not name a wedding-shuttle curb or gate; confirm the approved unloading position with the venue.",hotelPlan:"Downtown hotels may look close on a map, yet formalwear, weather, and traffic make a scheduled pickup more dependable than asking guests to improvise.",sourceLabel:"Clayton House official venue page",sourceUrl:"https://www.wedgewoodweddings.com/venues/clayton-house",venueSpecific:["The Clayton House describes two indoor-outdoor event spaces plus in-house catering and bar service at its 75th Street property. Name the booked space in the transportation schedule so the venue can distinguish the wedding movement from a general arrival, especially when both parts of the property may be active.","A public address does not establish a shuttle loading position. Treat directions and commercial passenger unloading as separate questions: send the proposed vehicle type to The Clayton House, ask where it should approach, and keep unused seats available when formalwear, gifts, or mobility equipment affect the practical load.","Downtown Scottsdale lodging can produce several small guest clusters. Combine riders by exact hotel and ready time instead of scheduling an individual stop for every room block. A concise route into 3719 North 75th Street gives the transportation lead a realistic headcount at each pickup and leaves the chauffeur with a clear final destination.","Use the published 75th Street address as the routing anchor, then obtain the event team’s exact unloading instruction. Do not infer that the parking entrance, a nearby curb, or the closest door is approved for a larger vehicle. The venue contact should also state whether guests can remain under cover while waiting for a return wave.","Because The Clayton House offers two indoor-outdoor spaces, confirm whether wedding-party portraits, family arrival, and general guest seating all begin from the same side of the property. If they do not, write separate movements and contacts. A single vehicle can still serve multiple groups, but only when each handoff is explicit.","Do not treat nearby public parking as permission for a chauffeured vehicle to stage through the reception. Ask where an empty vehicle may wait, if waiting is allowed, and how the transportation lead should call it forward. That answer determines whether early and final return waves use one continuous booking or separate movements.","During the final review, confirm the event-space name, 75th Street address, authorized approach, and end-of-night assembly point with The Clayton House. Downtown activity can change the practical route even when the street address stays the same, so the current venue instruction and live traffic direction belong on the final chauffeur sheet.","For a Clayton House quote, list each event room only if the wedding actually uses it. Include downtown hotel names, private-home stops, and return-wave destinations, then attach the venue’s loading response. This gives the reservations team enough detail to compare one larger vehicle with coordinated smaller vehicles without assuming that a public address solves shuttle access."]}),Ye({path:"/guides/venues/fairmont-scottsdale-princess",name:"Fairmont Scottsdale Princess",address:"7575 East Princess Drive, Scottsdale, Arizona 85255",venueFacts:"The official weddings page describes indoor and outdoor wedding settings and an on-property wedding planner.",arrivalNote:"Fairmont publishes driving directions that end at the lobby entrance; because a private event space may use different instructions, confirm whether the wedding shuttle should follow that public arrival route.",hotelPlan:"On-property guests and off-property guests need separate counts, and large resort grounds make the named event space especially important on the driver sheet.",sourceLabel:"Fairmont Scottsdale Princess weddings",sourceUrl:"https://www.fairmont.com/en/hotels/scottsdale/fairmont-scottsdale-princess/weddings.html",secondarySource:{label:"Fairmont location and public arrival directions",href:"https://www.fairmont.com/en/hotels/scottsdale/fairmont-scottsdale-princess/location-contact.html"},venueSpecific:["Fairmont’s public driving directions end with the lobby entrance on the right, while its wedding page describes multiple indoor and outdoor settings. Put both the contracted event space and the venue’s private-event arrival instruction on the schedule; a lobby route is useful context, but it is not automatically the wedding shuttle route.","Separate Fairmont guests staying at the resort from riders coming from other hotels or homes before choosing capacity. On-property guests may not need a seat for every movement, while an off-property party may need a fully assigned wave. The manifest should reflect committed riders rather than the total number of rooms or reception guests.","For an on-property resort wedding, the most important hotel-wave question is which guests are truly boarding off property. Give each outside hotel an exact lobby or approved pickup instruction, then create a separate note for any Fairmont guest who needs transportation within the wedding plan. Do not mix walkers into the shuttle count simply for symmetry.","Ask the Fairmont wedding planner whether the vehicle follows the published lobby approach or a different route for the contracted setting. Record the answer with the event-space name and arrival window. If staff direct the chauffeur elsewhere on the day, that current instruction controls and the transportation lead should update waiting guests before they move.","A wedding party using a Fairmont lawn or outdoor setting may have a different cue from guests entering a ballroom or other indoor space. Keep the getting-ready location and event-space name beside each movement. That prevents the driver sheet from reducing a large resort plan to the property address and one ambiguous arrival time.","For Fairmont return waves, identify which riders remain at the resort and which leave for off-property lodging. Publish only the destinations served by each departure. The transportation lead should assemble outbound guests at the venue-approved point and call the vehicle forward when the group is complete, rather than using the public lobby as an assumed waiting area.","Use the on-property wedding planner named in Fairmont’s materials as the source for the final private-event approach. Recheck the public directions and the booked-space instruction 14 days out, then confirm them again in the final update. A resort map can orient the group, but a named current instruction is what belongs in dispatch.","A Fairmont quote request should distinguish resort guests, off-property hotel riders, wedding-party movements, and end-of-night destinations. Add the contracted indoor or outdoor setting and state whether the public lobby route has been approved for the shuttle. That detail lets the reservations team price real movements instead of assuming every guest starts outside the resort."]}),Ye({path:"/guides/venues/sanctuary-camelback-mountain",name:"Sanctuary Camelback Mountain",address:"5700 East McDonald Drive, Paradise Valley, Arizona 85253",venueFacts:"Its official wedding site describes mountainside indoor and outdoor settings, including lawns, terraces, a ballroom, and intimate villa options.",arrivalNote:"Sanctuary publishes its McDonald Drive address but does not name a public wedding-shuttle gate; use the event team's instructions for the booked space and arrival window.",hotelPlan:"Some guests may be staying in resort casitas or villas while others arrive from Scottsdale hotels, so identify who truly needs an off-property shuttle.",sourceLabel:"Sanctuary Camelback Mountain weddings",sourceUrl:"https://www.sanctuaryaz.com/weddings",secondarySource:{label:"Sanctuary contact and address",href:"https://www.sanctuaryaz.com/contact"},venueSpecific:["Sanctuary’s wedding materials describe lawns, terraces, a ballroom, and intimate villa options at the McDonald Drive property. Use the exact contracted setting in the vehicle notes because “Sanctuary” alone does not tell the venue team which guest path or arrival instruction applies to this wedding.","Count resort guests and off-property riders separately before selecting a vehicle for Sanctuary. A couple using a villa setting may have a smaller movement than a ballroom celebration, and some guests may already be on site. Capacity planning should follow the manifest for each wave, not a broad estimate based on the venue’s range of settings.","Paradise Valley and Scottsdale hotel pickups should be grouped by readiness and destination, while anyone already at Sanctuary remains off the inbound shuttle manifest unless a movement is specifically planned. Give each hotel one approved waiting point and keep the McDonald Drive venue arrival as the final instruction, not another place for guests to negotiate where to meet.","Sanctuary publishes 5700 East McDonald Drive but no permanent public wedding-shuttle gate. Ask the event team where the assigned vehicle should unload for the booked lawn, terrace, ballroom, or villa setting. Also ask whether the return pickup uses that same point, because arrival and late-evening traffic patterns may be handled differently.","When the wedding uses more than one Sanctuary setting, write whether guests walk between them or board for another movement. Do not infer the route or distance from a resort illustration. The wedding party may need a separate cue for portraits or preparation, while general guests should receive one simple ready time and venue-approved arrival instruction.","A Sanctuary return plan should separate guests staying on property from those returning to Paradise Valley or Scottsdale lodging. The early wave can serve family or guests leaving after dinner, while the final sweep follows the contracted event end. Each wave needs its own destination list and a venue-confirmed assembly point.","At the final planning review, repeat the booked Sanctuary setting, McDonald Drive address, arrival point, return point, and resort contact. If the ceremony moves between an outdoor and indoor option, ask whether the transportation instruction changes. Record only the answer that affects vehicle movement; do not burden the chauffeur with unrelated event details.","For a Sanctuary quote, include the contracted lawn, terrace, ballroom, or villa only as the venue identifies it, plus rider counts from each hotel and the number staying on property. Note any guest who needs extra boarding time. This creates a route-based request rather than a generic resort wedding inquiry."]}),Ye({path:"/guides/venues/grand-hyatt-scottsdale-resort",name:"Grand Hyatt Scottsdale Resort",address:"7500 East Doubletree Ranch Road, Scottsdale, Arizona 85258",venueFacts:"Hyatt identifies the property as Grand Hyatt Scottsdale Resort and describes renovated ballrooms plus indoor and outdoor function space.",arrivalNote:"Hyatt publishes the Doubletree Ranch Road address but not a public wedding-shuttle gate on its event page; the booked space and arrival point should be confirmed with the resort team.",hotelPlan:"The property itself may house many guests, so separate in-resort walkers from riders coming from other hotels, homes, or the airport.",sourceLabel:"Hyatt announcement of the Grand Hyatt Scottsdale Resort name and event spaces",sourceUrl:"https://newsroom.hyatt.com/2024november11GrandHyattScottsdale",venueSpecific:["Hyatt now identifies the property as Grand Hyatt Scottsdale Resort and publishes 7500 East Doubletree Ranch Road. Use that current name on every manifest, map pin, and chauffeur note; older planning documents may still contain the former resort name, so the transportation lead should replace it before details are distributed.","Grand Hyatt lists ballrooms, lawns, gardens, and other event settings, making the contracted space essential to capacity and timing discussions. Separate guests staying at the resort from those riding in from other locations, then choose vehicles for the actual waves. The full reception attendance is not a substitute for that movement-by-movement count.","Begin hotel-wave planning by removing Grand Hyatt guests who will not ride inbound, then group off-property Scottsdale or Paradise Valley lodging by exact address and ready time. If airport luggage remains with any arriving guest, identify that movement separately. A wedding shuttle should not discover at the first pickup that a local guest wave also carries travel bags.","The Doubletree Ranch Road address routes the vehicle to Grand Hyatt, but Hyatt’s event page does not publish a wedding-shuttle gate. Ask the resort team for the approved arrival tied to the booked ballroom, lawn, or garden. Record whether the same location is used after the reception and whether a vehicle may wait nearby.","If the Grand Hyatt ceremony and reception use different settings, ask whether guests walk between them and whether the wedding party moves on a separate schedule. Keep any vehicle transfer as an explicit itinerary line with a rider count. Do not assume that every change of event space creates a transportation need or that every guest follows the wedding party.","For the return, divide guests who stay at Grand Hyatt from riders returning to other hotels, homes, or an airport-area property. A resort guest should not occupy a seat simply because their name appears on the reception list. Label each outbound wave by destination and have the transportation lead confirm who has already returned to a room.","At 14 days, verify the current Grand Hyatt name, Doubletree Ranch Road address, contracted setting, and vehicle instructions with the resort contact. Remove the former property name from guest messages unless it is needed to clarify an old document. The final update should use one naming convention so guests and chauffeurs search for the same destination.","A Grand Hyatt quote request should state how many guests stay at the resort, which off-property hotels need service, whether the ceremony and reception use separate settings, and the final return destinations. Attach the resort’s approved vehicle approach. These specifics let the reservations team evaluate the schedule without relying on the former name or a generic resort entrance."]})],No={updatedAt:"2026-09-24",path:"/guides/scottsdale-bachelorette-weekend",title:"Scottsdale Bachelorette Party Weekend",description:"Plan a three-day Scottsdale bachelorette weekend with an Old Town crawl, published Sprinter pricing, airport transfers, and one mobile headquarters.",metaDescription:"A three-day plan: the Old Town crawl, group sizing and the nightly return",h1:"Scottsdale bachelorette party weekend: a practical 3-day itinerary",eyebrow:"Three-day Scottsdale itinerary",intro:"Scottsdale Sprinters plans a strong Scottsdale bachelorette weekend with one main plan per day, one transportation lead, and enough open time for the group to reset. This itinerary keeps Old Town stops walkable, uses a Sprinter as the mobile headquarters for longer moves, and prices the shared ride from published rates.",fleetTable:!0,itinerary:[{day:"Day 1",title:"Arrive, settle in, and start with dinner",plan:"Consolidate airport arrivals, stock the house or hotel, leave recovery time, and use one dinner reservation as the first fixed point."},{day:"Day 2",title:"Pool time, reset, and Old Town crawl",plan:"Keep the morning flexible, set one group-ready deadline, and stage the Sprinter before the first Old Town stop."},{day:"Day 3",title:"Brunch, a lighter activity, and departures",plan:"Choose one low-friction group activity, confirm luggage before pickup, and split airport waves by flight time."}],crawlStops:[{number:1,name:"A booked dinner anchor in Old Town",note:"One confirmed meal reservation before the entertainment-district portion of the night; confirm the address, time and reservation name directly with the restaurant."},{number:2,name:"The Entertainment District blocks",note:"The late venues cluster within a few blocks of Scottsdale Road and Stetson Drive; confirm current entry, cover and reservation details with each one directly."},{number:3,name:"One main celebration stop",note:"Choose a single venue for the centre of the night rather than a list, and check its current event calendar and dress guidance directly."},{number:4,name:"A quieter regrouping block",note:"The Fifth Avenue and Marshall Way shopping streets sit a short walk from the district and work as a meeting point when a line is long."},{number:5,name:"The late pickup point",note:"A lawful meeting place the chauffeur can reach, agreed before anyone leaves the last venue and sent to the whole group in writing."}],sections:[{heading:"What is the best shape for a 3-day Scottsdale bachelorette weekend?",answer:"Build the weekend around 3 anchors—arrival dinner, one main Old Town celebration, and a relaxed farewell—then protect at least 2 open blocks for pool time, getting ready, meals, and recovery, because a minute-by-minute schedule usually breaks as soon as one flight or reservation shifts.",paragraphs:["Day 1 should feel easy. Group arriving flights into a small number of airport pickup windows, give everyone time to check in, and make dinner the only hard deadline. Put the address, reservation name, ready time, and clothing plan in one shared note. Guests who land late should have a clear way to join without holding the entire group at the airport.","Day 2 carries the biggest celebration. Keep the morning optional, choose one pool or daytime reservation if the group wants it, then create a real reset window before Old Town. The transportation plan begins at the house or hotel, not at the first bar. Everyone boards together with charged phones, identification, and the items they need for the full evening.","Day 3 works best at a slower tempo. Brunch and one flexible activity give the group a final shared memory without creating another complex transfer. Organize luggage before the vehicle arrives and split airport departures by terminal timing rather than friendship groups. The person with the earliest flight should not wait through a late group brunch."]},{heading:"How does a Sprinter work as the weekend’s mobile headquarters?",answer:"A single Sprinter can serve as mobile headquarters for 8 to 16 guests by keeping the group on one departure clock, giving everyone the same pickup message, and creating a consistent regrouping point between the house, dinner, Old Town, and the final return without relying on several separate cars.",paragraphs:["“Mobile headquarters” means the transportation plan has one accountable schedule and one known vehicle; it does not mean the vehicle can wait anywhere or store unlimited belongings. The transportation lead keeps the manifest, confirms when everyone is aboard, and communicates changes to the reservations team. Guests receive the simple version: where to stand, when to be ready, and what return wave they chose.","Choose capacity from the fleet table, then discuss the real load. A nominal seat count does not describe dresses, coolers, welcome bags, airport luggage, or mobility devices. The reservations team can help check the proposed vehicle against those details. For a nightlife-only movement, a party-oriented Sprinter may fit the mood; for airport transfers, luggage can change the practical answer.","The vehicle is most valuable on the longer or less walkable legs: airport to lodging, lodging to Old Town, a planned daytime destination, and the final ride home. Inside a compact Old Town crawl, walking between confirmed nearby stops can be simpler than repeatedly loading the group. The chauffeur should use only legal, currently available loading places."]},{heading:"What does a Scottsdale Sprinter cost per person?",answer:`For 13 guests sharing the ${o["ultra-luxury-party-sprinter-scottsdale"]} for 5 billed hours, the published ${to("ultra-luxury-party-sprinter-scottsdale")}-per-hour rate works out to about ${ao("ultra-luxury-party-sprinter-scottsdale",5,13)} per person before tax for the shared ride; the live total depends on the selected vehicle, service duration, and confirmed itinerary.`,paragraphs:["The calculation is deliberately transparent: the published hourly rate is multiplied by 5 billed hours and divided by 13 riders. If fewer people split the same vehicle, the per-person amount rises; if the group chooses a different vehicle or service window, it changes. Use the fleet table as a planning comparison, then request a quote for the actual route.","Do not compare a group vehicle with a single app estimate shown before a surge, a stop, or a post-event pickup. The useful comparison includes how many separate cars the group would need, whether everyone departs together, and who is responsible for finding missing riders. A shared hourly plan buys coordination as well as seats.","The itinerary should separate airport service from the nightlife service when the timing or luggage profile differs. A vehicle that fits the celebration may not be the best airport loadout. Send flight waves and luggage notes to the reservations team so each portion can be priced against the right vehicle rather than forcing one assumption across the entire weekend."]},{heading:"How should a practical Old Town crawl be sequenced?",answer:"Sequence the night in 3 moves—a booked dinner anchor, one main stop inside the Entertainment District, and a late pickup point the chauffeur can legally reach—then confirm reservations, dress rules, event programming, and entry conditions directly with each venue, because those conditions change without notice.",paragraphs:["The numbered route below is a planning sequence, not a promise of admission or a claim that every stop belongs in one night. A dinner reservation works as the meal anchor when booked directly. The late venues sit in the Entertainment District and are listed in Old Town Scottsdale’s official nightlife directory. No district claim or operating hours are assigned to any stop here.","Book the most important reservation first, then build around it. If the group cares about dinner or a particular evening’s programming, confirm that directly with the venue. Keep confirmation emails and the reservation name in the shared plan. A transportation booking does not create venue admission, skip a line, or override dress and identification requirements.","Designate a regrouping point before entering a loud venue. The group should know what happens if someone leaves early or cannot be reached. Do not ask a chauffeur to stop in an unapproved travel lane while the group decides. The transportation lead should call the movement only after guests are together and the driver confirms the legal pickup position."]},{heading:"How should the Old Town pickup and return be planned?",answer:"Use 2 written meeting points: a venue-confirmed arrival location and a separate late-night pickup location that the chauffeur can legally reach, then set one primary departure time plus a backup contact, because crowded streets and changing traffic controls make an improvised curbside search unreliable.",paragraphs:["Old Town is compact, but the entertainment district can be busy. The exact pickup point should be confirmed on the service day based on current traffic and venue instructions. This guide does not invent a club gate or claim a permanent shuttle lane. Guests should expect a short walk to a lawful meeting point if streets are restricted or congested.","Share a map pin only after the chauffeur or dispatch contact has confirmed it. A pin dropped by a guest from inside a building can land on an alley, patio, or wrong side of the block. The transportation lead should send the final location to the group and collect everyone there before calling the driver forward.","Choose the return rule before the night begins. If the group books one final departure, say clearly that leaving earlier requires a separate plan. If two waves are scheduled, assign riders in advance and record switches. The bride should never be the person counting heads on a crowded sidewalk while also trying to enjoy the celebration."]},{heading:"What should the group pack, assign, and confirm?",answer:"Give 1 person the master itinerary and assign 3 backups—lodging contact, reservation contact, and transportation contact—while every guest carries identification, a charged phone, the lodging address, and weather-appropriate basics, so one lost device or delayed guest does not stop the entire weekend plan.",paragraphs:["Keep the master itinerary short enough to use. It should show addresses, reservation names, ready times, departure times, and the transportation lead. Put optional activities in a separate section so guests can distinguish the fixed plan from suggestions. Avoid a long group-chat thread as the only source of truth; important information disappears quickly once travel begins.","For airport day, label bags and tell the reservations team the real luggage count. For nightlife, reduce what guests carry and confirm each venue’s current bag rules directly. Do not leave valuables or essential medication in a vehicle on the assumption that the same vehicle will remain in the same place all night.","Scottsdale conditions vary by season and time of day. Check an official forecast close to the weekend and plan water, sun protection, or a layer as appropriate. The group should also agree on a buddy system and a simple decision rule: no one changes venue alone without telling the transportation lead or their assigned buddy."]},{heading:"When should the weekend transportation be booked?",answer:"Availability varies by date and by vehicle, so no fixed lead time applies: work the manifest in 3 passes — confirm the flight waves once the group has booked flights, recheck lodging and venue details as they are fixed, then send the final passenger list 48 hours before service.",paragraphs:["Start with the pieces that are unlikely to change: travel dates, lodging, the main celebration night, estimated group size, and desired service window. The reservations team can recommend a fleet option from those facts. You do not need every brunch selected before asking, but you do need honest timing and a realistic pickup area.","Once flights are booked, collect them in a spreadsheet and group arrivals by a useful window. Confirm the exact lodging address, including unit or building instructions that the property permits you to share. Recheck every major venue reservation and current entry guidance. This is the point to decide whether one airport vehicle can serve everyone or separate waves are necessary.",`Forty-eight hours out, send a clean operational summary rather than forwarding the whole planning chat. Include named contacts, rider count, luggage note, ready times, addresses, and the confirmed Old Town meeting plan. If something changes afterward, have one person notify the reservations team and wait for acknowledgement before telling the group the plan is final. ${Oa}`]},{heading:"What are the most common bachelorette transportation questions?",answer:"Most groups ask 4 things: whether one Sprinter can cover airport and nightlife service, how per-person pricing is calculated, where an Old Town pickup can happen, and how late changes are handled; the answers below keep those decisions tied to the real manifest and confirmed itinerary.",paragraphs:[]}],faqs:[{question:"Can one vehicle handle the whole weekend?",answer:"It can cover several scheduled movements, but airport luggage, service gaps, and different group sizes may make separate bookings more practical. Share the complete itinerary with the reservations team."},{question:"Does the transportation reservation include club admission?",answer:"No. Venue reservations, admission, identification, dress rules, and event passes are separate. Confirm them directly with each official venue."},{question:"Can the group add stops during the night?",answer:"Ask the reservations team before service and route day-of requests through the transportation lead. A new stop must fit the booked time, legal access, and driver instructions."},{question:"Where does the Sprinter pick up in Old Town?",answer:"The exact lawful meeting point is confirmed for the service plan and current conditions. This guide intentionally does not promise a permanent curb or invented venue gate."}],links:[{href:"/experiences/bachelorette-party",label:"Bachelorette party transportation"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter van rental"},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:"Ultra Luxury Party Sprinter"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport Sprinter service"},{href:"/pricing",label:"Hourly and per-person pricing"}],sources:[{label:"Old Town Scottsdale nightlife directory",href:"https://oldtownscottsdaleaz.com/eat-drink/nightlife/"}]};function Va(e){const t=e.article?`${e.article} ${e.name}`:e.name;return{path:e.path,updatedAt:e.updatedAt,title:e.metaTitle??`${e.name} Transportation Guide | Scottsdale Sprinters`,description:`Plan ${e.name} group transportation with the official date status, published fleet capacities, hotel pickup, arrival, and post-event pickup guidance.`,metaDescription:"Official date status, hotel pickup, venue arrival and the post-event pickup plan",h1:e.h1??`${e.name} group transportation`,eyebrow:e.dateLine,intro:`A dependable ${e.name} ride from Scottsdale Sprinters begins with the official event information, a realistic rider count, and one transportation lead. This guide uses published organizer or venue facts, leaves unannounced details unguessed, and turns the day into a written pickup, arrival, communication and return plan.`,fleetTable:!0,sections:[{heading:`When is ${t}?`,answer:e.dateAnswer,paragraphs:["Use the official source linked below as the date authority. Artist schedules, participating teams, kickoff times, venue hours, and traffic instructions may arrive later than the date itself. Do not build a pickup plan around an unofficial calendar listing. The transportation lead should recheck the organizer page at booking, again as the date approaches, and on the service day.",e.eventSpecific[0],"Publishing early matters because a large-event route needs more than a car reservation. The group may still need admission passes, lodging, a meeting point, and agreement about who rides home. An article published ahead of the event gives planners time to compare vehicle sizes, collect guest commitments, and confirm current access rules without inventing details.","When a date or time remains unannounced, the quote request can still describe the expected city, group size, hotel area, and service pattern. Mark uncertain times as planning placeholders, not confirmed instructions. The reservations team can update the service window once the official organizer publishes the missing information."]},...e.gettingThere?[e.gettingThere]:[],{heading:`Which vehicle size fits a ${e.name} group?`,answer:`For ${t}, compare ${we.length} published capacity bands from ${we[0].capacity} through ${we[we.length-1].capacity} passengers, then choose from the committed rider count and what the group will carry; the largest seat number is not automatically the best choice when people have permitted gear, accessibility needs, or hotel luggage.`,paragraphs:[`The fleet table uses current published information for each displayed name, maximum seated capacity, hourly rate, and minimum. A ${o["executive-sprinter-scottsdale"]} seats ${i["executive-sprinter-scottsdale"]}; a ${o["motorcoach-56"]} seats ${i["motorcoach-56"]}. Larger groups can use multiple coordinated vehicles when one vehicle does not fit the rider count or what guests will carry.`,"Count the riders for each direction. The outbound group may be larger than the return group, especially when some guests camp, stay near the venue, or leave with family. Give every return rider a specific vehicle or wave. “We will decide later” is not a useful manifest when a large event crowd is leaving at once.",e.eventSpecific[1],"Tell the reservations team about permitted personal items before choosing the vehicle. Event bag and chair rules belong to the organizer, and vehicle fit belongs to the operator. Something allowed into the venue may still consume meaningful cabin space. Keep aisles and exits clear, and never use an advertised seat count as a substitute for a real load review."]},{heading:`How should a group arrive at ${e.venue}?`,answer:`Plan 1 documented arrival route to ${e.venue}, with the chauffeur following current event staff, traffic control, and the organizer's published instructions; a saved gate name from an earlier event is not reliable enough for dispatch, so this guide uses only access details supported by an official source.`,paragraphs:[`${e.verifiedAccess} The operational plan should record the venue as ${e.venueAddress}, plus any event-specific permit, lot, or loading instruction supplied for the booked vehicle. If an organizer later publishes a different route, that current instruction replaces the general address.`,e.eventSpecific[2],"Build arrival buffer before the first activity the group cares about, not merely before the headline start. Loading riders, traffic control, security screening, and the walk from the approved unload area all take time. The vehicle cannot bypass public safety instructions, and the group should not ask to unload in a travel lane because the schedule ran tight.","Keep admission passes, identification, and allowed personal items ready before the door opens. The transportation lead counts riders as they leave and identifies the return meeting plan once more. Nobody should assume that the arrival position will remain the pickup position after the event; traffic plans can reverse or move during egress."]},{heading:`What should the ${e.name} itinerary include?`,answer:`Write 7 lines into the ${e.name} itinerary: guest ready time, vehicle departure, venue arrival target, primary contact, official address, post-event meeting instructions, and final roll time, then keep optional meals or gatherings in a separate section so riders can immediately see the commitments that affect transportation.`,paragraphs:[`${e.dayPlan} Turn that outline into clock times only after official hours or kickoff information is available. A useful schedule works backward from the desired arrival, adding expected loading and a conservative traffic allowance. Avoid publishing a universal drive time because origin, closures, day of week, and event operations all change it.`,e.eventSpecific[3],"The ready time is when guests are physically at the pickup point with everything they will take. It is not the time they begin leaving hotel rooms. The transportation lead should arrive earlier, check the manifest, and contact missing riders. Decide in advance who has authority to hold the vehicle and how long the schedule can absorb that hold.","Include one contingency sentence: if the group becomes separated, each rider follows the written meeting instruction and contacts the transportation lead. Do not create multiple competing pins during the event. A simple, approved plan is easier to execute when cellular service is busy and the surrounding streets are controlled."]},{heading:`How should pickup after ${t} work?`,answer:`Use 2 checkpoints after ${t}: the group first gathers at a pedestrian meeting place permitted by venue instructions, then the transportation lead confirms the vehicle’s active pickup point before anyone walks toward it, preventing riders from chasing a moving vehicle through controlled traffic or crowd flow.`,paragraphs:["The chauffeur may be directed away from the arrival location or held until traffic staff release a lane. That is normal large-event operations, not a reason for guests to enter a roadway. The lead stays with the group, keeps a headcount, and waits for a confirmed message about where and when to move.","Set expectations before arrival: the vehicle cannot stop wherever a phone pin lands, and an event's official traffic team controls access. Guests should wear appropriate footwear for the walk they can reasonably expect around a large venue and keep enough phone charge for post-event messages. Anyone leaving separately tells the transportation lead.",e.eventSpecific[4],"For multiple return waves, label vehicles and destinations clearly. A hotel shuttle and a local-home shuttle should not rely on guests recognizing a driver in a crowd. Use the vehicle name, lead name, and destination list. The final sweep verifies the manifest before departure rather than waiting on people who changed plans without notice."]},{heading:`How far ahead should ${e.name} transportation be reserved?`,answer:`Availability for ${t} varies by date and by vehicle, so no fixed lead time applies: request a current quote with the rider count, hotel area and service pattern, and the reservations team confirms in writing what is open across the ${we.length} published capacity bands, updating it as official information is announced.`,paragraphs:["The first request needs the event, lodging or pickup area, likely passenger count, desired arrival, and return concept. A group does not need every attendee name to begin, but it should distinguish committed riders from possible riders. The reservations team can compare a single larger vehicle with several coordinated smaller options using current published capacities.","Once the group is committed, close the manifest and collect mobility needs, allowed gear, and destination choices. Confirm the official event status and make sure every rider has an admission plan independent of transportation. If the organizer has not announced an important detail, mark it open and assign one person to monitor the official source.",e.eventSpecific[5],"During the final 48 hours, verify addresses, contact numbers, service times, and current venue directions. Send one final summary to riders. If official instructions change on the day, the chauffeur follows traffic personnel and the transportation lead relays the update; the group should not treat an older screenshot as authority over current controls."]},{heading:`How is ${e.name} transportation priced per person?`,answer:`For 12 ${e.name} riders sharing the ${o["executive-sprinter-scottsdale"]} across 5 billed hours, the published ${to("executive-sprinter-scottsdale")}-per-hour rate is about ${ao("executive-sprinter-scottsdale",5,12)} per person before tax for the complete shared ride; actual pricing changes with the vehicle, duration, itinerary, and confirmed service plan.`,paragraphs:["That example is arithmetic, not a flat event fare: hourly rate multiplied by billed hours, divided by riders. It gives a group a common basis for comparison while staying aligned with the published rate. If only ten people ride, divide across ten. If the group needs a larger vehicle or a longer service window, request the matching calculation.","A complete plan may include a continuous vehicle, separated inbound and outbound transfers, or several hotel waves. Each structure uses time differently. Describe the actual service pattern when asking for a quote instead of requesting “round trip” and leaving a many-hour gap unexplained. The reservations team can then price the schedule that the group expects.",e.eventSpecific[6],"Per-person math is most useful after the rider list stabilizes. Name one person to collect shares and one person to manage the manifest; they can be the same person, but neither job should fall to the chauffeur. The transportation service moves the confirmed group while the lead owns internal guest decisions."]},{heading:`What are the most common ${e.name} transportation questions?`,answer:`Most ${e.name} groups need 4 answers before booking: the official date status, the number of committed riders, the venue's current vehicle instructions, and the return meeting process; the FAQ below addresses those points without promising an unpublished time, access route, parking privilege, or gate.`,paragraphs:[]}],faqs:[...e.faqs??[],{question:`Does a transportation booking include ${e.name} admission?`,answer:"No. Admission passes, wristbands, parking credentials, and venue entry are separate. Purchase and verify them only through the event’s official channels."},{question:"Can the vehicle wait next to the venue?",answer:"Only where current event operations permit it. Staging and pickup instructions can change, so the chauffeur follows venue staff and the transportation lead shares the confirmed meeting plan."},{question:"Can a group bring chairs, coolers, or bags?",answer:"Check the organizer’s current allowed-items policy first, then tell the reservations team exactly what the group will carry so vehicle fit can be reviewed."},{question:"What if the official event time changes?",answer:"Have the transportation lead contact the reservations team promptly. A revised service window is not assumed until the change is acknowledged and the updated plan is confirmed."}],links:[...e.links,{href:"/fleet",label:"Fleet capacities"},{href:"/pricing",label:"Published hourly pricing"}],sources:[e.source,e.accessSource,...e.additionalSources??[]]}}const Wo=[Va({updatedAt:"2026-09-24",path:"/guides/country-thunder-transportation",name:"Country Thunder Arizona",titleName:"Country Thunder Arizona 2027",dateLine:"Official dates: April 8–11, 2027",dateAnswer:"Country Thunder Arizona is officially scheduled for April 8–11, 2027—4 festival days at AZ Talio Ranch in Florence—and the organizer says 2027 hours will be announced closer to the festival, so build transportation around the published dates but wait for official daily times before locking departures.",venue:"AZ Talio Ranch",venueAddress:"20585 East Water Way, Florence, Arizona 85132",verifiedAccess:"Country Thunder’s official information page publishes the ranch address, tells fans to buy parking in advance because onsite parking is limited and not guaranteed on the day, names Stagecoach Express Shuttles as its partner shuttle from Mesa and Apache Junction, and says Uber and Lyft are available in Florence, with pre-booking recommended.",dayPlan:"For a festival day, the outline is hotel pickup, comfort stop if scheduled, venue arrival, a written post-show regrouping process, and the return to the named lodging stops.",gettingThere:{heading:"Where do you park at Country Thunder Arizona, and how do rideshares and shuttles work?",answer:"Country Thunder Arizona tells fans to buy parking in advance because onsite parking at AZ Talio Ranch, 20585 E Water Way in Florence, is limited and not guaranteed on the day; its partner shuttle runs from Mesa and Apache Junction, Uber and Lyft serve Florence with pre-booking advised, and no lot allows tailgating.",paragraphs:["The festival sells its parking online ahead of time. The passes it lists include weekend day parking, a weekend overnight lot, one extra-vehicle pass per campsite, and a camper drop-off pass for an RV delivered by someone without festival admission. Accessible spaces sit at the front of the reserved parking area, across from the reserved entrance; tell the front-gate staff on arrival.","Its parking-lot rules ban tailgating in every lot, reserved, day, ADA, glamping, staff and overnight alike, and ban cooking, grills, amplified sound and drinking games there too. Only vehicles accredited for a lot may enter it, and a vehicle without the right credential can be towed. A group that planned a lot party should plan it for the drive instead.","For rideshare, the festival says Uber and Lyft are available in Florence and recommends pre-booking a ride to guarantee a driver. As of September 24, 2026, its information page names no rideshare zone at the ranch and no drop-off lane for limousines, party buses or charters, so a chauffeur unloads where festival traffic staff direct and follows any instruction the festival publishes later.","The festival’s partner shuttle, Stagecoach Express Shuttles, picks up and drops off in Mesa at 240 West Baseline Road and in Apache Junction at 185 West Apache Trail, booked by phone. It does not start in Scottsdale. From a Scottsdale hotel or home, the ranch is about 63 miles and 66 minutes from Old Town by Google Directions, without festival traffic.","With a chauffeured ride, nobody in the group buys a parking pass or drives home after the headliner. The vehicle picks everyone up at the hotel or home and unloads where staff direct, and when it is booked by the hour the same vehicle brings the group back after the last set. Each festival day is its own booking."]},source:{label:"Country Thunder Arizona official 2027 event page",href:"https://www.countrythunder.com/az"},accessSource:{label:"Country Thunder Arizona official festival information",href:"https://www.countrythunder.com/az-info"},additionalSources:[{label:"Country Thunder festival policies: bags and parking lots",href:"https://www.countrythunder.com/policies"},{label:"Country Thunder Arizona 2027 lineup page",href:"https://www.countrythunder.com/az-lineup"}],links:[{href:"/experiences/country-thunder",label:"Country Thunder transportation experience"},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/fleet/party-bus-28-scottsdale",label:"28-passenger party bus"},{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:"Ultra Luxury Party Sprinter"}],faqs:[{question:"Where is Country Thunder Arizona held?",answer:"At AZ Talio Ranch, 20585 E Water Way, Florence, Arizona 85132. By Google Directions it is about 63 miles and 66 minutes from Old Town Scottsdale, and about 73 miles and 75 minutes from the Fairmont Scottsdale Princess, without festival traffic."},{question:"What are the Country Thunder Arizona 2027 dates?",answer:"Four days: Thursday, April 8; Friday, April 9; Saturday, April 10; and Sunday, April 11, 2027. The festival says the 2027 hours are announced closer to the festival, and its full lineup is still to come."},{question:"What is Country Thunder Arizona?",answer:"A four-day country music festival with camping at AZ Talio Ranch in Florence, run by Country Thunder, which also holds festivals in Wisconsin and Saskatchewan. It runs rain or shine, and the festival guarantees admission bought only from Country Thunder or its official partner."},{question:"What time do the gates open at Country Thunder Arizona?",answer:"The 2027 hours are announced closer to the festival. Last year the concert bowl opened at 3 p.m. on Thursday, 1 p.m. on Friday and Saturday, and 1:30 p.m. on Sunday, and the front gate was open from 9 a.m. to 10 p.m.; anyone arriving after it closed could not drive onto the grounds."},{question:"Can Uber or Lyft drop off at Country Thunder Arizona?",answer:"Uber and Lyft are available in Florence, and the festival recommends pre-booking a ride to guarantee a driver. It names no rideshare zone at the ranch, so drivers follow festival traffic staff. A chauffeured ride booked by the hour covers both ways: the same vehicle takes the group there and brings it home."},{question:"Is there a shuttle to Country Thunder Arizona from Scottsdale?",answer:"The festival’s partner shuttle, Stagecoach Express Shuttles, runs from Mesa and Apache Junction, not Scottsdale. From Scottsdale, a private ride starts at your hotel or home and unloads where festival traffic staff direct; booked by the hour, it brings the group back after the last set."},{question:"Can single-day guests use the campgrounds?",answer:"No. The festival says the campgrounds need full-event admission and that single-day holders do not have access. A campsite is sold for the whole festival, never by the night, and comes with two weekend general admission passes and parking for one vehicle."},{question:"Can we book a ride for all four days?",answer:"Yes, one booking per day. Each festival day is its own ride, with its own pickup time, riders and return, so a group can book Thursday and Saturday only, or all four. The price of each day is shown before you pay."},{question:"Is tailgating allowed at Country Thunder Arizona?",answer:"No. The festival’s parking-lot rules ban tailgating in every lot, along with cooking, grills, amplified sound and drinking games. The pre-party can ride with you instead: our party vehicles carry wet bars, lounge lighting and big sound for the hour-long drive to Florence."},{question:"What can we bring into the concert bowl?",answer:"Clear bags up to 14 by 14 inches, a one-gallon freezer bag or a small clutch; soft lawn chairs without canopies; and one unopened bottle of water per person. Outside food and drinks, coolers, backpacks, glass and umbrellas stay out, and the festival is cashless."}],eventSpecific:["Country Thunder publishes four festival dates but says the 2027 hours will be announced closer to the event. Keep each daily departure in draft until those hours appear, and do not assume that one day’s timing applies to the next. The transportation lead should recheck the Arizona event page for every day the group plans to attend.","A Country Thunder group may carry only items allowed by the festival: into the concert bowl, clear bags up to 14 by 14 inches, soft lawn chairs without canopies and one sealed bottle of water per person, with coolers, backpacks and outside food left behind. Anything the group brings still consumes vehicle space, so count it before selecting from the published capacities. A vehicle that fits riders for a Scottsdale night out may need a different load review for a camping weekend in Florence.","The official destination is AZ Talio Ranch at 20585 East Water Way in Florence, and the festival warns that onsite parking is limited. That statement does not create a commercial drop-off privilege, and the festival’s lot rules admit only vehicles accredited for each lot. Send the current event instructions to the reservations team, document the assigned arrival process, and follow staff direction when the vehicle reaches the ranch.","A four-day Country Thunder plan should be written as four separate service days even if the same group attends each one: Thursday, April 8; Friday, April 9; Saturday, April 10; and Sunday, April 11, 2027. Rider counts, readiness, permitted items, and return choices can change by day. Label every schedule with the correct date so an unannounced daily hour can be inserted later without silently changing another day’s plan.","After each Country Thunder day, the group gathers at one agreed meeting point before anyone walks toward the vehicle, and the lead sends one confirmed message about where the chauffeur is waiting. Last year the front gate was open from 9 a.m. to 10 p.m., and the festival said anyone arriving after it closed could not drive onto the grounds, so plan the late pickup before the headliner starts, not after it ends.","At the 14-day review, check whether Country Thunder has published the 2027 daily hours, the lineup, and any updated transportation or allowed-items information. If a detail remains unannounced, leave it clearly open and tell riders when it will be checked again. The official Arizona page, not a recycled itinerary from an earlier festival, controls the planning facts.","Price each Country Thunder service window from the lodging pickup through the confirmed return plan. Florence is about 66 minutes from Old Town each way by Google Directions, so a festival day booked by the hour runs well past a short example: our ready-made festival days run 10 to 12 hours door to door. A group attending more than one day books each day on its own."]}),Va({updatedAt:"2026-09-24",path:"/guides/fiesta-bowl-transportation",name:"Fiesta Bowl",article:"the",titleName:"Fiesta Bowl 2026-27",metaTitle:"Fiesta Bowl 2026: Parking & Parade",h1:"Fiesta Bowl 2026: parking, the parade and getting there",dateLine:"Official date: December 30, 2026",dateAnswer:"The 2026-27 Vrbo Fiesta Bowl is the CFP quarterfinal on Wednesday, December 30, 2026, at 5:30 pm Arizona time at State Farm Stadium in Glendale, so planners can anchor the service date now and should recheck the official page before confirming pickup times.",venue:"State Farm Stadium",venueAddress:"1 Cardinals Drive, Glendale, Arizona 85305",verifiedAccess:"The official 2026-27 Fiesta Bowl parking map and State Farm Stadium’s directions page both identify the Black Lot for rideshare. That published rideshare point is a planning reference, not a commercial-vehicle assignment; a charter drop-off for this game is announced closer to the date, and traffic staff remain controlling.",dayPlan:"For game day, the outline is hotel pickup, an optional pregame stop only if scheduled, arrival ahead of the 5:30 p.m. Arizona kickoff, a security and admission buffer, a postgame pedestrian regrouping point, and the confirmed vehicle pickup.",source:{label:"College Football Playoff Fiesta Bowl schedule",href:"https://collegefootballplayoff.com/sports/2021/9/7/fiesta-bowl"},accessSource:{label:"State Farm Stadium directions and parking",href:"https://www.statefarmstadium.com/plan-your-visit/directions-parking"},additionalSources:[{label:"Fiesta Sports Foundation 2026-27 CFP dates",href:"https://www.fiestasportsfoundation.org/news/2026/7/9/vrbo-fiesta-bowl-announces-dates-to-host-college-football-playoff-matchups-through-2032.aspx"},{label:"Fiesta Sports Foundation 2026-27 parking map",href:"https://www.fiestasportsfoundation.org/documents/2026/8/14/26-27_VFB_Parking_Map_FINAL.pdf"},{label:"Fiesta Sports Foundation Fiesta Bowl Parade",href:"https://www.fiestasportsfoundation.org/sports/2019/10/22/fiesta-bowl-parade.aspx"}],links:[{href:"/services/scottsdale-executive-minibus-group-shuttle",label:"Scottsdale group shuttle service"},{href:"/services/scottsdale-sprinter-van-rental",label:"Scottsdale Sprinter rental"},{href:"/fleet/executive-mini-bus-26-scottsdale",label:"24-passenger mini bus"},{href:"/guides/venues/state-farm-stadium",label:"State Farm Stadium parking guide"}],faqs:[{question:"Where is the Fiesta Bowl played?",answer:"At State Farm Stadium, 1 Cardinals Drive, Glendale, Arizona 85305. The 2026-27 game is the College Football Playoff quarterfinal."},{question:"What time does the Fiesta Bowl start?",answer:"5:30 p.m. Arizona time on Wednesday, December 30, 2026, the only College Football Playoff game that day. The College Football Playoff lists the same kickoff as 7:30 p.m. Eastern, because Arizona does not observe daylight saving time."},{question:"Where is the best place to park for the Fiesta Bowl?",answer:"The official 2026-27 parking map lists the West, North and East Preferred lots; the East Lot, Lot F and oversized parking; the West Lot, W2, the Great Lawn and the Yellow Lot; and the Black and Blue Lots, on game day only. Last season the lots opened at 11:30 a.m. and closed one hour after the game; this season’s times are announced closer to the date. With a chauffeured ride, nobody in the group parks."},{question:"Where do I buy Fiesta Bowl parking?",answer:"Parking passes are sold through the Fiesta Sports Foundation’s official parking link (SeatGeek), and State Farm Stadium’s lots take cards only."},{question:"How do I buy seats for the Fiesta Bowl?",answer:"From the Fiesta Sports Foundation, which runs the bowl: call 480.350.0911 or use its official website. A ride booking does not include game admission or a parking pass."},{question:"When is the Fiesta Bowl Parade?",answer:"Saturday, January 2, 2027, starting at 10 a.m. It is the 54th annual parade, admission is free, and it comes after the bowl games, not before."},{question:"Where does the Fiesta Bowl Parade go?",answer:"It is a 1.5-mile march through Central Phoenix, starting at North Central Avenue and Montebello Avenue, Phoenix 85012. The full 2027 route, grandstands and street closures are announced closer to the date."},{question:"Can we book a ride to the Fiesta Bowl Parade?",answer:"Yes, as its own ride on Saturday morning. Your chauffeur picks the group up at the hotel or home, drops everyone near the start at North Central Avenue and Montebello Avenue where police and event staff direct, and brings the group back when you are done."}],eventSpecific:["Fiesta Sports Foundation schedules this game as the CFP quarterfinal on Wednesday, December 30, 2026, at 5:30 pm Arizona time at State Farm Stadium. The College Football Playoff lists that same kickoff as 7:30 p.m. ET, because Arizona does not observe daylight saving time. Recheck both official pages if the organizer updates event information.","A Fiesta Bowl group usually needs one count for the stadium arrival and another for the return. Remove anyone using a separate postgame plan before assigning seats, and ask about mobility devices or personal items that affect fit. The vehicle choice should follow those confirmed movements, not the number of people included in a broader game-day gathering.","The official 2026-27 parking map places rideshare on the Black Lot, and the stadium directions page also names the Black Lot south of the stadium for rideshare and family-or-friend pickup. A limo or charter drop-off for this game is announced closer to the date. Use the Black Lot as rideshare orientation until the reservations team confirms the instruction for the booked vehicle.","Build the December 30 itinerary backward from the 5:30 p.m. Arizona kickoff at 1 Cardinals Drive in Glendale. If the group also wants the parade, schedule it as its own service: Saturday, January 2, 2027, at 10 a.m., starting at Central and Montebello in Phoenix, after the game. The 2027 parade route, grandstands, and street closures are announced closer to the date.","Postgame traffic at State Farm Stadium can be directed differently from arrival, so the lead should not send the group toward the Black Lot until the active pickup instruction is confirmed. Assemble first in a safe pedestrian place permitted by venue guidance, complete the headcount, and move only after the vehicle location and route are understood.","Before the Fiesta Bowl, confirm the December 30 date, the 5:30 p.m. Arizona kickoff, hotel addresses, the rider list, and the 2026-27 parking map. During the final 48 hours, recheck the Fiesta Sports Foundation and stadium pages. Live direction from stadium staff takes precedence over a saved map. January 2 parade closures are announced closer to the date.","A Fiesta Bowl quote should state whether the vehicle remains with the group, performs separate inbound and outbound transfers, or serves more than one hotel wave. Price examples based on five hours are comparisons only; the written quote must reflect the December 30 schedule, confirmed stadium access, rider count, and actual time requested."]})],Oo=[No,...Mo,...Wo];function Go(e){return{path:e.path,title:e.h1,metaTitle:e.title,description:e.description,intro:e.intro,metaDescription:e.metaDescription,lastUpdated:e.updatedAt??za,lastUpdatedLabel:A(e.updatedAt??za),sections:e.sections.map(t=>({question:t.heading,answer:t.answer,paragraphs:[...t.paragraphs,...t.bullets??[]]})),faqs:e.faqs,links:e.links,sources:e.sources,eyebrow:e.eyebrow,fleetRows:e.fleetTable?we:void 0,itinerary:e.itinerary,crawlStops:e.crawlStops}}const Lo=Oo.map(Go);function ro(e){const t=Lo.find(a=>a.path===e);if(!t)throw new Error(`[guides] Missing P3 guide: ${e}`);return t}const pd=ro("/guides/fiesta-bowl-transportation"),fd=ro("/guides/country-thunder-transportation"),Ja="2026-09-24",_o="https://www.barrett-jackson.com/2027-scottsdale",Bo="https://calendar.westworldaz.com/scottsdaleaz_westworld/260203141",Bt={collectors:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],crews:["executive-sprinter-scottsdale","limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],corporate:["executive-luxury-bus-29-scottsdale","executive-mini-bus-26-scottsdale","party-bus-28-scottsdale"]},Uo=[...Bt.collectors,...Bt.crews,...Bt.corporate].filter(Oe),_a=Uo.map(e=>({slug:e,name:o[e],capacity:i[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours})),Pe="executive-sprinter-scottsdale",H="maybach-jet-sprinter-scottsdale",St="motorcoach-56",Ya="ultra-luxury-party-sprinter-scottsdale",st="maybach-shuttle-sprinter-8",it="premium-suv-scottsdale",Ho="limo-sprinter-13-scottsdale",qo="limo-sprinter-16-scottsdale",zo="executive-luxury-bus-29-scottsdale",Vo="executive-mini-bus-26-scottsdale",Jo="party-bus-28-scottsdale",Yo=Math.max(..._a.map(e=>e.capacity)),oo="Your chauffeur waits; extra time is billed hourly at the vehicle’s rate — just call or text us to extend.";function Ut(e){return l(s[e].hourlyRateCents)}function Zo(e,t,a){return l(Math.round(s[e].hourlyRateCents*t/a))}function se(e,t,...a){return{question:e,answer:t,paragraphs:a}}const jo=[{label:"Barrett-Jackson 2027 Scottsdale official event page",href:_o},{label:"City of Scottsdale WestWorld calendar, Barrett-Jackson 2027",href:Bo}],Ko=[se("When is Barrett-Jackson Scottsdale 2027?","Barrett-Jackson Scottsdale runs Saturday, January 23 through Sunday, January 31, 2027, which is 9 public days at WestWorld of Scottsdale, with gates, food courts and sponsor displays open from 8:00 a.m. until auction close, plus an invitation-only Opening Night Gala on Friday, January 22, 2027, from 7:00 to 10:00 p.m.","Use the Barrett-Jackson 2027 Scottsdale page as the date authority. The City of Scottsdale WestWorld calendar lists the same Saturday, January 23 through Sunday, January 31 window. The city calendar shows a 10:00 a.m. start; the organizer’s own schedule says gates, food courts and sponsor displays open at 8:00 a.m. until auction close every day of those 9 days. Plan departures from the organizer’s 8:00 a.m. gate time, and recheck that page before the service day.","The Opening Night Gala is Friday, January 22, 2027, from 7:00 to 10:00 p.m., by invitation only in the Auction Arena. It is not a public gate day. A group attending the gala needs its own invitation and a separate service window from the public days that start the next morning. Do not treat January 22 as a day the general-admission crowd can enter.","The organizer says 2027 is 9 days of live auction action, with over 2,000 collector vehicles on display, an exhibitor marketplace, thrill rides and more. Daily auction close times, and which days the docket runs, are announced closer to the date. The venue map, travel notes, featured list and sponsors tab are also announced closer to the date. Mark those as open items rather than copying a prior year’s schedule.","A quote can still name the city, the hotel area, the rider count and whether the group is attending one day or several of the 9. Unannounced close times stay placeholders until Barrett-Jackson publishes them. The reservations team updates the service window from that page, not from a recycled itinerary."),se("Which vehicle fits a Barrett-Jackson collector or hospitality group?",`Collectors and VIP groups lead with the ${o[H]}, which seats ${i[H]}, then the ${o[Ya]}, the ${o[st]} and the ${o[it]}; friends and bidder crews ride the ${o[Pe]} or a Limo Party Sprinter; corporate hosts and big groups take the mini coach, the mini bus or the party bus.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. Collectors and VIP: the ${o[H]}, our pick for Barrett-Jackson, seats ${i[H]} at ${Ut(H)}/hr, then the ${o[Ya]}, the ${o[st]} and the ${o[it]}. Friends and bidder crews: the ${o[Pe]}, the ${o[Ho]} and the ${o[qo]}. Corporate hosts and big groups: the ${o[zo]}, the ${o[Vo]} and the ${o[Jo]}.`,`A VIP party larger than the ${o[H]} rides in two vehicles, one booking each for the same day and times: the ${o[H]} with the ${o[st]} seats ${i[H]+i[st]}, and with the ${o[it]} it seats ${i[H]+i[it]}. The largest vehicle in the table seats ${Yo}; for a bigger party the reservations team quotes two or more vehicles together.`,"Count riders for each direction. A morning arrival at the 8:00 a.m. gate and an evening return after auction close are often different lists. Someone who leaves with another host, or who stays for a later lot, should come off the return manifest before seats are assigned. “We will decide at the arena” is not a useful count when the grounds are releasing traffic.","Tell the reservations team which group is riding, collectors and VIP, a bidder crew or a corporate host party, so the written quote starts from that group’s vehicles.","Tell the reservations team what the group will carry before the vehicle is chosen. The organizer checks every bag and screens guests. A clear bag that the gate allows can still take a seat or an aisle. Seat counts are seated capacities, not a promise that coolers, display materials or extra coats will fit. Coolers are prohibited on the grounds."),se("How does parking work at Barrett-Jackson Scottsdale 2027?","Barrett-Jackson Scottsdale 2027 has plenty of complimentary public parking at WestWorld of Scottsdale, 16601 North Pima Road, with shuttles to and from the main gate and valet for a fee; rideshares use the McDowell Mountain Ranch Road lot, and with a chauffeured ride nobody in the group drives or parks: the chauffeur unloads where event staff direct.","Barrett-Jackson publishes plenty of complimentary public parking. Follow the road signs to parking. Shuttles run to and from the Scottsdale auction’s main gate. Valet parking is available for a fee. That is the official parking plan: complimentary public parking with shuttles, plus paid valet. It is not a statement that a booked commercial vehicle may unload at the arena door.","Rideshare drop-off and pick-up use the parking lot west of Thompson Peak Parkway on McDowell Mountain Ranch Road. Follow the signs to the rideshare area. That lot is the published rideshare point. It is not, by itself, a commercial-vehicle privilege. A chauffeured coach or Sprinter still needs the current event instruction, which for a limo, charter or commercial drop-off is announced closer to the date.","No city traffic plan or Pima Road closure list for 2027 is published yet. Those controls are announced closer to the date. Until then the address is the routing anchor: 16601 North Pima Road, Scottsdale, AZ 85260. If Barrett-Jackson or the city later publishes a credential, a lot or a loading lane, that current instruction replaces this general address for the booked vehicle.","Build the buffer before the group wants to be inside, not merely before the property line. Gates open at 8:00 a.m. Loading, the approach, security screening and the walk from the authorized unload point all take time. The vehicle cannot bypass traffic staff, and the group should not ask to unload in a travel lane because the schedule ran tight."),se("What should the Barrett-Jackson day plan include?","Write 7 lines into the Barrett-Jackson day plan: guest ready time, vehicle departure, the 8:00 a.m. gate target, a primary contact, the WestWorld address, the return meeting rule, and a final roll time, and keep meals or client entertainment on separate lines so riders can see what actually moves the vehicle.","A public day runs from the 8:00 a.m. gate until auction close. Auction close itself is announced closer to the date, so the return clock stays a placeholder until the organizer publishes that day’s end. Work backward from the arrival the group wants, add loading time, and do not print one drive time for every Scottsdale hotel. Origin, day of week and event operations all change it.","The ready time is when guests are at the pickup point with tickets, identification and the bag they will carry through screening. It is not the moment they start getting dressed. The transportation lead arrives earlier, checks the manifest and calls anyone missing. Decide in advance who may hold the vehicle and for how long.","Most of the site is climate-controlled. The Performance Track thrill rides and hot laps are outdoors, for ages 8 and up or guests at least 48 inches tall. If the group includes children who will ride, say so on the itinerary so the return is not planned around an activity they cannot enter. General-admission tickets are sold online and at the on-site AXS box office, and general admission does not guarantee arena seating.","One contingency line belongs on the sheet: if the group splits, each rider follows the written meeting instruction and contacts the transportation lead. Do not create several competing pins during the auction. A single approved plan is easier to run when the grounds are busy and cellular service is uneven."),se("How should pickup after Barrett-Jackson work?","Use 2 checkpoints after Barrett-Jackson: the group gathers first at a pedestrian point the current instructions allow, then the transportation lead confirms the vehicle’s active pickup before anyone walks toward traffic, because a commercial loading lane is announced closer to the date and the arrival curb may not be the departure curb.",`What if the auction runs late? ${oo}`,"The published rideshare lot, west of Thompson Peak Parkway on McDowell Mountain Ranch Road, is the official place rideshare guests request a car. A booked Sprinter, Maybach or motorcoach follows venue staff and the instruction confirmed for that vehicle. Guests should not walk into a roadway to chase a phone pin. The lead keeps the headcount and waits for a confirmed place to move.","Set the expectation before arrival. The vehicle cannot stop wherever a pin lands, and event traffic staff control access. Comfortable shoes matter for the walk from the shuttle or the authorized curb. Anyone leaving separately tells the transportation lead so the return manifest stays accurate.","For more than one return wave, label the vehicle, the lead and the hotel. A collector group heading to one resort and a hospitality group heading to another should not rely on recognizing a driver in a crowd. The final sweep checks the manifest before the vehicle rolls, rather than waiting on people who changed plans without notice."),se("What can guests bring, and what is the gate like?","The 2027 gate allows 3 bag shapes: a clutch up to 6.5 by 4.5 inches, a clear bag up to 12 by 6 by 12 inches, or a 1-gallon clear bag, and every bag is checked while guests are screened; weapons, video cameras, skateboards, drones, coolers and animals are prohibited, with licensed service animals allowed.","One sealed water bottle under 17 ounces per person is the published drink allowance. The event is cashless except for certain food concessions and valet parking. Bring the payment method those concessions and the valet booth will take, and do not plan to pay the gate or a food stand with cash unless that stand is one of the exceptions the organizer names.","Admission is separate from transportation. General-admission tickets are sold online and at the on-site AXS box office. General admission does not guarantee a seat in the arena. Buy and verify tickets only through Barrett-Jackson’s official channels. A vehicle booking does not include a credential, a parking pass or an invitation to the January 22 gala.","If an allowed-items rule changes, the organizer’s current page replaces this summary. Send the reservations team the exact list the group will carry so vehicle fit can be reviewed against that list. Something the gate permits can still be a poor fit in the cabin."),se("How far ahead should Barrett-Jackson transportation be requested?",`Availability for Barrett-Jackson varies by date and by vehicle, so no fixed lead time applies: request a current quote with the rider count, hotel area and which of the 9 days you need, and the reservations team confirms what is open across the ${_a.length} vehicles listed, updating the plan as Barrett-Jackson announces the remaining details closer to the date.`,"The first request needs the days, the lodging or pickup area, the likely passenger count, the desired arrival against the 8:00 a.m. gate, and the return concept. A group does not need every name to begin. It does need to separate committed riders from possible ones, and to say which group is riding: collectors and VIP, a bidder crew, or a corporate host party.","Once the group is committed, close the manifest and collect mobility needs and the bags that will go through screening. Confirm that every rider has an admission plan of their own. If the docket, the auction close or the commercial loading lane is still announced closer to the date, leave that line open and name one person to recheck the official page.",`During the final 48 hours, verify addresses, contact numbers and the newest Barrett-Jackson directions. Send one summary to riders. If staff change the approach on the day, the chauffeur follows them and the transportation lead relays the update. Reach the reservations team at ${C} or ${E}. An older screenshot does not outrank the current control.`),se("How is Barrett-Jackson transportation priced per person?",`For 12 Barrett-Jackson riders sharing the ${o[Pe]} across 5 billed hours, the published ${Ut(Pe)}-per-hour rate is about ${Zo(Pe,5,12)} per person before tax for the complete shared ride; actual pricing changes with the vehicle, the duration, the itinerary and the confirmed service plan.`,"That example is arithmetic, not a flat auction fare: hourly rate multiplied by billed hours, divided by riders. If only ten people ride, divide across ten. If the group needs the motorcoach or a longer window that waits through auction close, request that calculation instead of stretching the 5-hour illustration.","A complete plan may be a continuous vehicle, separate inbound and outbound transfers, or several hotel waves across the 9 days. Each shape uses time differently. Describe the actual pattern. A many-hour gap between drop-off and pickup is not a round trip until the quote says how those hours are billed.",`The same arithmetic on the ${o[St]} uses its own published rate of ${Ut(St)}/hr and its own seated capacity of ${i[St]}. Per-person math is useful after the rider list settles. One person collects shares and one person owns the manifest. Neither job belongs to the chauffeur.`)],Qo=[{question:"What are the dates for Barrett-Jackson Scottsdale 2027?",answer:"Saturday, January 23 through Sunday, January 31, 2027, at WestWorld of Scottsdale: nine days of live auction action with over 2,000 collector vehicles on display. The invitation-only Opening Night Gala is the evening before, Friday, January 22."},{question:"Where is Barrett-Jackson Scottsdale held?",answer:"At WestWorld of Scottsdale, 16601 North Pima Road, Scottsdale, AZ 85260. Barrett-Jackson’s 2027 venue map is announced closer to the date."},{question:"What time does Barrett-Jackson open?",answer:"Gates, food courts and sponsor displays open at 8:00 a.m. every day from January 23 to 31 and stay open until auction close. Daily auction close times are announced closer to the date, so plan the ride home as a window rather than a fixed time."},{question:"Is parking free at Barrett-Jackson?",answer:"Yes. Barrett-Jackson publishes plenty of complimentary public parking for Scottsdale 2027: follow the road signs to parking. Shuttles run to and from the main gate, and valet parking is available for a fee."},{question:"Is there a shuttle at Barrett-Jackson?",answer:"Yes. Barrett-Jackson says shuttles run to and from the Scottsdale auction’s main gate. With a chauffeured ride nobody in the group drives or parks; the vehicle unloads where event staff direct, and a limo, charter or commercial drop-off zone is announced closer to the date."},{question:"Where do rideshares drop off at Barrett-Jackson?",answer:"Use the parking lot west of Thompson Peak Parkway on McDowell Mountain Ranch Road and follow the signs to the rideshare area. A chauffeured commercial drop-off zone is announced closer to the date."},{question:"How do I buy Barrett-Jackson tickets?",answer:"General-admission tickets are sold online and at the on-site AXS box office, and general admission does not guarantee arena seating. Buy only through Barrett-Jackson’s official channels. A ride booking does not include admission, valet or an invitation to the Opening Night Gala."},{question:"What if the auction runs late?",answer:oo},{question:"What is the Barrett-Jackson Opening Night Gala?",answer:"An invitation-only evening in the Auction Arena on Friday, January 22, 2027, from 7:00 to 10:00 p.m., the night before the public auction days begin. Invited guests who want a chauffeured ride book it as its own evening service."}],Xo={path:"/guides/barrett-jackson-transportation",title:"Barrett-Jackson Scottsdale 2027: parking and getting there",metaTitle:"Barrett-Jackson 2027: Parking & Rides",description:"Barrett-Jackson Scottsdale 2027 runs January 23–31 at WestWorld of Scottsdale. The official dates, complimentary public parking and main-gate shuttles, valet, the rideshare lot, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"Official Jan 23–31 dates, free parking and shuttles, valet, or a chauffeured ride",lastUpdated:Ja,lastUpdatedLabel:A(Ja),eyebrow:"Official dates: January 23–31, 2027",intro:`A Barrett-Jackson ride from Scottsdale Sprinters starts with the official 2027 page, a realistic rider count and one transportation lead. Collectors and VIP groups lead with the ${o[H]}; friends and bidder crews ride the ${o[Pe]} or a Limo Party Sprinter; corporate hosts and big groups take the mini coach, the mini bus or the party bus. This guide uses only published organizer facts, leaves unannounced details for closer to the date, and turns each day into a written pickup, arrival and return plan.`,sections:Ko,faqs:Qo,links:[{href:"/fleet/executive-sprinter-scottsdale",label:o[Pe]},{href:"/fleet/maybach-jet-sprinter-scottsdale",label:o[H]},{href:"/fleet/motorcoach-56",label:o[St]},{href:"/services/corporate-transportation-scottsdale",label:"Scottsdale corporate transportation"},{href:"/fleet",label:"Fleet capacities"},{href:"/pricing",label:"Published hourly pricing"}],sources:jo,fleetRows:_a},md=[Xo],Za="2026-09-24",en="/guides/new-years-eve-scottsdale-phoenix",_e="ultra-luxury-party-sprinter-scottsdale",ja="limo-sprinter-13-scottsdale",$t="limo-sprinter-16-scottsdale",Ht="party-bus-28-scottsdale",ht="executive-luxury-bus-29-scottsdale",tn="executive-mini-bus-26-scottsdale",et="maybach-jet-sprinter-scottsdale",an="maybach-shuttle-sprinter-8",qt="premium-suv-scottsdale",zt="executive-sprinter-scottsdale",w=e=>o[e],ie=e=>i[e],rn="https://decadencearizona.com/",on="https://decadencearizona.com/faq",nn="https://decadencearizona.com/location",sn="https://decadencearizona.com/extras",hn="https://www.scottsdaleaz.gov/codes-and-ordinances/transportation-safety-zone",dn="https://www.scottsdaleaz.gov/docs/default-source/scottsdaleaz/transportation/transportation-safety-zone-ordinance.pdf?sfvrsn=fe6b7d49_2",ln="https://www.valleymetro.org/how-to-ride/hours-service",cn="https://www.phoenix.gov/newsroom/public-transit-news/free-rides-return-to-phoenix-for-new-year-s-eve.html",un="https://www.scottsdaleaz.gov/transit-system",pn="https://www.visitphoenix.com/events/annual-events/new-years-eve-events/",fn="https://event.marriott.com/phxwh-w-scottsdale/events/scottsdale/new-years-eve-event-with-fireworkds",mn="https://www.fiestasportsfoundation.org/news/2026/9/14/cactus-bowl-tickets-now-on-sale-for-saturday-night-primetime-college-football-postseason-action-in-tempe-at-mountain-america-stadium.aspx",gn="https://www.fiestasportsfoundation.org/news/2026/7/9/vrbo-fiesta-bowl-announces-dates-to-host-college-football-playoff-matchups-through-2032.aspx",yn=[{label:"Decadence Arizona 2026, official site",href:rn},{label:"Decadence Arizona FAQ: age, doors, parking, re-entry and bags",href:on},{label:"Decadence Arizona location, parking and transit",href:nn},{label:"Decadence Arizona extras: premium parking and the Tempe shuttle",href:sn},{label:"City of Scottsdale, Transportation Safety Zone",href:hn},{label:"City of Scottsdale, Transportation Safety Zone ordinance",href:dn},{label:"Valley Metro hours of service and holiday schedule",href:ln},{label:"City of Phoenix, New Year’s Eve 2025 free rides (last year)",href:cn},{label:"City of Scottsdale trolley service",href:un},{label:"Visit Phoenix New Year’s Eve events",href:pn},{label:"W Scottsdale New Year’s Eve 2025 event page (last year)",href:fn},{label:"Fiesta Sports Foundation, Cactus Bowl 2026",href:mn},{label:"Fiesta Sports Foundation, Vrbo Fiesta Bowl dates",href:gn}];function ke(e,t,...a){return{question:e,answer:t,paragraphs:a}}const wn=[ke("What is on in Scottsdale and Phoenix for New Year’s Eve 2026?","New Year’s Eve 2026 is Thursday, December 31, 2026. Confirmed so far: Decadence Arizona on December 30 and 31 at Phoenix Raceway in Avondale, the Fiesta Bowl on December 30 in Glendale, and the Cactus Bowl on December 26 in Tempe. Scottsdale, Phoenix and Tempe have not published their 2026 New Year’s Eve events yet.","As of September 24, 2026, the official listings still describe last year. Visit Phoenix’s New Year’s Eve page and Experience Scottsdale’s New Year’s Eve story both still cover New Year’s Eve 2025. The City of Phoenix major-events page lists no New Year’s Eve event, and neither does Old Town Scottsdale’s official events list. Last year the official listings were resort, hotel, bar and venue parties, with no city-run celebration. The 2026 events are announced closer to the date; recheck the official pages in December.","The Vrbo Fiesta Bowl, a College Football Playoff quarterfinal, kicks off at 5:30 p.m. Arizona time on Wednesday, December 30, the same night as the first night of Decadence. Our Fiesta Bowl guide covers the game.","New Year’s Day is Friday, January 1, 2027. Plan the ride home for the early hours of that morning, not for the evening of December 31."),ke("How do drop-off and pickup work in Old Town Scottsdale on New Year’s Eve?","Old Town Scottsdale’s Transportation Safety Zone is in effect every night from 5 p.m. to 4 a.m., New Year’s Eve included. While it is in effect, hired vehicles load and unload only at the marked Passenger Convenience Areas and vehicle-for-hire lanes, never in a through lane, so your chauffeur stops where the city allows.","The zone covers the downtown entertainment district east of Buckboard Trail, from Sixth Avenue to Camelback Road, Sunday through Saturday. The city’s ordinance counts limousines, livery vehicles and any other motorized vehicle that carries passengers for hire as vehicles for hire. Stopping, standing, loading or unloading in a designated through lane is not allowed while the zone is in effect.","Exact curbs follow the posted signs, so the chauffeur goes by the signs and the officers on the night rather than an old map. No Old Town street closures or rideshare zones have been published for New Year’s Eve 2026; they are announced closer to the date if the city sets any.","Agree one loading point for the whole group before midnight. A crew spread across three bars walks to that point together, and the transportation lead calls the chauffeur once everyone is there. Nobody steps into a through lane to meet the vehicle."),ke("How do you get to Decadence Arizona at Phoenix Raceway?","Decadence Arizona runs December 30 and 31, 2026, at Phoenix Raceway, 7602 Jimmie Johnson Drive, Avondale, off I-10 and Loop 202. Doors open at 6 p.m. and the event ends at 3 a.m. both nights. The organizer says public transit is limited and recommends personal vehicles, event shuttles or rideshare.","Parking lots open at 4 p.m. Free parking is Entry G, premium parking is Entry F and rideshare is Entry E, and the organizer asks drivers to stay in the right lane until they reach their entry. There is no overnight parking: cars left behind are towed at the owner’s expense, on a night that ends at 3 a.m.","The organizer has not published a lane for limousines, party buses or charters. The only drop-off lane it names is Rideshare, Entry E, and its location page says dedicated rideshare pick-up and drop-off points operate near the primary entrance gates. Your chauffeur follows event staff on the night. If the organizer publishes charter guidance, that replaces this paragraph.","Wristbands scan once a day, so there is no leaving and coming back on the same night, and set times are released the week of the event. The organizer also sells a round-trip shuttle from Sunbar in Tempe as an extra, and two West Valley hotel packages include a festival shuttle."),ke("What should a Decadence group know before the ride?","Decadence is strictly 18 and over with a physical government-issued photo ID, and 21 and over for alcohol service, so a ride group can include riders under 21. The event is cashless, enforces a clear-bag policy, and does not admit patrons who are clearly intoxicated or under the influence of drugs.","The largest bag allowed is a clear bag up to 15 by 15 by 5 inches, or a one-gallon clear freezer bag, plus one small clutch up to 5 by 7 by 2 inches. An empty hydration pack of that size with no more than 2 pockets is the only exception. Outside food and drinks, glass, cans, coolers, chairs and festival totems are not allowed; two factory-sealed water bottles are.","There are no ATMs on site. The event takes Visa, Mastercard, American Express, Discover, Apple Pay and Google Pay.","Tell the reservations team the ages in the group when you book. Our guide to Arizona party bus alcohol rules explains what applies on board."),ke("Which vehicle fits which New Year’s Eve group?",`VIP and dinner parties ride the ${w(et)}, the ${w(_e)}, the ${w(an)} or the ${w(qt)}. Old Town crews take a Limo Party Sprinter or the ${w(zt)}. Decadence and big crews take the ${w(Ht)}, the ${w(ht)} or the ${w(tn)}.`,`Seat counts are seated capacities from the fleet: the ${w(_e)} seats ${ie(_e)}, the ${w(et)} ${ie(et)}, the ${w(ja)} ${ie(ja)}, the ${w($t)} ${ie($t)} and the ${w(zt)} ${ie(zt)}. The ${w(Ht)} seats ${ie(Ht)}, the ${w(ht)} ${ie(ht)}, and the ${w(qt)} ${ie(qt)}.`,`Our pick for the night is the ${w(_e)}: fiber-optic lighting with eighteen modes, lasers and a fog machine for the countdown, and a full partition with an intercom to your chauffeur. It rides with the VIP group because it is one of our ultra-luxury units.`,`When a group outgrows its row, the page offers the next row that seats everyone: a VIP table or an Old Town crew too big for its row moves up to the party bus or a coach. For a group bigger than the ${w(ht)}, we plan two or more vehicles and quote them together.`,"Count riders for each direction. The group that leaves at 6 p.m. and the group that rides home at 3 a.m. are often different lists, and the return manifest is the one that matters."),ke("How late can you ride home on New Year’s Eve?","As late as you book. Reserve by the hour and the vehicle is yours for the whole night block, or book a ride there and a ride back. Valley Metro light rail’s last full trips start between 10:50 p.m. and 12:10 a.m., and no New Year’s Eve extension has been announced for 2026.","Last New Year’s Eve (2025), Valley Metro bus, rail and paratransit rides were free from 7 p.m. on December 31 to 2 a.m. or end of service on January 1. The 2026 plan is announced closer to the date; recheck in December.","Scottsdale’s free trolleys run Monday to Friday, 5:45 a.m. to 7:45 p.m., and do not run on New Year’s Day. On New Year’s Day, light rail and streetcar run a Sunday schedule.",`Decadence ends at 3 a.m. and allows no overnight parking, so the ride home is the leg to book first. Reach the reservations team at ${C} or ${E} with the date, the pickup area, the rider count and the night you are planning.`),ke("When and where is the Cactus Bowl?","The Cactus Bowl is Saturday, December 26, 2026, at 5:30 p.m. Arizona time at ASU’s Mountain America Stadium in Tempe: Big Ten against Big 12. Parking, rideshare and drop-off for the bowl are announced closer to the date, so plan the ride around the kickoff and the official instructions when they appear.","The bowl sets its own parking, so ASU’s regular-season game-day rules are not bowl guidance. The Cactus Bowl’s online A-to-Z guide still describes last year’s game at a different stadium; wait for the 2026 version.","Tickets are sold by the Fiesta Sports Foundation. A ride booking does not include a game ticket or a parking pass.")],bn=[{question:"What is there to do on New Year’s Eve 2026 in Phoenix and Scottsdale?",answer:"Confirmed so far: Decadence Arizona on December 30 and 31 at Phoenix Raceway in Avondale, and the Fiesta Bowl on December 30 in Glendale. Scottsdale, Phoenix and Tempe have not published their 2026 New Year’s Eve events yet. Last year the official listings were resort, hotel, bar and venue parties, with no city-run celebration."},{question:"Where can I watch fireworks in Scottsdale on New Year’s Eve?",answer:"No public fireworks show is announced for New Year’s Eve 2026 as of September 24, 2026. Last year (December 31, 2025), the W Scottsdale’s ticketed 21+ New Year’s Eve party, 9 p.m. to 2 a.m., advertised a fireworks show, and Visit Phoenix’s 2025 listings also advertised a fireworks display at Allegra, The REMI Scottsdale. Check again in December."},{question:"What is Decadence Arizona?",answer:"A New Year’s festival at Phoenix Raceway on December 30 and 31, 2026, presented by Relentless Beats and Global Dance. It is strictly 18 and over with a government photo ID, and 21 and over for alcohol."},{question:"Where is Decadence Arizona?",answer:"At Phoenix Raceway, 7602 Jimmie Johnson Drive, Avondale, AZ 85323, off I-10 and Loop 202. The organizer says public transit is limited and recommends personal vehicles, event shuttles or rideshare."},{question:"What time does Decadence start and end?",answer:"Doors open at 6 p.m. and the event ends at 3 a.m., both nights. Wristbands scan once a day, so there is no same-day re-entry."},{question:"Where do you park or get dropped off at Decadence?",answer:"Lots open at 4 p.m. Free parking is Entry G, premium parking is Entry F and rideshare is Entry E; stay in the right lane until your entry. There is no overnight parking, and cars left behind are towed at the owner’s expense. The organizer has not published guidance for limos, party buses or charters."},{question:"Where and when is the Cactus Bowl?",answer:"Saturday, December 26, 2026, at 5:30 p.m. Arizona time, at ASU’s Mountain America Stadium in Tempe: Big Ten against Big 12. Parking and drop-off for the bowl are announced closer to the date."},{question:"Is Valley Metro free on New Year’s Eve 2026?",answer:"Not announced as of September 24, 2026. Last New Year’s Eve (2025), Valley Metro bus, rail and paratransit rides were free from 7 p.m. on December 31 to 2 a.m. or end of service on January 1. On New Year’s Day, light rail and streetcar run a Sunday schedule."}],vn={path:en,title:"New Year’s Eve 2026 in Scottsdale and Phoenix: Old Town, Decadence and the ride home",metaTitle:"New Year’s Eve Scottsdale & Decadence",description:"New Year’s Eve 2026 is Thursday, December 31. Old Town Scottsdale’s drop-off rules, Decadence Arizona at Phoenix Raceway on December 30 and 31, the Cactus Bowl on December 26, late transit, and a chauffeured ride home after midnight.",metaDescription:"Official dates, drop-off rules and late-night transit",lastUpdated:Za,lastUpdatedLabel:A(Za),eyebrow:"New Year’s Eve: Thursday, December 31, 2026",intro:"A New Year’s Eve ride from Scottsdale Sprinters starts with the night your group is actually having: an Old Town countdown, Decadence Arizona at Phoenix Raceway, or a dinner and the drive home. This guide uses only what the organizers, the City of Scottsdale and Valley Metro have published, labels last year’s details as last year’s, and says plainly what is still announced closer to the date.",sections:wn,faqs:bn,links:[{href:"/guides/fiesta-bowl-transportation",label:"Fiesta Bowl transportation guide"},{href:"/services/scottsdale-nightlife-transportation",label:"Scottsdale nightlife transportation"},{href:"/guides/party-bus-alcohol-laws-arizona",label:"Arizona party bus alcohol rules"},{href:`/fleet/${_e}`,label:w(_e)},{href:`/fleet/${$t}`,label:w($t)},{href:`/fleet/${et}`,label:w(et)},{href:"/pricing",label:"Published hourly pricing"}],sources:yn},gd=[vn],Ka="2026-09-24",kn="/guides/asu-gcu-graduation-transportation",Be="executive-sprinter-scottsdale",Pt="executive-white-sprinter-scottsdale",dt="executive-luxury-bus-29-scottsdale",Vt="executive-mini-bus-26-scottsdale",Ct="limo-sprinter-13-scottsdale",Qa="limo-sprinter-16-scottsdale",Jt="party-bus-28-scottsdale",Yt="maybach-jet-sprinter-scottsdale",Zt="ultra-luxury-party-sprinter-scottsdale",jt="maybach-shuttle-sprinter-8",Kt="premium-suv-scottsdale",f=e=>o[e],q=e=>i[e],Sn="https://graduation.asu.edu/undergraduate-commencement",An="https://graduation.asu.edu/graduate-commencement",Tn="https://graduation.asu.edu/ceremonies/schedule",$n="https://graduation.asu.edu/guests/parking",Pn="https://graduation.asu.edu/know-before-you-go",Cn="https://graduation.asu.edu/ceremonies/inclement-weather-plan-mountain-america-stadium",En="https://graduation.asu.edu/ceremonies/futuredates",Fn="https://traditionalcommencement.gcu.edu/",Dn="https://traditionalcommencement.gcu.edu/files/2026/09/WN26-Trad-Parking-Updated.pdf",In="https://traditionalcommencement.gcu.edu/files/2026/09/24EVT0093-WN26TradFAQ-FLY_FINAL_WORD.pdf",xn=[{label:"ASU Undergraduate Commencement, Fall 2026",href:Sn},{label:"ASU Graduate Commencement, Fall 2026",href:An},{label:"ASU Fall 2026 ceremony schedule",href:Tn},{label:"ASU graduation parking and transportation",href:$n},{label:"ASU graduation: know before you go",href:Pn},{label:"ASU inclement weather plan, Mountain America Stadium",href:Cn},{label:"ASU future commencement dates and live streams",href:En},{label:"GCU traditional commencement, Winter 2026",href:Fn},{label:"GCU Winter 2026 commencement parking instructions (PDF)",href:Dn},{label:"GCU Winter 2026 commencement FAQ (PDF)",href:In}];function he(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Rn=[he("When is ASU graduation in December 2026?","ASU’s fall 2026 University Commencement is Monday, December 14, 2026, on the Tempe campus: Graduate Commencement at 9:00 a.m. in Desert Financial Arena, and Undergraduate Commencement at 2:00 p.m. at Mountain America Stadium, on Frank Kush Field. Neither ceremony needs tickets.","For the undergraduate ceremony, graduates should arrive no later than 1:30 p.m. to sit with their college, and seating is released to the general public at 1:45 p.m. ASU lists the ceremony as ending at 3:30 p.m., and the graduate ceremony at 11:00 a.m.","The same week holds the other ceremonies: celebrations on December 11 and 12, Barrett, The Honors College Convocation at 11:00 a.m. on December 14 at ASU Gammage, The College of Liberal Arts and Sciences Convocation at 7:30 p.m. on December 14 at the stadium, and college convocations on December 15, 16 and 17, most of them in Desert Financial Arena or ASU Gammage. The ASU Online Celebration is December 16 at 11:30 a.m. in the Student Pavilion.","ASU says times and locations are subject to change; the schedule was last updated on August 26, 2026. Recheck it the week before, and plan the ride around the ceremony your graduate is actually walking in.","Spring 2027 University Commencement is May 10, 2027, by ASU’s future-dates calendar, which also says dates can change. This page is updated for May when ASU posts that schedule."),he("Where do you park for ASU graduation, and where can you be dropped off?","ASU’s commencement parking is complimentary and first come, first served: Lot 58, Lot 59 and the Packard Drive Structure for Mountain America Stadium, and Lot 59 and the Packard Drive South Garage for Desert Financial Arena. The overflow for both is the Novus Parking Structure, which takes payment on the way out.","ASU warns that large attendance creates traffic around both venues and that exits from the lots and structures will be delayed, and it strongly encourages public transportation. ASU Gammage and the Student Pavilion use Lot 3.","Mountain America Stadium is at 500 E Veterans Way, Tempe, AZ 85287, and Desert Financial Arena at 600 E Veterans Way, Tempe, AZ 85281. Accessible parking is available at each venue with a placard or plate, and ASU publishes an ADA courtesy shuttle map for the arena and the stadium.","ASU publishes no drop-off lane for limousines, charters or rideshare at commencement; its maps mark only the ADA courtesy shuttle stop. So your chauffeur drives the approach and unloads where campus event staff and police direct, and you agree the pickup point before the ceremony, not after it. When ASU publishes more for December, that replaces this paragraph.","The parking maps on ASU’s page were last updated in December 2025 for the stadium and April 2026 for the arena. Recheck them the week of the ceremony."),he("When is GCU graduation in December 2026?","GCU’s Winter 2026 traditional commencement is Thursday, December 17 and Friday, December 18, 2026, with ceremonies at 10 a.m. and 4 p.m. each day in Global Credit Union Arena, Phoenix. Each ceremony runs about an hour to an hour and a half.","December 17 at 10 a.m.: the College of Engineering and Technology and the College of Natural Sciences. December 17 at 4 p.m.: the College of Arts and Media, the College of Education, and the College of Humanities and Social Sciences.","December 18 at 10 a.m.: the Colangelo College of Business and the College of Theology. December 18 at 4 p.m.: the College of Engineering and Technology, the College of Natural Sciences, and the College of Nursing and Healthcare Professions.","Doors open two hours before each ceremony, and GCU asks ticketed guests to be seated at least 30 minutes before the start. Guests need general admission tickets: each registered graduate can reserve up to six, children three and under sit on a lap, and an overflow area shows the live stream.","GCU says its spring 2027 traditional commencement will be announced shortly after the winter ceremonies."),he("Where do you park or get dropped off for GCU graduation?","GCU parks commencement guests in the 33rd Avenue garage beside Global Credit Union Arena, 3300 W. Camelback Road, with more parking in the 31st Avenue garage at 3050 W. Camelback Road. Its rideshare drop-off and pickup address is 3300 W. Camelback Road.","Phoenix police officers direct traffic during the ceremonies and may send drivers to another lot. Classes are in session that week, so GCU expects traffic to and on campus to be exceptionally busy, and asks guests to allow 30 to 45 minutes more for parking and the walk into the arena.","From the north on I-17, exit at Camelback Road and head to 33rd Avenue. From the south, exit at Bethany Home Road, take 35th Avenue south, then Camelback Road east to the garage. GCU estimates 30 to 45 minutes from Scottsdale and 45 minutes to an hour from Mesa, Gilbert and Chandler, before parking.","GCU names no separate lane for limousines or charters, so your chauffeur follows the officers on the day and meets the family at the pickup point you agreed."),he("What can you bring into the ceremony?","Both universities enforce a clear bag policy. At GCU the limit is 12 by 12 by 6 inches, with metal detectors and bag checks, and there is no storage. At ASU the policy covers Mountain America Stadium and every ASU venue, and umbrellas are not allowed in the stadium.","GCU does not allow balloons, flags or banners, wrapped packages or gifts, noisemakers, alcohol, glass, strollers, wagons or car seats. Flowers are sold at a booth near the arena. ASU does not allow banners, flags or signs inside any venue, and allows clear, factory-sealed water bottles up to 1.5 liters at the stadium.","Book the vehicle by the hour and the flowers, balloons and gifts can stay on board during the ceremony, ready for the photos after."),he("What happens if it rains on ASU commencement day?","ASU’s undergraduate commencement is outdoors and takes place rain or shine. If weather forces a delay, ASU may hold the start for up to an hour; if the ceremony cannot be held in the stadium, it is canceled, because no indoor space on campus holds the graduates and 30,000 or more guests.","ASU advises guests to bring ponchos or rain gear, since umbrellas are not allowed, and to prearrange a meeting place outside the stadium in case the ceremony is canceled.","Make that meeting place your pickup point. The chauffeur knows where it is before the ceremony starts, and nobody has to find the family in a crowd leaving at once."),he("How long is graduation day, and how many hours should you book?","Plan the ceremony, the photos and a meal. ASU lists its undergraduate ceremony as starting at 2:00 p.m. and ending at 3:30 p.m., and GCU’s ceremonies last about an hour to an hour and a half, with doors open two hours before. A ceremony and a family dinner fit a four-hour block; an airport pickup or a party after needs more.","Book by the hour and the vehicle and chauffeur stay with you for the whole block: the pickup, the wait during the ceremony, the photos, dinner and the ride home. Or book a ride there and a ride back.","Every vehicle has a minimum number of hours, shown with its price on this page. Longer bookings earn free hours on the same published ladder as every other ride.",`Reach the reservations team at ${C} or ${E} with the ceremony, the pickup area, the number of riders and the plan after.`),he("Which vehicle fits which graduation group?",`Graduates and their families ride the ${f(Be)} or the ${f(Pt)}, or the ${f(dt)} or the ${f(Vt)} for a big family. The grad party crew takes a Limo Party Sprinter or the ${f(Jt)}. A VIP family celebration takes the ${f(Yt)}, the ${f(Zt)}, the ${f(jt)} or the ${f(Kt)}.`,`Our pick for graduation day is the ${f(Be)}: black-on-black leather shuttle seats that each recline, room for the whole family, and space for forty bags, so the flowers, gifts and gowns ride along. It delivers on every metric without the limo styling, which is what a day in caps and gowns calls for.`,`Seat counts are seated capacities from the fleet: the ${f(Be)} and the ${f(Pt)} seat ${q(Be)} each, the ${f(dt)} ${q(dt)}, the ${f(Vt)} ${q(Vt)}, the ${f(Ct)} ${q(Ct)}, the ${f(Qa)} ${q(Qa)}, the ${f(Jt)} ${q(Jt)}, the ${f(Yt)} ${q(Yt)}, the ${f(Zt)} ${q(Zt)}, the ${f(jt)} ${q(jt)} and the ${f(Kt)} ${q(Kt)}.`,`When a family outgrows its row, the page never offers it a party vehicle; for a group bigger than the ${f(dt)}, we plan two vehicles and quote them together. If anyone riding is under 21, no alcohol comes on board for the whole trip.`)],Mn=[{question:"Where do you park for ASU graduation?",answer:"ASU’s commencement parking is free and first come, first served: Lot 58, Lot 59 and the Packard Drive Structure for Mountain America Stadium, and Lot 59 and the Packard Drive South Garage for Desert Financial Arena. The Novus Parking Structure is the paid overflow. ASU warns that exits will be delayed and encourages public transportation."},{question:"Is there a drop-off area for ASU commencement?",answer:"ASU publishes no drop-off lane for limousines, charters or rideshare at commencement; its maps mark only the ADA courtesy shuttle stop. A chauffeur unloads where campus event staff and police direct."},{question:"Where is the GCU graduation rideshare drop-off?",answer:"GCU’s rideshare drop-off and pickup address is 3300 W. Camelback Road, Phoenix, beside Global Credit Union Arena. Guest parking is the 33rd Avenue garage there, with more in the 31st Avenue garage. Phoenix police direct traffic during the ceremonies."},{question:"When is ASU graduation 2026?",answer:"Monday, December 14, 2026: Graduate Commencement at 9:00 a.m. in Desert Financial Arena and Undergraduate Commencement at 2:00 p.m. at Mountain America Stadium, both in Tempe. College convocations run December 14 to 17."},{question:"When is GCU graduation 2026?",answer:"Thursday, December 17 and Friday, December 18, 2026, at 10 a.m. and 4 p.m. each day, in Global Credit Union Arena, Phoenix. Doors open two hours before each ceremony."},{question:"Do you need tickets for ASU graduation?",answer:"Not for University Commencement: neither the graduate nor the undergraduate ceremony requires tickets, and stadium guest seating is first come, first served. Some convocations and celebrations do require tickets; ASU’s schedule marks which."},{question:"How many guest tickets do you get for GCU graduation?",answer:"Each registered graduate can reserve up to six general admission guest tickets. Children three and under do not need one but sit on a ticketed guest’s lap, and an overflow area shows the live stream."},{question:"How long is the ASU graduation ceremony?",answer:"ASU lists Undergraduate Commencement as starting at 2:00 p.m. and ending at 3:30 p.m., and Graduate Commencement as starting at 9:00 a.m. and ending at 11:00 a.m. Allow time before for the crowd and after for photos."},{question:"What is the ASU graduation bag policy?",answer:"Mountain America Stadium and every ASU venue have a clear bag policy, and umbrellas are not allowed in the stadium. Guests with a bag that does not comply are asked to return it to their car."},{question:"Can you watch ASU graduation online?",answer:"Yes. ASU streams its ceremonies live; each one’s link is on the ceremony schedule and in the ASU Mobile app. GCU streams every ceremony too, and posts the videos on its YouTube channel afterward."},{question:"When is ASU graduation in spring 2027?",answer:"ASU’s future-dates calendar lists Spring 2027 University Commencement on May 10, 2027, subject to change. GCU will announce its spring 2027 ceremonies after the winter ones."}],Nn={path:kn,title:"ASU & GCU graduation 2026: dates, parking and rides",metaTitle:"ASU & GCU Graduation 2026 Parking",description:"ASU commencement is Monday, December 14, 2026, at Desert Financial Arena and Mountain America Stadium; GCU’s ceremonies are December 17 and 18 at Global Credit Union Arena. Official times, parking, drop-off and bag rules, and a chauffeured ride for the family.",metaDescription:"ASU on December 14, GCU on December 17 and 18: times, parking, drop-off and a ride",lastUpdated:Ka,lastUpdatedLabel:A(Ka),eyebrow:"Graduation: ASU December 14 · GCU December 17 and 18, 2026",intro:"A graduation ride from Scottsdale Sprinters starts with the ceremony your graduate is walking in: ASU’s commencement in Tempe or GCU’s in Phoenix. This guide uses only what the two universities have published, and says plainly what they have not.",sections:Rn,faqs:Mn,links:[{href:`/fleet/${Be}`,label:f(Be)},{href:`/fleet/${Pt}`,label:f(Pt)},{href:`/fleet/${Ct}`,label:f(Ct)},{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/service-areas/phoenix",label:"Phoenix service area"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport Sprinter van service"},{href:"/pricing",label:"Published hourly pricing"}],sources:xn},yd=[Nn],Xa="2026-09-24",Wn="/guides/christmas-lights-scottsdale-phoenix",W="ultra-luxury-party-sprinter-scottsdale",Ze="maybach-jet-sprinter-scottsdale",er="maybach-shuttle-sprinter-8",Ae="premium-suv-scottsdale",O="executive-sprinter-scottsdale",Qt="executive-white-sprinter-scottsdale",Xt="executive-mini-bus-26-scottsdale",ea="executive-luxury-bus-29-scottsdale",lt="motorcoach-56",h=e=>o[e],M=e=>i[e],ct=e=>l(s[e].hourlyRateCents),Et=e=>s[e].minimumHours,ta=(e,t)=>l(s[e].hourlyRateCents*Math.max(t,Et(e))),tr=(e,t,a)=>l(Math.round(s[e].hourlyRateCents*Math.max(t,Et(e))/a));function de(e,t,...a){return{question:e,answer:t,paragraphs:a}}const On="https://www.christmasattheprincess.com/",Gn="https://www.christmasattheprincess.com/faq",Ln="https://fairmontscottsdaleprincess.ticketspice.com/2026-christmas-at-the-princess",_n="https://www.phoenixzoo.org/events/zoolights/",Bn="https://www.phoenixzoo.org/visit/",Un="https://www.phoenixzoo.org/events/sensory-friendly-zoolights/",Hn="https://www.phoenixzoo.org/events/cruise-zoolights/",qn="https://dbg.org/events/las-noches-de-las-luminarias/",zn="https://dbg.org/explore/private-events-rentals/rental-faqs/",Vn="https://www.glendaleaz.gov/Explore/Special-Events/Events",Jn="https://www.glendaleaz.gov/News/Whats-New/Glendale-Glitters-Returns",Yn="https://scottsdazzle.com/",Zn="https://scottsdazzle.com/event/tree-lighting-spectacular-celebrating-75-years-of-scottsdale/",jn="https://oldtownscottsdaleaz.com/events/scottsdazzle/",Kn="https://oldtownscottsdaleaz.com/get-around/public-parking/",Qn="https://www.scottsdaleaz.gov/codes-and-ordinances/transportation-safety-zone",Xn=[{label:"Christmas at the Princess, official site",href:On},{label:"Christmas at the Princess FAQ: tickets, parking and rideshare",href:Gn},{label:"Christmas at the Princess 2026 tickets and parking",href:Ln},{label:"Phoenix Zoo, ZooLights 2026-27",href:_n},{label:"Phoenix Zoo, hours and visit",href:Bn},{label:"Phoenix Zoo, Sensory Friendly ZooLights",href:Un},{label:"Phoenix Zoo, Cruise ZooLights",href:Hn},{label:"Desert Botanical Garden, Las Noches de las Luminarias",href:qn},{label:"Desert Botanical Garden, parking and arrival (rental FAQ)",href:zn},{label:"City of Glendale, special events: Glendale Glitters",href:Vn},{label:"City of Glendale, Glendale Glitters 2024 release (last year’s parking)",href:Jn},{label:"Scottsdazzle, City of Scottsdale",href:Yn},{label:"Scottsdazzle Tree Lighting Spectacular",href:Zn},{label:"Old Town Scottsdale, Scottsdazzle",href:jn},{label:"Old Town Scottsdale, public parking",href:Kn},{label:"City of Scottsdale, Transportation Safety Zone",href:Qn}],es=27,ts=2,as=[de("When is Christmas at the Princess 2026, and how do parking and drop-off work?","Christmas at the Princess runs nightly from Friday, November 20, 2026, through Saturday, January 2, 2027, at the Fairmont Scottsdale Princess, 7575 E Princess Dr. Parking is a separate paid ticket bought with admission; self-parkers follow the signs onto Cottage Terrace Drive, and rideshare guests are dropped at the Enchanted Plaza.","The resort publishes its hours by the day of the week: 5 to 10 p.m. Monday to Thursday, and 4 to 11 p.m. Friday to Sunday; from December 17 it is 4 to 11 p.m. every night. November 20 is a Friday, so opening night starts at 4 p.m., and the last night, Saturday, January 2, keeps the same hours. There are no closed nights. On November 30 the resort’s village is closed for a private event, so the Ferris wheel, the sledding and the mini golf are shut that night and tickets are priced lower.","Tickets are booked online in advance for a date, with no entry time. The organiser says it is a ticketed event with limited availability that often sells out, and it does not recommend waiting to buy on site. Children 3 and under enter free, the event is cashless, and tickets bought from resellers are not honored. Book only on the event’s own 2026 ticket page.","Admission and parking are separate. A self-parking or valet ticket is required to park on the property, and parking costs more when it is bought on arrival. Self-parkers follow the signs onto Cottage Terrace Drive, where an attendant scans tickets and hands out wristbands; valet guests go to the hotel’s front drive.","Guests who arrive by rideshare follow the signs to the ride-share drop-off in the Enchanted Plaza, where staff scan tickets and hand out wristbands. The resort publishes no drop-off for a limousine, a charter or a Sprinter, so our chauffeur unloads where resort staff direct. If the vehicle is to wait on the property through your visit, ask us when you book whether it needs a parking ticket of its own.","For dinner, the organiser names Bourbon Steak, La Hacienda and Toro Scottsdale at the resort, recommends reservations there, and suggests making them at least one month ahead. Santa is there until Christmas Eve."),de("When is ZooLights 2026 at the Phoenix Zoo, and where do you park?","ZooLights runs from Wednesday, November 25, 2026, to Friday, January 15, 2027, from 5:30 to 10:30 p.m., at the Phoenix Zoo, 455 North Galvin Parkway. When the main lots fill, message boards send drivers to the overflow lot at Phoenix Municipal Stadium, about a 15-minute walk away; the Zoo mentions no shuttle.","The overflow lot is at the southwest corner of Van Buren and Priest, and the walk from it is on a lit, paved path. The Zoo asks guests to carpool and to watch the message boards on the approach. It publishes no rideshare, limousine or bus drop-off for ZooLights, so the chauffeur unloads where Zoo staff direct and meets the group at a point agreed before you walk in.","Tickets go on sale October 1 and are good for any one public night of the season: there is no date and no entry time on them. Children 2 and under are free, tickets are non-refundable, and group tickets are sold when 50 or more are bought in advance. ZooLights is open on Christmas night; the Zoo itself is closed that day.","The Zoo’s own advice on crowds: Monday, Tuesday and Wednesday are the quietest nights, the first two weeks of December and all of January are less busy, and most guests arrive when the gates open, so arriving around 7:30 or 8 p.m. can make entry smoother. It is five million lights on over two miles of trail, and most animals are not visible at night.","Two nights are ticketed on their own. Sensory Friendly ZooLights is Tuesday, December 8, 2026, with smaller crowds, quieter music and reduced flashing lights. Cruise ZooLights, a drive-through night on Sunday, January 17, 2027, admits vehicles no larger than a full-size long-bed truck, so it is not a night for a Sprinter or a coach."),de("When is Las Noches de las Luminarias 2026 at the Desert Botanical Garden?","Las Noches de las Luminarias runs 26 nights from 5:30 to 9:30 p.m. at the Desert Botanical Garden, 1201 North Galvin Parkway: November 27 to 29, December 4 to 6, December 11 to 13, December 16 to 23, December 26 to 31, and January 1 to 3, 2027. There are no nights on December 24 or 25.","Member tickets go on sale October 1 and general admission tickets on October 16. December 4 to 6 is Members Weekend. Whether entry is timed is not stated on the 2026 page; it is announced closer to the date, so check the Garden’s ticket page when you buy.","The Garden has published no parking, overflow or shuttle plan for Luminarias. Its standing guidance, written for private events, says the Garden has complimentary on-site parking with over 600 spaces and bus parking, and that guests are welcome to arrive by ride-share. With a chauffeur, the group is dropped where Garden staff direct and nobody looks for a space.","During Luminarias the Garden recommends reserving Gertrude’s by Tarbell’s through OpenTable. The Garden closes to daytime visitors at 4 p.m. on many event days, so an afternoon visit and the evening event are separate plans."),de("When is Glendale Glitters 2026?","Glendale Glitters returns to Murphy Park in Historic Downtown Glendale for its 33rd year: the lighting ceremony is at 5:45 p.m. on Friday, November 27, 2026, the kickoff event runs November 27 and 28 from 5 to 10 p.m., and the lights stay on nightly through January 1, 2027, from 5 to 10 p.m.","The City of Glendale’s 2026 page gives Murphy Park in Historic Downtown Glendale as the place and no street address. Last year’s lighting was in front of the Glendale Civic Center.","The city has not published 2026 parking for Glendale Glitters; it is announced closer to the date. Two years ago, in its 2024 release, the city pointed drivers to free parking in the downtown garage at 5835 W. Palmaire Ave. and on surface streets. With a chauffeured ride the group is dropped close to the park where traffic staff allow, and the vehicle comes back at a time you set.","Glitter and Glow and any other special Glitters night have no official 2026 dates, so they are not on this page."),de("When is Scottsdazzle 2026 in Old Town Scottsdale?","Scottsdazzle, the City of Scottsdale’s holiday season in Old Town, kicks off on Saturday, November 28, 2026, with the Tree Lighting Spectacular at the Scottsdale Waterfront Canal Bank, 7135 E Camelback Rd, from 7 to 9 p.m., and runs through December 31, 2026, throughout Old Town Scottsdale.","The tree lighting is free and lights a 36-foot Scottsdazzle tree; this year it celebrates 75 years of Scottsdale. The city’s event calendar lists more evenings through December, and it says the full 2026 program is announced closer to the date, so check it before you set the night.","Old Town parking is free: every public garage is free, and street parking has a three-hour limit. Old Town is compact and walkable once you are there.","Old Town Scottsdale’s Transportation Safety Zone is in effect every night from 5 p.m. to 4 a.m. While it is in effect, hired vehicles load and unload only at the marked Passenger Convenience Areas and vehicle-for-hire lanes, never in a through lane, so your chauffeur stops where the city allows."),de("Can you see two holiday light displays in one night?",`Yes. ZooLights and Las Noches de las Luminarias are both on North Galvin Parkway in Phoenix, about ${ts} minutes apart by car, and Christmas at the Princess is about ${es} minutes from the Phoenix Zoo in typical traffic. Book the vehicle by the hour and it waits between the stops, so the second display is a short, warm ride.`,"Those drive times are Google’s typical times without event traffic, measured on September 24, 2026. From Kierland the Princess is about 7 minutes; from Old Town Scottsdale about 22; from Sky Harbor or the Phoenician about 27; and from Historic Downtown Glendale about 34. The drive-time map on this page lists them.","Plan around the hours. ZooLights runs 5:30 to 10:30 p.m. and Luminarias 5:30 to 9:30 p.m., so the Garden goes first when you pair them. Christmas at the Princess opens at 4 or 5 p.m. and closes at 10 or 11 p.m., depending on the night, and Glendale Glitters is lit from 5 to 10 p.m. The Princess ticket is for a date and the ZooLights ticket for any one night, and neither carries an entry time.","One display with dinner fits the 4-hour minimum. Two displays usually take 5 or 6 hours, and three a longer evening. The hours you book cover the wait while you walk the lights, and a stop inside those hours costs nothing extra."),de("Which vehicle fits a family, a date night or an office party?",`Families and friends start with the ${h(O)} (${M(O)} seats) or the ${h(Xt)}; date nights and VIP groups take the ${h(Ae)}, the ${h(Ze)} or our pick, the ${h(W)} (${M(W)} seats); office parties take the ${h(Qt)}, the ${h(ea)} or the ${h(lt)}.`,`The ${h(W)} is our flagship for a lights night: fiber-optic lighting with eighteen modes takes the cabin from a dance party to something as quiet as candlelight, and it seats ${M(W)}. For a couple, the ${h(Ae)} is black on black with heated leather captain’s seats; the ${h(Ze)} (${M(Ze)} seats) and the ${h(er)} (${M(er)}) are the Maybach cabins.`,`For a family, the ${h(O)} has black leather seats that each recline, with room for strollers, coats and bags; the ${h(Xt)} seats ${M(Xt)} for an extended family.`,`An office holiday party takes the ${h(Qt)} (${M(Qt)} seats), the ${h(ea)} (${M(ea)}) or, for the whole company, the ${h(lt)} (${M(lt)}). The motorcoach photos on this page are representative; the assigned coach is confirmed in writing. Count everyone who rides, plus coats and anything bought at the displays.`),de("What does a chauffeured holiday lights night cost?",`Every vehicle is booked by the hour with a ${Et(O)}-hour minimum (the motorcoach ${Et(lt)}): 4 hours in the ${h(O)} is ${ta(O,4)} before tax, about ${tr(O,4,M(O))} each for ${M(O)} riders; the ${h(W)} is ${ta(W,4)}, about ${tr(W,4,M(W))} each for ${M(W)}; the ${h(Ae)} is ${ta(Ae,4)} for a date night.`,`Those are the published hourly rates times the hours, before ${Ga}% Arizona sales tax: ${ct(O)} an hour for the ${h(O)}, ${ct(W)} for the ${h(W)}, ${ct(Ae)} for the ${h(Ae)} and ${ct(Ze)} for the ${h(Ze)}. The fare belongs to the vehicle, so one more rider does not change it. Admission and any parking at the displays are bought from the organisers, not from us.`,"The packages on this page add extras from our catalog to a vehicle and a set of hours, priced the same way: the Lights Crawl, Princess Date Night and the Family Lights Tour. Checkout shows exactly what is charged today and when any balance is due.",`Call ${C} or email ${E} with the night, the pickup address and the rider count, and we confirm what is open. Availability varies by night and by vehicle.`)],rs=[{question:"What time does Christmas at the Princess open?",answer:"At 5 p.m. Monday to Thursday and 4 p.m. Friday to Sunday, and at 4 p.m. every night from December 17. It closes at 10 p.m. on the 5 p.m. nights and at 11 p.m. on the others. Opening night, Friday, November 20, 2026, starts at 4 p.m."},{question:"When does Christmas at the Princess start and end?",answer:"Nightly from Friday, November 20, 2026, through Saturday, January 2, 2027, at the Fairmont Scottsdale Princess, 7575 E Princess Dr, Scottsdale. There are no closed nights; on November 30 some attractions are closed for a private event."},{question:"Is parking included with Christmas at the Princess tickets?",answer:"No. Admission and parking are separate, and a self-parking or valet ticket is required to park on the property; parking costs more if it is bought on arrival. Rideshare guests are dropped at the Enchanted Plaza."},{question:"When does ZooLights at the Phoenix Zoo start and end?",answer:"ZooLights runs from Wednesday, November 25, 2026, to Friday, January 15, 2027, from 5:30 to 10:30 p.m. every night, Christmas night included."},{question:"Where do you buy Phoenix ZooLights tickets?",answer:"Online from the Phoenix Zoo, with general sales from October 1. A ticket is good for any one public night of the season, with no date or entry time on it. Sensory Friendly ZooLights on December 8 and Cruise ZooLights on January 17 are ticketed separately."},{question:"Where do you park for ZooLights?",answer:"In the Zoo’s main lots; when they fill, message boards send drivers to the overflow lot at Phoenix Municipal Stadium, at Van Buren and Priest, about a 15-minute walk on a lit path. The Zoo mentions no shuttle."},{question:"When does Glendale Glitters start and end?",answer:"The lighting ceremony is Friday, November 27, 2026, at 5:45 p.m., the kickoff event runs November 27 and 28, and the lights stay on nightly through January 1, 2027, from 5 to 10 p.m."},{question:"Where is Glendale Glitters?",answer:"In Murphy Park, in Historic Downtown Glendale. The city has not published a street address or 2026 parking; its 2024 release pointed drivers to free parking in the downtown garage at 5835 W. Palmaire Ave. and on surface streets."},{question:"Where can you see Christmas lights in Phoenix and Scottsdale?",answer:"The five big displays of the 2026 season are Christmas at the Princess in Scottsdale, ZooLights at the Phoenix Zoo, Las Noches de las Luminarias at the Desert Botanical Garden, Glendale Glitters in Historic Downtown Glendale and Scottsdazzle in Old Town Scottsdale."},{question:"Can the chauffeur wait while we walk the lights?",answer:"Yes. Book the vehicle by the hour and it is yours for the whole block: it waits while you walk the lights, takes you to a second display or to dinner, and brings everyone home. Stops inside the hours you booked cost nothing extra."}],os={path:Wn,title:"Christmas at the Princess, Phoenix ZooLights and Glendale Glitters 2026: parking and rides",metaTitle:"Christmas at the Princess & ZooLights",description:"Christmas at the Princess, Phoenix ZooLights, Las Noches de las Luminarias, Glendale Glitters and Scottsdazzle: the official 2026 dates and hours, where to park or be dropped off, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"Official dates, hours, parking and a ride home",lastUpdated:Xa,lastUpdatedLabel:A(Xa),eyebrow:"Official dates: November 20, 2026 – January 15, 2027",intro:"A holiday lights night with Scottsdale Sprinters starts with the organisers’ own 2026 dates, one vehicle for the whole group and a chauffeur who waits while you walk the lights. This guide covers Christmas at the Princess, ZooLights at the Phoenix Zoo, Las Noches de las Luminarias at the Desert Botanical Garden, Glendale Glitters and Scottsdazzle in Old Town, using only what each organiser publishes, parking and drop-off first.",sections:as,faqs:rs,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:h(W)},{href:"/fleet/executive-sprinter-scottsdale",label:h(O)},{href:"/fleet/premium-suv-scottsdale",label:h(Ae)},{href:"/services/corporate-transportation-scottsdale",label:"Scottsdale corporate transportation"},{href:"/guides/venues/fairmont-scottsdale-princess",label:"Fairmont Scottsdale Princess guide"},{href:"/pricing",label:"Published hourly pricing"}],sources:Xn},wd=[os],ar="2026-09-24",ns="/guides/venues/desert-diamond-arena",Ce="ultra-luxury-party-sprinter-scottsdale",aa="maybach-jet-sprinter-scottsdale",ss="maybach-shuttle-sprinter-8",is="premium-suv-scottsdale",Ue="limo-sprinter-13-scottsdale",rr="limo-sprinter-16-scottsdale",ra="executive-sprinter-scottsdale",Ee="party-bus-28-scottsdale",ut="executive-luxury-bus-29-scottsdale",oa="executive-mini-bus-26-scottsdale",m=e=>o[e],le=e=>i[e],na=e=>`${l(s[e].hourlyRateCents)} an hour with a ${s[e].minimumHours}-hour minimum`,Ve="https://www.desertdiamondarena.com",hs=`${Ve}/venue-info/`,ds=`${Ve}/venue-info/parking/`,ls="https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/asm-glendale/Parking_Map_0b35a191-a8e4-47e1-bca1-e73b26128e02.jpg",cs=`${Ve}/venue-info/azguide/`,us=`${Ve}/events-tickets/`,ps=`${Ve}/events-tickets/seat-map/`,fs=`${Ve}/events-tickets/box-office/`,ms="https://assets.simpleviewinc.com/simpleview/image/upload/v1/clients/asm-glendale/DDA_Private_Event_Deck_2026_91290cc0-c10b-4ec7-b259-f9be05e09cf7.pdf",gs="https://www.pbr.com/news/2026/05/pbr-world-finals-championship-to-be-held-in-glendale-arizona-may-20-23-2027/",ys="https://westgateaz.com/",ws="https://www.valleymetro.org/how-to-ride/destinations/destinations-west-valley",Ba=Jr.filter(e=>e.featured),Wt=Ba.find(e=>e.label==="Jonas Brothers"),Ua=Ba.find(e=>e.label==="Pentatonix"),nt=Ba.find(e=>e.kind==="sports"),bs=[{label:"Desert Diamond Arena, venue information",href:hs},{label:"Desert Diamond Arena, parking and directions",href:ds},{label:"Desert Diamond Arena, official parking map",href:ls},{label:"Desert Diamond Arena, A to Z guide and bag policy",href:cs},{label:"Desert Diamond Arena, event calendar",href:us},{label:"Desert Diamond Arena, seat map",href:ps},{label:"Desert Diamond Arena, box office",href:fs},{label:"Desert Diamond Arena, Jonas Brothers event page",href:Wt.url},{label:"Desert Diamond Arena, PBR World Finals 2027 event page",href:nt.url},{label:"PBR, World Finals Championship in Glendale, May 20–23, 2027",href:gs},{label:"Desert Diamond Arena, 2026 private events guide (capacity)",href:ms},{label:"Westgate Entertainment District",href:ys},{label:"Valley Metro, West Valley destinations",href:ws}],vs={Sun:"Sunday",Mon:"Monday",Tue:"Tuesday",Wed:"Wednesday",Thu:"Thursday",Fri:"Friday",Sat:"Saturday"},Ke=["January","February","March","April","May","June","July","August","September","October","November","December"];function sa(e){const[t,a,n]=e.split("-").map(Number),c=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"][new Date(Date.UTC(t,a-1,n)).getUTCDay()];return`${vs[c]}, ${Ke[a-1]} ${n}, ${t}`}function j(e){const[t,a,n]=e.dates.start.split("-").map(Number);if(!e.dates.end||e.dates.end===e.dates.start)return`${Ke[a-1]} ${n}, ${t}`;const[,c,N]=e.dates.end.split("-").map(Number);return c===a?`${Ke[a-1]} ${n} to ${N}, ${t}`:`${Ke[a-1]} ${n} to ${Ke[c-1]} ${N}, ${t}`}function ks(e){const t=e.dates.end&&e.dates.end!==e.dates.start?`${sa(e.dates.start)} to ${sa(e.dates.end)}`:sa(e.dates.start),a=[e.doors?`doors ${qa(e.doors)}`:null,e.starts?`${e.dates.end&&e.dates.end!==e.dates.start?"first show":"show"} ${qa(e.starts)}`:null].filter(Boolean);return`${t}: ${e.title}${a.length?` (${a.join(", ")})`:""}.`}function K(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Ss=[K("Where is Desert Diamond Arena?","Desert Diamond Arena is at 9400 West Maryland Avenue, Glendale, AZ 85305, in the Westgate Entertainment District off Loop 101. State Farm Stadium is directly south across Maryland Avenue, and Westgate’s shops and restaurants are directly north across Entertainment Boulevard.","From Loop 101, exit 7A is Maryland Avenue and exit 7B is Glendale Avenue; the arena’s own parking map routes cars into its lots from both. The arena sits on 13.5 acres, is managed by Legends Global, and says it entertains over one million visitors a year with concerts, family shows and sporting events.","By Google’s typical drive time, measured on September 24, 2026 without event traffic, the arena is 23 minutes from downtown Phoenix, 28 minutes from Phoenix Sky Harbor, and 36 minutes from Old Town Scottsdale or Kierland. Show nights add the arena’s own traffic to the last mile.","Valley Metro lists no light rail to the Westgate area. Its West Valley destinations page gives the Westgate Entertainment District one bus connection, Route 70."),K("How does parking work at Desert Diamond Arena?","Arena parking lots open one hour before doors. On the day, spaces are in lots G, J, L, Yellow, the Garage and VIP, as each event allows, and the entrances take credit or debit cards only, no cash. A pre-paid space, bought on the event page up to an hour before the event, is guaranteed until 30 minutes after the start.","Pre-paid parking is shown at the entrance from the Ticketmaster app, the ParkWhiz confirmation email or a ParkWhiz account. The arena says it gives faster entry and exit and closer spaces. Its VIP parking, sold on the event pages, is reserved front-row parking with an express lane in and out, in limited numbers.","Every pass covers one standard 12 by 18 foot space, and oversized vehicles must buy additional spaces. Overnight parking and camping are not permitted. Accessible parking is first come, first served in Lots G, J and the Garage for a valid placard or plate, with a pre-purchased permit or a day-of fee.","The arena’s pages publish no parking price: it is set by event and shown when you buy the space through the event page. Pay by card, and pre-pay when the lot matters to your group."),K("Where do rideshare and chauffeured groups drop off at Desert Diamond Arena?","Desert Diamond Arena publishes no rideshare, limo, charter or bus drop-off zone on its parking page, its A to Z guide or its event pages, so a chauffeured group unloads where arena staff and police direct on the night, and agrees one pickup point for the ride home before the show.","Nothing here is a reserved lane for booked vehicles. The chauffeur drives the approach the event’s traffic allows, lets the group out where staff direct, and meets it at the agreed point once the crowd clears. If the arena publishes a drop-off plan for a show, that plan replaces this paragraph.","A group that splits across cars also splits across lots and exits. One vehicle arrives with everyone at once and leaves with everyone at once, which matters most on a night that starts with dinner at Westgate."),K("What’s coming up at Desert Diamond Arena?",`Coming up at Desert Diamond Arena: the Jonas Brothers on ${j(Wt)}, Rush on December 1 and 3, 2026, Pentatonix on ${j(Ua)}, and the PBR World Finals Championship on ${j(nt)}. The arena’s calendar lists these shows from October 21, 2026, as read on September 24, 2026:`,...Jr.map(ks),"Los Tigres del Norte moved from September 12 to October 24, and the arena says tickets for the original date are valid for the new one. The Hot Wheels Stunt Show has three performances: noon and 7 p.m. on Saturday, March 6, and 2 p.m. on Sunday, March 7.","The PBR World Finals Championship comes to Glendale after its opening rounds in Fort Worth on May 6 to 9, 2027. Session times are announced closer to the date. New shows are added to the arena’s calendar through the year, and it is the place to check before you book."),K("How many people does Desert Diamond Arena hold?","Desert Diamond Arena’s own 2026 private events guide lists the arena at a capacity of 20,000, with a 24,400 square foot floor. The number sold for a show depends on its stage and seating layout, which the arena’s seat map shows event by event.","For a group, capacity decides the traffic, not the ride: a sold-out night means full lots, lines at the card readers and one long exit. That is the night to leave the driving to a chauffeur and the parking to the lot."),K("What is the Desert Diamond Arena bag policy?","Bags and purses must be 12 by 12 by 6 inches or smaller to enter Desert Diamond Arena, clear or not. Laptop bags, briefcases, camera bags, coolers, luggage of any kind and seat cushions are not allowed at any size.","Outside food, drinks, cans, bottles and flasks are not allowed either; a factory-sealed water bottle under 17 ounces is. Every guest is screened on entry, with Evolv scanners at some entrances.","Settle bags at the hotel. A group that is dropped off has no car in the lot to go back to during the show."),K("Which hotels and restaurants are near Desert Diamond Arena?","The arena’s parking map shows the Renaissance Hotel, the Hampton Inn & Suites, Home2 Suites by Hilton and the Tru Hotel just west of the arena, between 95th Avenue and Loop 101, and the Westgate Entertainment District’s restaurants directly north across Entertainment Boulevard.","Westgate describes itself as specialty shops, eateries and entertainment in the heart of Glendale, at 6770 North Sunrise Boulevard. On the arena’s own map it sits across one street from the arena.","Our Westgate Dinner + Show package is built for that night: pickup, dinner at Westgate, the show and the ride home, in one booking."),K("Which vehicle fits a Desert Diamond Arena group?",`Concert crews ride a Limo Party Sprinter or the ${m(ra)}. A VIP night out takes the ${m(aa)}, the ${m(Ce)}, the ${m(ss)} or the ${m(is)}. Big groups and fan clubs take the ${m(Ee)}, the ${m(ut)} or the ${m(oa)}.`,`Seat counts are seated capacities from the fleet: the ${m(Ce)} seats ${le(Ce)}, the ${m(Ue)} ${le(Ue)}, the ${m(rr)} ${le(rr)}, the ${m(ra)} ${le(ra)} and the ${m(aa)} ${le(aa)}. The ${m(Ee)} seats ${le(Ee)}, the ${m(ut)} ${le(ut)} and the ${m(oa)} ${le(oa)}.`,`Our pick for an arena night is the ${m(Ce)}, ${na(Ce)}: fiber-optic lighting with eighteen modes, lasers and a fog machine, an ultra-premium sound system and a full partition with an intercom to your chauffeur. The ${m(Ue)} is ${na(Ue)}, and the ${m(Ee)} is ${na(Ee)}. Every rate prices the whole vehicle, before tax.`,`For a group bigger than the ${m(ut)}, we plan two or more vehicles and quote them together. Count riders for the ride home as well as the ride there; the late list is the one that matters.`),K("How should a group plan the ride to a Desert Diamond Arena show?","Plan backwards from the doors. At every listed concert the doors open an hour before the show, and the arena lots open an hour before the doors, so a pickup that lands the group at the arena around the doors time leaves room for the lines and the bag check.","Arena guests with the paid Bassline Bar upgrade get in 60 minutes before general doors, between Gates 3 and 4; plan that pickup earlier still. It is an add-on to a ticket, not a ticket.",`Book by the hour and the vehicle is yours for the whole night, dinner at Westgate included, or book a ride there and a ride back. Reach the reservations team at ${C} or ${E} with the show, the date, the pickup area and the rider count.`)],As=[{question:"Where do you park at Desert Diamond Arena?",answer:"In the arena’s own lots: on the day, lots G, J, L, Yellow, the Garage and VIP, as each event allows. They open one hour before doors, take cards only, and a pre-paid space bought on the event page is held until 30 minutes after the start."},{question:"How much is parking at Desert Diamond Arena?",answer:"The arena’s pages publish no parking price: it is set by event and shown when you pre-pay on the event page through Ticketmaster or ParkWhiz. At the entrance it is credit or debit card only, no cash, and oversized vehicles must buy additional spaces."},{question:"What time do Desert Diamond Arena parking lots open?",answer:"One hour before the event’s doors. At every listed concert the doors open an hour before the show."},{question:"What concerts are coming to Desert Diamond Arena?",answer:`Among the listed shows: the Jonas Brothers on ${j(Wt)}, Rush on December 1 and 3, 2026, and Pentatonix on ${j(Ua)}, then the PBR World Finals Championship on ${j(nt)}. The arena’s calendar has the full, current list.`},{question:"How many people does Desert Diamond Arena hold?",answer:"The arena’s own 2026 private events guide lists a capacity of 20,000. A show’s capacity depends on its stage and seating layout."},{question:"Where is Desert Diamond Arena?",answer:"At 9400 West Maryland Avenue, Glendale, AZ 85305, in the Westgate Entertainment District off Loop 101, across Maryland Avenue from State Farm Stadium."},{question:"What is the Desert Diamond Arena bag policy?",answer:"Bags up to 12 by 12 by 6 inches, clear or not. No laptop bags, briefcases, camera bags, coolers, luggage or seat cushions at any size."},{question:"When is the PBR World Finals at Desert Diamond Arena?",answer:`The PBR World Finals Championship is ${j(nt)}, after the opening rounds in Fort Worth on May 6 to 9. Session times are announced closer to the date.`},{question:"Can a limo or party bus drop off at Desert Diamond Arena?",answer:"Yes, where arena staff and police direct on the night. The arena publishes no rideshare, limo or charter zone, so the chauffeur confirms the drop-off for your show and agrees one pickup point for the ride home."},{question:"Is there light rail to Desert Diamond Arena?",answer:"No. Valley Metro lists no light rail to the Westgate area; its one listed connection there is bus Route 70."}],Ts={path:ns,title:"Desert Diamond Arena: Parking, Upcoming Shows and Concert Rides",metaTitle:"Desert Diamond Arena Parking & Shows",description:"Desert Diamond Arena in Glendale: how the arena’s parking works, the upcoming concerts and the PBR World Finals, capacity, the bag policy, the hotels and Westgate next door, and a chauffeured ride so nobody drives or parks.",metaDescription:"Lots, doors, the upcoming shows and a chauffeured ride",lastUpdated:ar,lastUpdatedLabel:A(ar),eyebrow:"Glendale · Westgate Entertainment District",intro:`Scottsdale Sprinters’ short answer on Desert Diamond Arena: it is at 9400 West Maryland Avenue in Glendale, in the Westgate Entertainment District beside State Farm Stadium. Arena lots open one hour before doors and take cards only, and a pre-paid space is held until 30 minutes after the start. Coming up: the Jonas Brothers on ${j(Wt)}, Rush on December 1 and 3, Pentatonix on ${j(Ua)} and the PBR World Finals on ${j(nt)}. For a group, one chauffeured vehicle replaces the lot, the card reader and the drive home.`,sections:Ss,faqs:As,links:[{href:"/guides/venues/state-farm-stadium",label:"State Farm Stadium parking, across Maryland Avenue"},{href:"/service-areas/glendale",label:"Glendale service area"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:`/fleet/${Ce}`,label:m(Ce)},{href:`/fleet/${Ue}`,label:m(Ue)},{href:`/fleet/${Ee}`,label:m(Ee)},{href:"/pricing",label:"Published hourly pricing"}],sources:bs},bd=[Ts],or="2026-09-24",$s="/guides/wm-phoenix-open-parking",me="maybach-jet-sprinter-scottsdale",Ft="ultra-luxury-party-sprinter-scottsdale",nr="maybach-shuttle-sprinter-8",sr="premium-suv-scottsdale",ir="limo-sprinter-13-scottsdale",Fe="limo-sprinter-16-scottsdale",pt="party-bus-28-scottsdale",Ge="executive-sprinter-scottsdale",Ps="executive-white-sprinter-scottsdale",hr="executive-mini-bus-26-scottsdale",ft="executive-luxury-bus-29-scottsdale",v=e=>o[e],F=e=>i[e],ia=e=>l(s[e].hourlyRateCents);function Cs(e,t,a){return l(Math.round(s[e].hourlyRateCents*t/a))}const dr=F(Ge),lr=6,Es="https://wmphoenixopen.com/event-schedule/",Fs="https://wmphoenixopen.com/spectator-info/",Ds="https://wmphoenixopen.com/wp-content/uploads/2026/04/2026-Parking-Map_Public.pdf",Is="https://wmphoenixopen.com/wp-content/uploads/2026/05/ADA-Spectator-Information.pdf",xs="https://wmphoenixopen.com/tickets-packages/tickets-concerts-coors-birds-nest/",Rs="https://coorslightbirdsnest.com/",Ms="https://wmphoenixopen.com/insights/grammy-award-winning-imagine-dragons-to-kick-off-wm-phoenix-open-week-at-the-iconic-16th-hole-for-year-6-of-concert-in-the-coliseum/",Ns="https://tpc.com/scottsdale/",Ws=[{label:"WM Phoenix Open 2027 event schedule",href:Es},{label:"WM Phoenix Open spectator information: parking, entrances, entry times and bags",href:Fs},{label:"WM Phoenix Open 2026 parking map (last year’s plan)",href:Ds},{label:"WM Phoenix Open accessibility services (ADA) guide",href:Is},{label:"Coors Light Birds Nest 2027 tickets and lineup",href:xs},{label:"Coors Light Birds Nest FAQ",href:Rs},{label:"Concert in the Coliseum 2027 announcement",href:Ms},{label:"TPC Scottsdale, the host course",href:Ns}];function ce(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Os=[ce("Where do you park for the WM Phoenix Open 2027, and is it free?","The 2027 parking plan and any parking price are announced closer to the date. In 2026, general parking used remote WestWorld Lots A, B and C, plus a Salt River Fields lot with a free shuttle; ADA parking is Lot 2, at Hayden and Bell. With a chauffeured ride, nobody in the group drives or parks.","Last year’s plan, labelled as last year’s: in 2026 the remote general-parking lots were WestWorld Lots A, B and C, open Monday through Sunday and reached from the WestWorld area near Frank Lloyd Wright Boulevard, Thompson Peak Parkway, Pima Road and Bell Road. The 2026 Salt River Fields lot ran Wednesday through Sunday from 9:00 a.m. to 6:00 p.m., about 7.6 miles south of TPC Scottsdale, with a free shuttle to the tournament. The tournament’s parking answers still link that 2026 map.","Also from 2026: general-parking guests were told not to leave Loop 101 at Hayden Road or Scottsdale Road, which were kept for ADA access and credentialed passes because of restrictions on 78th Street and Mayo Boulevard, and to use the Princess Boulevard or Bell Road exits instead. Treat that as last year’s routing until the tournament publishes the 2027 version.","Confirmed now: some areas and parking lots are reserved for specific pass types, including event staff, vendors, volunteers, media, charter buses and internal operations, and guests may enter only the areas their pass allows. The ADA lot is Lot 2, at the corner of Hayden and Bell Roads, with a valid handicap placard displayed. The tournament also says parking operations, routes and lot availability may change as the event approaches.","The chauffeured alternative: we pick the group up at the hotel or home and unload where traffic staff direct. Nobody hunts for a lot, waits for a remote-lot shuttle or drives home after the 16th hole. Whether a booked Sprinter or coach needs a pass for any lot is not published, so the reservations team confirms the current instruction before the day rather than promising a lot."),ce("Where do rideshares and drop-offs go at the Phoenix Open?","In 2026, rideshare vehicles, taxis and all passenger drop-off and pick-up used Lot R, entered from Pima Road, instead of the public lots; the 2027 plan is announced closer to the date. At the Birds Nest, rideshares use Hartford Drive, south of Princess. A chauffeured vehicle unloads where traffic staff direct.","No official page gives a limo, a party bus or a charter a gate or drop-off privilege. The only published line about charters is that some lots are reserved for pass types, charter buses among them, and the tournament has not published how an operator gets that pass. So this page promises no gate, lot or curb: the chauffeur follows traffic staff, and the reservations team passes on any 2027 instruction the tournament publishes.","The entrances are the Main Entrance at Bell, the Hayden Entrance and the Fairmont Scottsdale Princess Golf Entrance. Checkpoints stand throughout the area and must be passed before entering designated zones, and some roads and private areas are closed to event guest traffic. Plan the pickup as a place the group can walk to from the entrance it used, not a pin dropped beside a checkpoint.","For the ride home, name one meeting point and one transportation lead before the group goes in. The curb you arrived at may not be where a vehicle can wait at the end of play. The lead counts heads, confirms the vehicle’s position with the chauffeur and walks the group there together, rather than everyone chasing a map pin at once."),ce("When is the WM Phoenix Open 2027?","The WM Phoenix Open runs Monday, February 8 to Sunday, February 14, 2027, at TPC Scottsdale. Monday and Tuesday are Ford Free Days with free general admission, and the 4 rounds run Thursday, February 11 to Sunday, February 14: play begins at 7:30 a.m. Thursday and Friday and 9:00 a.m. on the weekend.","The week opens early. The Concert in the Coliseum is on Saturday, February 6, 2027, on the 16th hole: Imagine Dragons, with Counting Crows opening, for guests 21 and over, with venue gates at 3:30 p.m. The Carlisle Pro-Am starts at 8:30 a.m. on Monday, February 8, and the Annexus Pro-Am at 8:30 a.m. on Wednesday, February 10, the day the WHOOP Shot at Glory is on the 16th hole at 3:30 p.m.","Saturday, February 13 is Green Out Saturday: guests wear green, and a donation goes to the tournament’s Working for Tomorrow fund. The Coors Light Birds Nest runs the evenings of Wednesday, February 10 to Saturday, February 13. The tournament says its agenda is subject to change, so recheck the official schedule in the week before you ride.","For a ride, pick the day first, then the arrival. The tournament suggests lining up early for a seat at the 16th hole, especially on Friday and Saturday, when early arrivals are asked to use the Main Entrance. On the Ford Free Days, Monday and Tuesday, no ticket is needed at all."),ce("Where is the Phoenix Open played, and when do the gates open?","The Phoenix Open is played on the Stadium Course at TPC Scottsdale, 17020 North Hayden Road, Scottsdale, AZ 85255. Entry opens each day at 7:00 a.m. at the Main and Princess entrances and at 7:15 a.m. at Hayden; on Friday and Saturday, Hayden opens only once the Main line is in.","The three entrances are the Main Entrance at Bell, the Hayden Entrance and the Fairmont Scottsdale Princess Golf Entrance. Guests arriving early on Friday and Saturday are asked to use the Main Entrance; a line may form at Hayden, but Hayden admits guests only after everyone at the Main Entrance is in. Tournament Guest Services is north of Bell Road between Hayden and 82nd Street and opens daily at 7 a.m.","The entry times are the tournament’s own answers, written after the 2026 event and not dated for 2027, so recheck them in January. The street address is the host club’s, from TPC Scottsdale’s own site. On the day the tournament routes guests by entrance, lot and signage rather than by street number, and the chauffeur follows its signs and staff.","Tournament traffic is not normal traffic. Build the buffer before the time the group wants to be through the gate, count screening and the walk from the unload point, and plan the return as a window rather than a fixed minute: the round, the crowd at the 16th hole and the exits decide it."),ce("Which vehicle fits a Phoenix Open group?",`Match the vehicle to the day: hospitality hosts and VIP guests ride the ${v(me)} or our other ultra-luxury rides, 16th-hole crews take a Limo Party Sprinter or the ${v(pt)} for up to ${F(pt)}, and couples and golf fans take an Executive Sprinter or, for a club of up to ${F(ft)}, the ${v(ft)}.`,`Corporate hospitality and VIP: the ${v(me)} leads, ${F(me)} seats with Maybach massage recliners and a wet bar. The ${v(Ft)} seats ${F(Ft)} in a fiber-optic lounge for a Birds Nest night, the ${v(nr)} seats ${F(nr)} in custom Maybach seats, and the ${v(sr)} carries a couple or a small client party of up to ${F(sr)}. A larger hospitality list moves in the executive coaches below.`,`16th-hole crews: the ${v(ir)} and the ${v(Fe)} are limo lounges on wheels for ${F(ir)} and ${F(Fe)}, and the ${v(pt)} puts ${F(pt)} on limo seating when the whole crew comes. These are party rides for a group out to celebrate; we never send one as a corporate client vehicle.`,`Couples and golf fans: the ${v(Ge)} and the ${v(Ps)} seat ${F(Ge)} each in reclining leather, and the ${v(hr)} (${F(hr)} seats) and the ${v(ft)} (${F(ft)} seats) carry a golf club, a supporters’ group or a company outing in one vehicle.`,"Count riders for each direction. A morning arrival for the 16th hole and an evening return after the Birds Nest are often different lists. Anyone leaving with another group comes off the return manifest before seats are assigned; “we will decide at the course” is not a count the chauffeur can plan around when the tournament is releasing traffic."),ce("What is the Coors Light Birds Nest, and how do you get there and back?","The Coors Light Birds Nest is the tournament’s 21-and-over concert tent at 82nd Street and Bell Road, across from the main entrance, from Wednesday, February 10 to Saturday, February 13, 2027. Headliners usually go on at about 8:30 p.m.; rideshares use Hartford Drive, south of Princess, and a booked ride waits for the group.","The 2027 lineup so far: Riley Green with Ashley Cooke on Wednesday, Jason Aldean with Josh Ross on Thursday, and Snoop Dogg with T-Pain on Friday. Saturday’s act is to be announced. Valid government-issued ID is required at the gate, and Will Call is at the Birds Nest front gate on 82nd Street and Bell Road, opening at noon Wednesday through Saturday.","The gate time is announced closer to the date: the organizer’s own pages do not yet agree on it. Birds Nest parking hours are also listed as to be determined. After the concert, the organizer’s shuttles take guests to the WestWorld of Scottsdale parking used for the tournament.","A chauffeured group skips the lot and the shuttle: book the vehicle by the hour for the evening, or a drop-off and a set pickup, and agree the meeting point before the headliner starts. The Birds Nest and the Concert in the Coliseum are both 21 and over, so a group with anyone younger plans the tournament day instead of the concert night."),ce("What can you bring into the Phoenix Open, and what should the day plan include?","The gate allows no opaque bag larger than 6 by 6 by 6 inches and no clear bag larger than 12 by 6 by 12 inches, and admission is a digital AXS ticket. Write the day plan in 5 lines: ready time, entrance, meeting point, one transportation lead and the ride home.","General admission for the tournament and for the Birds Nest is a digital AXS Mobile ID ticket; guests without a smartphone can visit Guest Services. Guests 15 and younger get in free, and on the Ford Free Days, Monday, February 8 and Tuesday, February 9, no ticket is needed. Suites and hospitality packages are sold by the tournament, not by us: a ride includes no ticket, pass or parking.","Anything bigger than those bag limits, a cooler included, stays on the vehicle. The ready time is when guests are at the pickup point with tickets on their phones, not when they start getting dressed. On Green Out Saturday the tournament asks guests to wear green; its FAQ sets no other dress code.","Free mobility scooters are offered first come, first served, Tuesday through Sunday, on Bell Road near the main entrance, and there are ADA viewing platforms at the 16th green, the 17th fairway and the 18th green. Tell the reservations team about mobility needs when you book, so the pickup and the unload point suit the rider.",`During the final 48 hours, verify addresses, contact numbers and the tournament’s newest parking and entry notes, and send one summary to riders. If staff change the approach on the day, the chauffeur follows them and the transportation lead relays the update. Reach the reservations team at ${C} or ${E}.`),ce("How is Phoenix Open transportation priced per person?",`For ${dr} Phoenix Open riders sharing the ${v(Ge)} for ${lr} billed hours, the published ${ia(Ge)}-per-hour rate comes to about ${Cs(Ge,lr,dr)} per person before tax for the whole shared ride; the price changes with the vehicle, the hours, the day and the confirmed plan.`,"That example is arithmetic, not a flat tournament fare: the hourly rate times the billed hours, divided by the riders. If only ten people ride, divide by ten. A day that waits through the round and dinner after needs more hours than a drop-off and a set pickup, so describe the real pattern and let the quote price it.",`The same arithmetic on the ${v(Fe)} uses its own rate of ${ia(Fe)} an hour and its ${F(Fe)} seats; on the ${v(me)}, ${ia(me)} an hour for ${F(me)}. The ready-made packages on this page print the engine’s own total for their hours and extras, including any hour the rate ladder gives free.`,"One person collects the shares and one person owns the manifest. Neither job belongs to the chauffeur, and neither should wait until the group is standing at the curb after the round.")],Gs=[{question:"When is the WM Phoenix Open 2027?",answer:"Monday, February 8 to Sunday, February 14, 2027, at TPC Scottsdale. Monday and Tuesday are Ford Free Days with free general admission, and the four tournament rounds run Thursday, February 11 to Sunday, February 14."},{question:"Where is the Phoenix Open played?",answer:"On the Stadium Course at TPC Scottsdale, 17020 North Hayden Road, Scottsdale, AZ 85255. The entrances are the Main Entrance at Bell, the Hayden Entrance and the Fairmont Scottsdale Princess Golf Entrance."},{question:"What time do gates open at the Phoenix Open?",answer:"Entry opens at 7:00 a.m. at the Main and Princess entrances and at 7:15 a.m. at Hayden. Play begins at 7:30 a.m. on Thursday and Friday and 9:00 a.m. on Saturday and Sunday. The entry times are undated, so recheck them in January."},{question:"Is parking free at the Phoenix Open?",answer:"The 2027 parking plan and any price are announced closer to the date. In 2026, general parking used remote lots at WestWorld and at Salt River Fields, which had a free shuttle. With a chauffeured ride nobody in the group drives or parks."},{question:"Where do Uber and Lyft drop off at the Phoenix Open?",answer:"In 2026, rideshares, taxis and all stop-and-drop used Lot R, entered from Pima Road; the 2027 plan is announced closer to the date. For the Birds Nest, rideshare pickup and drop-off is on Hartford Drive, south of Princess."},{question:"Can a limo or party bus drop off at the Phoenix Open gate?",answer:"No official page gives a limo, party bus or charter a gate or drop-off privilege, and some lots are reserved for pass types, charter buses included. Our chauffeur unloads where traffic staff direct and follows any 2027 instruction the tournament publishes."},{question:"What does it cost to get into the Phoenix Open?",answer:"Monday, February 8 and Tuesday, February 9 are Ford Free Days: free admission, no ticket needed. Guests 15 and younger get in free. Other admission is sold through AXS; the official site says its link is coming soon, so 2027 prices are announced closer to the date."},{question:"Where is the Coors Light Birds Nest?",answer:"At 82nd Street and Bell Road, across from the main tournament entrance, Wednesday, February 10 to Saturday, February 13, 2027. It is 21 and over, headliners usually go on at about 8:30 p.m., and rideshares use Hartford Drive, south of Princess."},{question:"What happens at the 16th hole during Phoenix Open week?",answer:"The week opens with the Concert in the Coliseum on the 16th hole on Saturday, February 6, 2027: Imagine Dragons, with Counting Crows opening, for guests 21 and over, gates at 3:30 p.m. The WHOOP Shot at Glory is on the 16th at 3:30 p.m. on Wednesday, February 10."},{question:"What should I wear to the Phoenix Open?",answer:"The tournament’s FAQ sets no general dress code. Saturday, February 13 is Green Out Saturday: wear green, and a donation goes to its Working for Tomorrow fund. Keep bags small: opaque up to 6 by 6 by 6 inches, clear up to 12 by 6 by 12."}],Ls={path:$s,title:"WM Phoenix Open 2027: parking and getting there",metaTitle:"WM Phoenix Open 2027: Parking & Rides",description:"The WM Phoenix Open 2027 runs February 8–14 at TPC Scottsdale. The official dates and entry times, last year’s parking and stop-and-drop plan, the Birds Nest, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"Official Feb 8–14 dates, parking and drop-off, the Birds Nest, or a chauffeured ride",lastUpdated:or,lastUpdatedLabel:A(or),eyebrow:"Official dates: February 8–14, 2027",intro:"A Phoenix Open ride from Scottsdale Sprinters starts with the day your group is having: the 16th hole with the crew, a client day in hospitality, a round with the golf fans or a Birds Nest night. This guide uses only what the tournament and TPC Scottsdale publish, labels last year’s parking plan as last year’s, and says plainly what is announced closer to the date.",sections:Os,faqs:Gs,links:[{href:"/experiences/wm-phoenix-open",label:"WM Phoenix Open group transportation"},{href:"/guides/arabian-horse-show-transportation",label:"Arabian Horse Show at WestWorld, the same week"},{href:"/services/golf-outing-sprinter-van-scottsdale",label:"Golf outing transportation"},{href:`/fleet/${Ft}`,label:v(Ft)},{href:`/fleet/${me}`,label:v(me)},{href:`/fleet/${Fe}`,label:v(Fe)},{href:"/pricing",label:"Published hourly pricing"}],sources:Ws},vd=[Ls],cr="2026-09-24",_s="/guides/nba-all-star-weekend-2027",ha={vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],fans:["executive-sprinter-scottsdale","limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],corporate:["executive-luxury-bus-29-scottsdale","executive-white-sprinter-scottsdale","executive-mini-bus-26-scottsdale","motorcoach-56"]},Bs=[...ha.vip,...ha.fans,...ha.corporate].filter(Oe),no=Bs.map(e=>({slug:e,name:o[e],capacity:i[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours})),T="maybach-jet-sprinter-scottsdale",ur="ultra-luxury-party-sprinter-scottsdale",mt="maybach-shuttle-sprinter-8",gt="premium-suv-scottsdale",fe="executive-sprinter-scottsdale",Us="executive-luxury-bus-29-scottsdale",Hs="motorcoach-56",y=e=>o[e],_=e=>i[e],da=e=>l(s[e].hourlyRateCents);function pr(e,t,a){return l(Math.round(s[e].hourlyRateCents*t/a))}const qs=Math.max(...no.map(e=>e.capacity)),so="Your chauffeur waits; extra time is billed hourly at the vehicle’s rate — just call or text us to extend.",zs="https://www.nba.com/news/phoenix-suns-nba-all-star-2027-official-release",Vs="https://pr.nba.com/phoenix-to-host-nba-all-star-2027/",Js="https://www.phoenix.gov/major-events.html",Ys="https://mortgagematchupcenter.com/plan-your-visit/transportation-parking/",Zs="https://mortgagematchupcenter.com/venue/accessibility-ada-information/",js="https://mortgagematchupcenter.com/",Ks="https://mortgagematchupcenter.com/news/phoenix-suns-and-phoenix-mercury-announce-landmark-naming-rights-partnership-with-mortgage-matchup/",Qs=[{label:"NBA: Phoenix Suns to host NBA All-Star 2027 (official release)",href:zs},{label:"NBA Communications: Phoenix to host NBA All-Star 2027",href:Vs},{label:"City of Phoenix: major events, NBA All-Star 2027",href:Js},{label:"Mortgage Matchup Center: transportation and parking",href:Ys},{label:"Mortgage Matchup Center: accessibility, drop-off and pickup",href:Zs},{label:"Mortgage Matchup Center: bag policy and parking",href:js},{label:"Mortgage Matchup Center: the arena’s new name",href:Ks}];function ue(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Xs=[ue("When is NBA All-Star weekend 2027, and where is it?","NBA All-Star 2027 is in Phoenix from Friday, February 19 to Sunday, February 21, 2027. The 76th NBA All-Star Game is on Sunday, February 21, at Mortgage Matchup Center, home of the Phoenix Suns, at 201 East Jefferson Street in downtown Phoenix. Tip-off times are announced by the NBA closer to the date.","The NBA announced Phoenix as the host on March 7, 2024. Its release names the arena Footprint Center; it is the same building, renamed Mortgage Matchup Center by the Suns and the Mercury on October 2, 2025. Use that name when you book and when you give the address: 201 East Jefferson Street, Phoenix, AZ 85004, on the southeast corner of 1st Street and Jefferson.","As announced in March 2024, the on-court events start on Friday, February 19, with a showcase of top rookies and second-year players, then a Saturday night of contests on February 20, and the All-Star Game itself on Sunday, February 21. The NBA also plans a practice, a celebrity game and a fan fest at venues around Phoenix. Where and when each of those takes place is announced by the NBA closer to the date.","So this page prints no tip-off time, no Saturday venue and no fan-fest address. When the NBA publishes the 2027 schedule, the reservations team plans each pickup from it, not from a previous year’s weekend. Until then a quote can still hold the days, the hotel, the group size and the vehicle."),ue("Where do you park for the NBA All-Star Game, and where is drop-off?","For a game or event, Mortgage Matchup Center publishes 3rd Street, just south of Jefferson, at the green curb as its drop-off and pickup, and garages within walking distance bought ahead through ParkWhiz. The 2027 All-Star parking and traffic plan is announced closer to the date. With a chauffeured ride nobody drives or parks.","The arena’s own event-night plan, which is the one published now: several garages and lots within walking distance, with guests encouraged to buy parking in advance through ParkWhiz. Event parking is generally available from about 30 minutes before doors open, parking does not include in-and-out privileges, and availability, pricing and access may vary by event. The arena lists more than 700 on-site spaces and publishes no price.","Valet is available only for select ticketed guests and membership-based areas; it is not open to the general public. Vehicles cannot be parked or left unattended in the drop-off zones, so the curb on 3rd Street is a place to unload, not to wait. Drop-off for will call and the ticket office is on 1st Street, just north of Madison.","An All-Star weekend can bring its own street closures and a security perimeter around the arena. None is published for 2027, so this page does not guess one. Your chauffeur unloads at the arena’s published curb or where event and police staff direct, and the reservations team passes on any 2027 instruction the NBA or the city publishes."),ue("Where do rideshares drop off and pick up at Mortgage Matchup Center?","The arena lists 4 Lyft drop-off points: 1st Street at Jefferson by the arena plaza, South 2nd Street, South 3rd Street at the Phoenix Convention Center, and East Jefferson Street. Rideshare pickup is at South 3rd Street and East Jefferson Street, by the Phoenix Convention Center. A booked chauffeur uses the 3rd Street curb or where staff direct.","After a game every rideshare in downtown Phoenix is heading for the same corner. A chauffeured vehicle is booked before the weekend, so the group is not waiting on surge pricing or a car that cannot reach the pin. Name one meeting point before going in, and one person who counts heads before anyone walks to the curb.","Light rail is the other published option: the arena says light rail fare is included in a ticket to any game or event there, bus fare excepted. Stations and bus stops are on accessible routes. That helps a guest who is staying downtown; a group coming from a Scottsdale resort usually wants the door-to-door ride."),ue("Which vehicle fits an All-Star VIP, fan or corporate group?",`VIP and courtside guests lead with the ${y(T)}, which seats ${_(T)}, then the ${y(ur)}, the ${y(mt)} and the ${y(gt)}; friends and fan crews ride the ${y(fe)} or a Limo Party Sprinter; corporate hosts take the mini coach, the white Sprinter, the mini bus or the full-size coach.`,`The table uses current published names, seated capacities, hourly rates and minimums, in the page’s three groups. VIP and courtside guests: the ${y(T)}, our pick for All-Star weekend, seats ${_(T)} at ${da(T)}/hr in a private jet cabin with Maybach massage recliners, a wet bar and a full partition, then the ${y(ur)}, the ${y(mt)} and the ${y(gt)}.`,`A VIP party larger than the ${y(T)} rides in two vehicles, one booking each for the same times: the ${y(T)} with the ${y(mt)} seats ${_(T)+_(mt)}, and with the ${y(gt)} it seats ${_(T)+_(gt)}. Friends and fan crews: the ${y(fe)} and the two Limo Party Sprinters. Corporate hospitality: the ${y(Us)}, the Executive White Sprinter, the Mini Bus and the ${y(Hs)}, the largest in the table at ${qs} seats.`,"Count riders for each direction. The ride to the game and the ride home are often different lists, and a guest who leaves with another host should come off the return manifest before seats are assigned. Arrive without bags where you can: the arena encourages it, allows small clutches and crossbody bags, and does not allow standard backpacks inside."),ue("How does pickup after the All-Star Game work downtown?","Plan 2 steps: the group gathers at one meeting point the chauffeur and the transportation lead agreed before tip-off, then walks to the vehicle together once the lead confirms where it is. No vehicle may wait in the arena’s drop-off zone, so the chauffeur clears the curb after drop-off and comes back for the group.",`What if the game runs late? ${so}`,"Book by the hour and the vehicle is yours for the whole block: the dinner before, the arena, the after-party and the ride back to the hotel. A ride there and a ride back is the other shape; it suits a group that knows it will leave with the crowd. Either way the chauffeur follows event and police staff on the day.","For more than one return wave, label each vehicle, its lead and its hotel. A VIP group heading to a resort and a client group heading to another hotel should not rely on spotting a driver in a crowd. The final sweep checks the manifest before the vehicle rolls."),ue("Can one booking cover the whole All-Star weekend?","Each day is its own booking by the hour, and one request can hold all 3 days, February 19 to 21: the reservations team quotes each day’s vehicle and hours together. Friday and Saturday times are announced by the NBA closer to the date, so those blocks stay flexible until the schedule is out.","A weekend plan often starts at the airport: a VIP guest landing at Phoenix Sky Harbor can be met there and driven to the hotel, and the rest of the weekend fills in around the game, with dinners, a hotel party and the fan events once the NBA names their venues.","Write one line per day: the pickup address and ready time, the destination, the return rule, and the name of the person who owns the headcount. Leave the unannounced lines open rather than copying last year’s weekend, and let the reservations team fill them in when the NBA publishes the 2027 schedule."),ue("How far ahead should All-Star weekend transportation be booked?",`No fixed lead time applies: availability for February 19 to 21 varies by vehicle, and the ${_(T)}-seat ${y(T)} is a single unit. Request a quote with the days, the hotel, the rider count and the group, and the reservations team confirms what is open and holds it in writing.`,"The first request needs the days, the lodging or pickup area, the likely passenger count and which group is riding: VIP and courtside guests, a fan crew or a corporate hospitality list. A group does not need every name to begin, but it should separate committed riders from possible ones.",`In the final 48 hours, verify addresses, contact numbers and the newest NBA and arena directions, and send one summary to riders. If staff change the approach on the day, the chauffeur follows them and the transportation lead relays the update. Reach the reservations team at ${C} or ${E}.`),ue("How is All-Star transportation priced per person?",`For ${_(T)} guests sharing the ${y(T)} across 5 billed hours, its published ${da(T)}-per-hour rate works out to about ${pr(T,5,_(T))} per person before tax for the whole shared ride; the price changes with the vehicle, the hours, the add-ons and the confirmed plan.`,`The same arithmetic for a fan crew of ${_(fe)} in the ${y(fe)} at ${da(fe)}/hr for 5 hours is about ${pr(fe,5,_(fe))} each. It is hourly rate times billed hours, divided by riders, not a flat game-night fare. If fewer people ride, divide across fewer.`,"Every vehicle has a minimum number of hours, shown in the table. The ready-made packages on this page add extras from the published add-on list, and each one is priced by the same engine as the vehicle, so the number on the tile is the number at checkout, before tax.")],ei=[{question:"When is NBA All-Star weekend 2027?",answer:"Friday, February 19 to Sunday, February 21, 2027, in Phoenix. The NBA All-Star Game is on Sunday, February 21. The full weekend schedule and tip-off times are announced by the NBA closer to the date."},{question:"Where is the 2027 NBA All-Star Game?",answer:"At Mortgage Matchup Center, home of the Phoenix Suns, 201 East Jefferson Street, Phoenix, AZ 85004. The NBA’s 2024 announcement calls it Footprint Center; the arena was renamed in October 2025."},{question:"What time does NBA All-Star 2027 start?",answer:"Not yet announced. The NBA publishes tip-off times for the Friday, Saturday and Sunday events closer to the date. Book the day now and the reservations team sets the pickup time once the schedule is out."},{question:"Where do you park for the All-Star Game at Mortgage Matchup Center?",answer:"On a normal event night, in the garages and lots within walking distance, bought ahead through ParkWhiz, with no in-and-out. Valet is not open to the general public. The All-Star weekend parking plan is announced closer to the date."},{question:"Where is drop-off at Mortgage Matchup Center?",answer:"On 3rd Street, just south of Jefferson, at the green curb, for games and events. Vehicles cannot wait there, so a chauffeur unloads, clears the curb and comes back for the group at the time you set."},{question:"Is Mortgage Matchup Center the same as Footprint Center?",answer:"Yes. The Suns and the Mercury renamed Footprint Center as Mortgage Matchup Center on October 2, 2025. It is the same arena at 201 East Jefferson Street in downtown Phoenix."},{question:"What if the game runs late?",answer:so},{question:"Does a ride booking include All-Star tickets?",answer:"No. Buy tickets only through the NBA’s official channels; a ride booking does not include tickets, credentials or hospitality. Scottsdale Sprinters is not affiliated with the NBA, the Phoenix Suns or Mortgage Matchup Center."}],ti={path:_s,title:"NBA All-Star 2027 in Phoenix: the weekend, the arena and getting there",metaTitle:"NBA All-Star 2027 Weekend in Phoenix",description:"NBA All-Star 2027 is in Phoenix, February 19–21, with the All-Star Game on Sunday, February 21, at Mortgage Matchup Center. The official dates, what is announced and what is not, the arena’s parking, drop-off and rideshare points, and a chauffeured ride so nobody drives or parks.",metaDescription:"Feb 19–21 in Phoenix, the game at Mortgage Matchup Center, parking, drop-off, and a chauffeured ride",lastUpdated:cr,lastUpdatedLabel:A(cr),eyebrow:"Official dates: February 19–21, 2027",intro:`An All-Star ride from Scottsdale Sprinters starts with the NBA’s own announcement, a realistic rider count and one transportation lead. VIP and courtside guests lead with the ${y(T)}; friends and fan crews ride the ${y(fe)} or a Limo Party Sprinter; corporate hosts take the mini coach, the mini bus or the full-size coach. This guide uses only published NBA and arena facts, leaves the unannounced schedule for closer to the date, and turns each day of the weekend into a written pickup, arrival and return plan. Scottsdale Sprinters is not affiliated with the NBA, the Phoenix Suns or Mortgage Matchup Center.`,sections:Xs,faqs:ei,links:[{href:"/fleet/maybach-jet-sprinter-scottsdale",label:o[T]},{href:"/guides/venues/footprint-center",label:"Footprint Center group arrival guide"},{href:"/services/corporate-transportation-scottsdale",label:"Scottsdale corporate transportation"},{href:"/experiences/corporate-event",label:"Corporate event transportation planning"},{href:"/fleet",label:"Fleet capacities"},{href:"/pricing",label:"Published hourly pricing"}],sources:Qs,fleetRows:no},kd=[ti],fr="2026-09-24",ai="/guides/cactus-league-spring-training",tt="maybach-jet-sprinter-scottsdale",at="ultra-luxury-party-sprinter-scottsdale",mr="maybach-shuttle-sprinter-8",gr="premium-suv-scottsdale",yr="limo-sprinter-13-scottsdale",Dt="limo-sprinter-16-scottsdale",la="party-bus-28-scottsdale",rt="executive-sprinter-scottsdale",ri="executive-white-sprinter-scottsdale",wr="executive-mini-bus-26-scottsdale",ca="executive-luxury-bus-29-scottsdale",k=e=>o[e],B=e=>i[e],oi="https://cactusleague.com/schedule.php",ni="https://www.mlb.com/giants/spring-training/a-z-guide",si="https://saltriverfields.com/welcome-to-salt-river-fields/",ii="https://saltriverfields.com/parking/",hi="https://www.mlb.com/camelback-ranch/your-visit/information-and-policies",di="https://www.mlb.com/cubs/sloan-park/transportation",li="https://www.mlb.com/athletics/spring-training/guide",ci="https://www.mlb.com/angels/spring-training/ballpark",ui="https://www.mlb.com/brewers/spring-training/trip-planning",pi="https://www.peoriasportscomplex.com/spring-training/find-info/maps-directions",fi="https://www.surprisestadium.com/stadium-info/stadium-a-z",mi="https://www.goodyearbp.com/Ballpark-Visitors/Directions-and-Parking",gi="https://www.mlb.com/guardians/spring-training/a-to-z-guide",yi="https://www.mlb.com/news/mlb-commissioner-rob-manfred-on-initial-cba-proposals",wi=[{label:"Cactus League 2027 schedule",href:oi},{label:"Scottsdale Stadium spring training A to Z (San Francisco Giants)",href:ni},{label:"Welcome to Salt River Fields: rideshare and address",href:si},{label:"Salt River Fields parking and directions",href:ii},{label:"Sloan Park transportation (Chicago Cubs)",href:di},{label:"Camelback Ranch information and policies",href:hi},{label:"Hohokam Stadium spring training guide (Athletics)",href:li},{label:"Tempe Diablo Stadium ballpark information (Angels)",href:ci},{label:"American Family Fields of Phoenix trip planning (Brewers)",href:ui},{label:"Peoria Sports Complex maps and directions",href:pi},{label:"Surprise Stadium A to Z",href:fi},{label:"Goodyear Ballpark directions and parking",href:mi},{label:"Goodyear Ballpark spring training A to Z (Cleveland Guardians)",href:gi},{label:"MLB.com: the collective bargaining agreement’s expiry date",href:yi}];function pe(e,t,...a){return{question:e,answer:t,paragraphs:a}}const bi={head:["Ballpark (teams)","Drop-off or rideshare","Parking and gates"],rows:[["Camelback Ranch-Glendale (Dodgers, White Sox)","None published; staff direct","Free, no overnight parking; gates 60 minutes before first pitch"],["Hohokam Stadium, Mesa (Athletics)","None published; staff direct","Cash only; gates 1.5 hours before game time"],["Tempe Diablo Stadium (Angels)","Just outside the Alameda Drive entrance to the west lot, never inside it","Cashless; lots open 2.5 hours before home games"],["American Family Fields of Phoenix (Brewers)","Along 53rd Avenue and Indian School, outside the lot","Sold on the day, card only, more for larger vehicles; lots open 3 hours before"],["Peoria Sports Complex (Padres, Mariners)","Stadium Way and Paradise Lane, west of Gate D; buses at Mariners Way","Free, no overnight parking; gates about 90 minutes before"],["Surprise Stadium (Rangers, Royals)","Loading zone just north of the Surprise Aquatic Center","Free, more than 1,600 spaces; gates 1.5 hours before"],["Goodyear Ballpark (Guardians, Reds)","VIP lot off Wood Boulevard, or the Third Base Entrance","Free with a game ticket; gates 1.5 hours before"]]},vi=[pe("Is there parking at Scottsdale Stadium, and where is the drop-off?","Very little. The Giants say parking at Scottsdale Stadium is very limited, with a select number of spaces at the Scottsdale Library and Civic Center, and they encourage fans to walk, bike or take rideshare. The drop-off zones are at Gate A on 75th Street and Gate E on Drinkwater Boulevard, and gates open 2 hours before game time.","The Osborn Road lot is reserved for Giants and City of Scottsdale personnel only, so it is not a place to park or to wait. The stadium has four gates: Home Plate Plaza at Drinkwater Boulevard and Osborn Road, Gate A in centerfield facing 75th Street, Gate E on the third-base side along Drinkwater Boulevard, and Gate F in the left-field corner.","The Giants list the Gate A and Gate E drop-off zones under accessibility. We treat them as the stadium’s published drop-off points, never as a spot reserved for us: the chauffeur unloads at the zone, or where stadium and city staff direct, and the group walks in from there. A 2027 spring training trolley has not been announced.","The chauffeured alternative is the simple one: we pick the group up at the hotel or home, nobody hunts for one of the few spaces, and the vehicle comes back for the ride home after the last out. Game times are announced closer to the date, so the pickup is set once the league posts them."),pe("Where do you park at Sloan Park, and where do rideshares drop off?","Sloan Park’s lots open 4 hours before Cubs spring training games, and gameday parking is first come, first served and cashless, by credit card. Rideshares drop off and pick up outside the Right Field Gate, across Sheffield Avenue, and a free shuttle runs from Mesa Riverview, across from the park, to Cubs home games.","Tempe Marketplace also runs a trolley to and from Cubs home games at Sloan Park. Both shuttles drop off at the First Base Gate. Parking prices depend on the lot, and the Cubs sell a limited number of pre-sale single-game and group spaces in the Purple Lot.","Sloan Park is the Cubs’ spring home in Mesa, and the league’s last game of 2027, the Brewers at the Cubs on Tuesday, March 23, is played there. A chauffeured group uses the published rideshare point outside the Right Field Gate, or unloads where staff direct, and meets the vehicle at the same side of Sheffield Avenue after the game."),pe("Where do rideshares and drop-offs go at Salt River Fields?","Salt River Fields at Talking Stick, at 7555 North Pima Road in Scottsdale, suggests the access road along the grass-field parking lots, or the Centerfield Parking Lots, for pickup and drop-off. There are 3 entrances off Pima Road. It is the spring home of the Diamondbacks and the Rockies.","The ballpark’s 2027 lot prices and its accessible drop-off are not yet published: its A to Z still describes the 2026 season, so this page prints neither. Our Salt River Fields arrival guide keeps the venue’s own sources in one place.","Salt River Fields and Scottsdale Stadium are the two Scottsdale ballparks. For the ride back, the group gathers at one pedestrian point first and the trip lead confirms the vehicle’s position before anyone walks toward traffic; event-day signs and staff direct the actual vehicle movement."),{...pe("Where do you park and get dropped off at the other Cactus League ballparks?","Each park sets its own rules. Camelback Ranch, Peoria Sports Complex and Surprise Stadium park free, and Goodyear Ballpark is free with a game ticket; Hohokam Stadium is cash only, and Tempe Diablo and American Family Fields are cashless or card only. Only Peoria publishes a bus drop-off, at Mariners Way off 83rd Avenue.","Camelback Ranch-Glendale (the Dodgers and the White Sox): parking is free, with no overnight parking, and the gates open 60 minutes before first pitch. No rideshare or drop-off zone is published, so the chauffeur unloads where ballpark staff direct.","Hohokam Stadium in Mesa (the Athletics): on-site parking is cash only, and the gates open 1.5 hours before game time. No rideshare or drop-off zone is published.","Tempe Diablo Stadium (the Angels): rideshare drop-off and pickup is just outside the Alameda Drive entrance to the west parking lot, and no pickup or drop-off is allowed inside that lot. Both lots are entered from Alameda Drive and open 2.5 hours before home games, and the venue is cashless.","American Family Fields of Phoenix (the Brewers): drop-offs and rideshares use the designated space along 53rd Avenue and Indian School, outside the parking lot. Parking is sold on the day only, by card, with more charged for oversized and larger vehicles, and the lots open 3 hours before the game.","Peoria Sports Complex, 16101 North 83rd Avenue (the Padres and the Mariners): rideshare pickup and drop-off is near Stadium Way and Paradise Lane, just west of the Gate D entrance. Buses enter at Mariners Way off 83rd Avenue, where the bus passenger drop-off is. Parking is free, with no overnight parking, and the gates typically open 90 minutes before the published game time.","Surprise Stadium (the Rangers and the Royals): the designated rideshare and drop-off loading zone is just north of the Surprise Aquatic Center. Parking is free, with more than 1,600 spaces, and the gates open 1.5 hours before game time.","Goodyear Ballpark, 1933 South Ballpark Way (the Guardians and the Reds): rideshare pickup and drop-off is in the VIP parking lot, reached from Wood Boulevard north of Lower Buckeye Road, and drop-off is also available at the Third Base Entrance. Parking is free with a game ticket, with no overnight parking, and the gates open 1.5 hours before game time."),table:bi},pe("When is spring training in Arizona in 2027?","As scheduled by the Cactus League, Opening Day is Friday, February 19, 2027, with 8 games, and the last Cactus League game is Tuesday, March 23, 2027. That is 229 games in about five weeks. Game times are announced closer to the date: the league lists every one of them as to be determined.","One date to know before you book: Major League Baseball’s collective bargaining agreement with its players is set to expire on December 1, 2026. The dates on this page are the Cactus League’s published schedule. We recheck them after December 1 and update this page if the league changes anything.",`If a game you planned around moves, every booking allows one free date change when you ask ${Yr} or more hours before pickup, subject to availability: the deposit travels to the new date and the new date’s rate applies.`,`Saturday and Sunday games in the Cactus League window, February 19 to March 23, 2027, are major-event dates on our booking calendar, so they run on the ${bo}-day major-event cancellation window, with the deposit non-refundable. Weekday games follow the standard or large-group terms, depending on the size of the group. The booking step flags a major-event date before anything is paid.`),pe("Where is spring training in Arizona, and which teams play where?","Fifteen Major League teams train at 10 ballparks around Phoenix: Scottsdale Stadium and Salt River Fields in Scottsdale, Sloan Park and Hohokam Stadium in Mesa, Tempe Diablo Stadium, Camelback Ranch-Glendale, American Family Fields of Phoenix, Peoria Sports Complex, Surprise Stadium and Goodyear Ballpark.","Scottsdale Stadium: the Giants. Salt River Fields at Talking Stick: the Diamondbacks and the Rockies. Sloan Park: the Cubs. Hohokam Stadium: the Athletics. Tempe Diablo Stadium: the Angels. Camelback Ranch-Glendale: the Dodgers and the White Sox. American Family Fields of Phoenix: the Brewers. Peoria Sports Complex: the Padres and the Mariners. Surprise Stadium: the Rangers and the Royals. Goodyear Ballpark: the Guardians and the Reds.","The two Scottsdale parks, the two Mesa parks and Tempe Diablo are in the East Valley; Camelback Ranch, American Family Fields, Peoria, Surprise and Goodyear are in the West Valley. A two-ballpark day is simplest between neighbours, and it is one hourly booking: the first game, lunch, the second park and the ride home, confirmed once both game times are posted.","Which team plays where on a given day is the league’s to publish. Check the official Cactus League schedule for the game, buy the tickets from the teams, and send us the game or games; we build the pickup, the wait and the return around them in writing."),pe("Which vehicle fits a spring training group?",`Match the vehicle to the day: ballpark crews and bachelor groups ride a Limo Party Sprinter or the ${k(la)}, families and fan clubs take the ${k(rt)} or an executive coach for up to ${B(ca)}, and VIP groups ride the ${k(tt)} or the ${k(at)}.`,`Ballpark crews and bachelor groups: the ${k(yr)} is a nightclub on wheels with a wet bar for ${B(yr)}, the ${k(Dt)} is our most spacious Sprinter, a lounge for ${B(Dt)} with four wet bars, and the ${k(la)} puts ${B(la)} on limo seating on a wood floor when the whole crew comes. These are party rides, for a group out to celebrate.`,`Families and fan clubs: the ${k(rt)} and the ${k(ri)} seat ${B(rt)} each in reclining leather, a cup holder at every seat and room for the gear. The ${k(wr)} (${B(wr)} seats) and the ${k(ca)} (${B(ca)} seats) carry a fan club or a company outing in one pickup.`,`VIP groups: the ${k(tt)} leads, ${B(tt)} seats with four Maybach massage recliners and a wet bar. The ${k(at)} seats ${B(at)} in a fiber-optic lounge with ultra-premium sound, our pick for a ballpark day that ends in Old Town. The ${k(mr)} seats ${B(mr)} in custom Maybach seats, and the ${k(gr)} carries up to ${B(gr)}.`,"Count riders for each direction. A group that arrives together for first pitch does not always leave together, and anyone leaving with another group comes off the return list before the chauffeur plans the pickup."),pe("Can a party bus, limo or charter drop off at a spring training ballpark?","Only Peoria Sports Complex publishes a bus rule: buses enter at Mariners Way off 83rd Avenue, where the bus passenger drop-off is. None of the 10 ballparks publishes a permit rule for limos or party buses, so our chauffeur uses the park’s published drop-off or rideshare zone, or unloads where staff direct.","Two other published rules matter for a bigger vehicle. American Family Fields charges more for oversized and larger vehicles that park, and Tempe Diablo Stadium allows no pickup or drop-off inside its west lot. Where the vehicle waits during the game is confirmed with the reservations team before the day, not decided at the gate.","For the ride back, name one meeting point and one trip lead before the group goes in. After the last out the lead counts heads, confirms the vehicle’s position with the chauffeur and walks the group there together, rather than everyone chasing a map pin at once.",`We are a chauffeured transportation service. We do not sell tickets, parking passes or admission, and a ride includes none of them. Questions this page does not answer go to the reservations team at ${C} or ${E}.`)],ki=[{question:"When is spring training in Arizona in 2027?",answer:"As scheduled by the Cactus League, Opening Day is Friday, February 19, 2027, with eight games, and the last Cactus League game is Tuesday, March 23, 2027. Game times are announced closer to the date."},{question:"Where is spring training in Arizona?",answer:"At ten ballparks around Phoenix: Scottsdale Stadium and Salt River Fields in Scottsdale, Sloan Park and Hohokam Stadium in Mesa, Tempe Diablo Stadium, Camelback Ranch-Glendale, American Family Fields of Phoenix, Peoria Sports Complex, Surprise Stadium and Goodyear Ballpark."},{question:"What teams have spring training in Arizona?",answer:"Fifteen: the Giants, the Diamondbacks and Rockies, the Dodgers and White Sox, the Cubs, the Athletics, the Angels, the Brewers, the Padres and Mariners, the Rangers and Royals, and the Guardians and Reds."},{question:"What is the Cactus League?",answer:"Major League Baseball’s spring training in Arizona. In 2027, as scheduled by the Cactus League, 15 teams play 229 games at 10 ballparks from February 19 to March 23."},{question:"Is there parking at Scottsdale Stadium?",answer:"Very little. The Giants say parking is very limited, with a select number of spaces at the Scottsdale Library and Civic Center, and encourage walking, biking or rideshare. The drop-off zones are at Gate A on 75th Street and Gate E on Drinkwater Boulevard."},{question:"Where do you park at Sloan Park?",answer:"The lots open four hours before Cubs spring training games; parking is first come, first served and cashless. Rideshares use the point outside the Right Field Gate, across Sheffield Avenue, and a free shuttle runs from Mesa Riverview."},{question:"Where do rideshares drop off at Salt River Fields?",answer:"On the access road along the grass-field parking lots, or at the Centerfield Parking Lots. Salt River Fields is at 7555 North Pima Road, with three entrances off Pima Road."},{question:"Where do you park at Camelback Ranch?",answer:"Parking at Camelback Ranch-Glendale is free, with no overnight parking, and the gates open 60 minutes before first pitch. No rideshare or drop-off zone is published."},{question:"Could the MLB labor talks change the 2027 dates?",answer:`MLB’s collective bargaining agreement with its players is set to expire on December 1, 2026. The dates here are the Cactus League’s published schedule; we recheck them after December 1, and every booking allows one free date change ${Yr} or more hours before pickup.`},{question:"Do you sell spring training tickets or parking?",answer:"No. We sell chauffeured transportation only. Tickets come from the teams and the league, and parking from the ballparks; with a chauffeured ride, nobody in the group needs a parking space."}],Si={path:ai,title:"Spring Training 2027 in Arizona: ballpark drop-off, parking and rides",metaTitle:"Spring Training 2027: Parking & Rides",description:"Cactus League spring training 2027 runs February 19 to March 23 at ten ballparks around Phoenix. The official dates, the fifteen teams, each ballpark’s parking, rideshare and drop-off rules, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"Feb 19 – Mar 23 dates, parking and drop-off at all 10 ballparks",lastUpdated:fr,lastUpdatedLabel:A(fr),eyebrow:"As scheduled: February 19 to March 23, 2027",intro:"A spring training ride from Scottsdale Sprinters starts with the day your group is having: a ballpark crew or a bachelor weekend at the game, a family or a fan club with a few games on the list, or a VIP day in the Maybach Jet. This guide covers the ten Cactus League ballparks with only what the league, the teams and the ballparks publish, and says plainly what is announced closer to the date.",sections:vi,faqs:ki,links:[{href:"/experiences/spring-training",label:"Spring training group transportation: rates and two-game days"},{href:"/guides/venues/salt-river-fields",label:"Salt River Fields group arrival guide"},{href:"/guides/scottsdale-event-transportation",label:"Scottsdale event transportation guide"},{href:"/services/bachelor-party-transportation-scottsdale",label:"Bachelor party transportation"},{href:`/fleet/${at}`,label:k(at)},{href:`/fleet/${Dt}`,label:k(Dt)},{href:`/fleet/${rt}`,label:k(rt)},{href:`/fleet/${tt}`,label:k(tt)},{href:"/pricing",label:"Published hourly pricing"}],sources:wi},Sd=[Si],br="2026-09-24",Ai="/guides/phoenix-raceway-nascar-transportation",ge="maybach-jet-sprinter-scottsdale",ye="ultra-luxury-party-sprinter-scottsdale",vr="maybach-shuttle-sprinter-8",kr="premium-suv-scottsdale",Sr="limo-sprinter-13-scottsdale",be="limo-sprinter-16-scottsdale",yt="party-bus-28-scottsdale",Ar="executive-sprinter-scottsdale",Tr="executive-mini-bus-26-scottsdale",$r="executive-luxury-bus-29-scottsdale",ua="motorcoach-56",b=e=>o[e],D=e=>i[e],pa=e=>l(s[e].hourlyRateCents);function Ti(e,t,a){return l(Math.round(s[e].hourlyRateCents*t/a))}const wt=10,Pr=9,Cr=D(be),$i="https://www.phoenixraceway.com/events/spring-cup-race/",Pi="https://www.phoenixraceway.com/schedule/",Ci="https://www.phoenixraceway.com/parkingdirections/",Ei="https://www.phoenixraceway.com/faqs/",Fi="https://www.phoenixraceway.com/phx-weekend-schedule/",Di="https://www.phoenixraceway.com/hospitality/",Ii="https://www.phoenixraceway.com/about-phoenix-raceway/",xi="https://speedwaymedia.com/2026/08/05/phoenix-raceway-unveils-power-packed-2027-race-schedule/",Ri=[{label:"Phoenix Raceway: the 2027 spring NASCAR weekend, days and tickets",href:$i},{label:"Phoenix Raceway event calendar: spring and fall 2027 dates",href:Pi},{label:"Phoenix Raceway parking and directions: free parking, entries and routes",href:Ci},{label:"Phoenix Raceway FAQs and gate policy",href:Ei},{label:"Phoenix Raceway weekend schedule (the October 2026 race weekend)",href:Fi},{label:"Phoenix Raceway spring hospitality: suites, Ally Curve and The Perch",href:Di},{label:"Phoenix Raceway track facts",href:Ii},{label:"Phoenix Raceway 2027 schedule release (August 5, 2026)",href:xi}];function Q(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Er=[["Old Town Scottsdale","31.1","about 44 minutes"],["The Phoenician","30.5","about 43 minutes"],["Phoenix Sky Harbor (PHX)","26.0","about 35 minutes"],["Kierland / Scottsdale Quarter","39.1","about 53 minutes"],["Scottsdale Airport (SDL)","39.4","about 52 minutes"],["Fairmont Scottsdale Princess","43.3","about 52 minutes"]],Mi=[Q("Where do you park at Phoenix Raceway, and is parking free?","Parking is free for ticket holders: with no pass, follow the signs from I-10 to the free general lots at Entries J, K and L. Paid Premium, El Mirage and Preferred passes park closer to the gates. With a chauffeured ride from Scottsdale, nobody in the group drives the 31 miles or parks.","The track says it plainly: Phoenix Raceway offers free general parking to ticket holders. Without a parking pass, follow the directional signage from I-10 to the free lots on site; the general-admission entries are J, K and L. A parking tram runs along Kevin Harvick Road from Cotton Lane to Blue 6, and a camping shuttle runs the Mountain Road route from Gate 2 to Dunes North 5.","Paid passes, sold by the track for the spring and fall weekends, buy distance. Premium Parking is a reserved spot, the closest parking to the gates, by Gates 4 and 5 at Entry E. El Mirage Parking is closest to the ticket gates, at Entry F. Preferred Parking is a reserved spot on asphalt, entered through Entry G. Suite guests park at Entry C. Pass holders follow the map printed on the back of their pass.","Accessible parking: guests with a state-issued plate or placard exit I-10 at Avondale Boulevard, Exit 131, head south and follow the blue route signs. Spaces are first come, first served until the lots fill, and then traffic control directs cars to general parking, so the track advises arriving early.","The chauffeured alternative: we pick the group up at the hotel or home in Scottsdale, drive the approach and unload where race-day traffic staff direct. Nobody hunts for a lot, rides a tram back after the checkered flag or drives the interstate home after a long day in the sun. No lot or lane is published for hired vehicles, so the reservations team confirms the current instruction before race day rather than promising one."),Q("Where do Uber, Lyft and drop-offs go at Phoenix Raceway?","At Phoenix Raceway, 7602 Jimmie Johnson Drive in Avondale, rideshares and taxis use Entry E, the entry the track lists for Uber, Lyft and taxis, shared with Premium and Ally Curve parking. No entry is published for limos, party buses or charters, so a chauffeured vehicle unloads where race-day traffic staff direct.","Entry E is the only drop-off the track names for a hired ride, and it names rideshare apps and taxis, not limos or buses. Suite guests park at Entry C, and The Perch, a hospitality area, is sold with the convenience of bringing in your own motor coach. None of that is a privilege a chauffeured Sprinter or coach can claim, so this page promises no gate, lane or curb.","On the day, the chauffeur follows the signs from I-10 and the traffic staff, unloads the group where directed, and waits where staff assign. If the track publishes a 2027 instruction for hired vehicles, the reservations team passes it on before race day.","For the ride home, name one meeting point and one transportation lead before the group goes in. The curb you arrived at may not be where a vehicle can wait at the end of the race, and phones struggle when a grandstand empties at once. The lead counts heads, confirms the vehicle’s spot with the chauffeur and walks the group there together."),{...Q("How far is Phoenix Raceway from Scottsdale, and which way do you drive?","Phoenix Raceway is in Avondale, about 31 miles and 44 minutes from Old Town Scottsdale by I-10 West without race traffic, and about 53 minutes from Kierland. The track sits about 6 miles south of I-10 at Exit 131, Avondale Boulevard; drivers headed for general parking use Exit 126 or 128.",`Measured with Google Directions on September 24, 2026, driving, with no race traffic: ${Er.map(([e,t,a])=>`${e}, ${t} miles, ${a}`).join("; ")}. Every route runs on I-10 West.`,"The track’s own routes, for guests driving themselves: on I-10 West, or coming down I-17 or Loop 101 to I-10 West, general parking uses Exit 126 (Estrella Parkway) or Exit 128 (Litchfield Road), and parking-pass and ADA traffic uses Exit 131 (Avondale Boulevard). From Loop 202 North, general parking uses Exit 76 (Buckeye Road) and passes use Exit 73 (Broadway Road). ADOT’s traveler line is 511, or az511.com.","Race traffic is not normal traffic. Those minutes are Google’s typical times, not race-day times, so the chauffeur builds the buffer into the pickup: the drive, the approach to the lots, screening at the gate and the walk to the seats. The return is a window rather than a fixed minute: the race’s length, the crowd and the lots decide it."),table:{head:["From","Miles","Typical drive"],rows:Er.map(([e,t,a])=>[e,t,a])}},{...Q("When is NASCAR at Phoenix Raceway in 2027?","The spring race weekend runs Friday, March 12 to Sunday, March 14, 2027. Friday is the ARCA Menards Series race, Saturday, March 13 puts IndyCar and the NASCAR O’Reilly Auto Parts Series on one card, and the NASCAR Cup Series races on Sunday, March 14. Start times are announced closer to the date.","The track’s calendar lists the 2027 spring weekend as March 12 to 14, with times to be decided, and its schedule release says the full 2027 NASCAR and NTT INDYCAR SERIES schedules, with broadcast details and times, will be released at a later date. Tickets, hospitality and camping are already on sale from the track: Sunday only, Saturday only, or a 2-day package for Saturday and Sunday.","NASCAR comes back in the fall: the track lists its 2027 fall weekend as October 22 to 24, with the Truck Series on Friday, the O’Reilly Auto Parts Series and ARCA Menards Series West on Saturday, and the Cup Series race on Sunday, October 24.","For a ride, pick the day first: Sunday is the Cup race, Saturday puts 2 races on one card, and Friday is the ARCA race. A group staying for the whole weekend books each day as its own ride, so no vehicle sits idle overnight in Avondale."),table:{head:["Day","Date","On track"],rows:[["Friday","March 12, 2027","ARCA Menards Series"],["Saturday","March 13, 2027","IndyCar and the NASCAR O’Reilly Auto Parts Series"],["Sunday","March 14, 2027","NASCAR Cup Series"]]}},Q("What time do the gates open at Phoenix Raceway?","2027 gate and race times are announced closer to the date. On the track’s most recent published schedule, for the October 2026 weekend, Sunday’s lots open at 6:00 a.m., the gates at 8:00 a.m. and the Cup race starts at 12:00 p.m.; Saturday’s lots open at 8:00 a.m. and the gates at 10:00 a.m.","The same October 2026 schedule runs the parking trams from 6:00 a.m. on Sunday until an hour after the race, and on Friday opens the lots at 9:30 a.m. and the gates at 11:30 a.m. It is the track’s schedule for a different weekend, printed here only to show how early a race day starts; the March 2027 times replace it when the track publishes them.","What that means for a pickup: a group that wants the pre-race, a meal and its seats before the green flag leaves Scottsdale in the morning, well before the start. Your chauffeur sets the ready time from the published 2027 schedule once it is out, and from your seats and plans until then.","The Infield Experience, the suites and Ally Curve open with the spectator gates on that schedule. On race day, pit road access for Infield Experience pass holders ends one hour before the race, by the track’s own FAQ."),Q("How many hours should you book for a race day at Phoenix Raceway?",`Plan about ${wt} hours for Cup Sunday and ${Pr} for Saturday’s two-race card, from pickup in Scottsdale to drop-off at home. The drive is about 45 minutes each way from Old Town before race traffic, the gates open hours before the start, and after the checkered flag the lots take time to clear, so the vehicle waits with the group.`,`Where the ${wt} hours go on a Sunday, with the track’s most recent published race day as the model: about 45 minutes out from Old Town, more with race traffic; arriving before the gates so the group is in its seats well ahead of the green flag; the race itself, which runs for hours; and the wait after the checkered flag while the lots empty. Booked by the hour, the vehicle is yours for the whole block: it waits while the lots clear instead of the group standing in them, and nobody drives the interstate home after a day in the sun.`,`Saturday is shorter on the clock but puts 2 races on one card, IndyCar and the O’Reilly Auto Parts Series; ${Pr} hours covers both and the drive. A group that wants only one race, or a drop-off and a set pickup, books fewer hours: tell the reservations team the plan and the quote prices it.`,"If the race runs long, from caution laps or a weather delay, your chauffeur waits; extra time is billed hourly at the vehicle’s rate — just call or text us to extend.","The ready-made packages on this page are built on those hours, and each prints the engine’s own total, including any hour the rate ladder gives free."),Q("Which vehicle fits a race-day group?",`VIP and infield guests ride the ${b(ge)} or the ${b(ye)}, race-day crews take a Limo Party Sprinter or the ${b(yt)} for up to ${D(yt)}, and suite and client groups take an Executive Sprinter or an executive coach, up to the ${b(ua)}.`,`VIP and infield guests: the ${b(ge)} leads the VIP row, ${D(ge)} seats with Maybach massage recliners and a wet bar. The ${b(ye)}, our flagship for race weekend, seats ${D(ye)} in a fiber-optic lounge with a wet bar for the ride home after the checkered flag. The ${b(vr)} seats ${D(vr)} in custom Maybach seats, and the ${b(kr)} carries a couple or a small VIP party of up to ${D(kr)}.`,`Race-day crews: the ${b(Sr)} and the ${b(be)} are limo lounges on wheels for ${D(Sr)} and ${D(be)}, and the ${b(yt)} puts ${D(yt)} on limo seating with two wet bars when the whole crew comes. These are party rides for a group out to celebrate; we never send one as a corporate client vehicle.`,`Suites and client groups: the ${b(Ar)} seats ${D(Ar)} in reclining leather with room for bags, the ${b(Tr)} (${D(Tr)} seats) and the ${b($r)} (${D($r)} seats) carry a client list or a company outing in one vehicle, and the ${b(ua)} takes up to ${D(ua)} when the whole company goes to the race.`,"Count riders for each direction. A morning arrival and the ride home after the race are often different lists. Anyone leaving with another group comes off the return manifest before seats are assigned; “we will decide at the track” is not a count the chauffeur can plan around when the lots are emptying."),Q("What can you bring into Phoenix Raceway?","Each guest may bring 2 bags up to 18 by 18 by 14 inches and 1 soft-sided cooler up to 14 by 14 by 14 inches, with ice and sealed food or drinks. Alcohol, glass, hard or foam coolers, collapsible chairs and wagons are not allowed through the grandstand gates, and the track is cashless.","Hillside guests, general admission on Sunday only, sit on the hill with no seats: bring a chair or blanket, and a hard or soft cooler is allowed there without glass or alcohol. Anything bigger than the gate limits stays on the vehicle, which is one reason to book it by the hour: the extra cooler, the spare layers and the bags ride back with the group.","On the ride itself, guests 21 and over may bring their own drinks aboard: Arizona’s open-container law, A.R.S. § 4-251, exempts passengers in a vehicle for hire. We do not sell alcohol, the chauffeur never drinks, and if anyone on board is under 21 the vehicle is dry for everyone. Nothing opened on board goes through the gates.","Write the day plan in 5 lines: ready time, the entry you are heading for, the meeting point, one transportation lead and the ride home. The ready time is when guests are at the pickup point with tickets on their phones, not when they start getting ready. Tell the reservations team about mobility needs when you book, so the pickup and the unload suit the rider.",`During the final 48 hours, verify addresses, contact numbers and the track’s newest parking and entry notes, and send one summary to riders. If staff change the approach on the day, the chauffeur follows them and the transportation lead relays the update. Reach the reservations team at ${C} or ${E}.`),Q("How is Phoenix Raceway transportation priced per person?",`For ${Cr} race fans sharing the ${b(be)} for ${wt} billed hours, the published ${pa(be)}-per-hour rate comes to about ${Ti(be,wt,Cr)} per person before tax for the whole shared race day; the price changes with the vehicle, the hours, the day and the confirmed plan.`,"That example is arithmetic, not a flat race-day fare: the hourly rate times the billed hours, divided by the riders. If only ten people ride, divide by ten. A day that waits through the race and the lots needs more hours than a drop-off and a set pickup, so describe the real pattern and let the quote price it.",`The same arithmetic on the ${b(ye)} uses its own rate of ${pa(ye)} an hour and its ${D(ye)} seats; on the ${b(ge)}, ${pa(ge)} an hour for ${D(ge)}. The ready-made packages on this page print the engine’s own total for their hours and extras, including any hour the rate ladder gives free.`,"One person collects the shares and one person owns the manifest. Neither job belongs to the chauffeur, and neither should wait until the group is standing at the curb after the race.")],Ni=[{question:"When is NASCAR in Phoenix in 2027?",answer:"Friday, March 12 to Sunday, March 14, 2027, at Phoenix Raceway in Avondale: the ARCA race on Friday, IndyCar and the NASCAR O’Reilly Auto Parts Series on Saturday, and the NASCAR Cup Series on Sunday. The fall weekend is October 22 to 24, 2027."},{question:"Is parking free at Phoenix Raceway?",answer:"Yes. General parking is free for ticket holders: follow the signs from I-10 to Entries J, K and L. Premium, El Mirage and Preferred passes, sold by the track, park closer to the gates. With a chauffeured ride, nobody in the group drives or parks."},{question:"Where do Uber and Lyft drop off at Phoenix Raceway?",answer:"At Entry E, which the track lists for rideshare (Uber, Lyft and taxis), Premium and Ally Curve parking."},{question:"Can a limo or party bus drop off at the Phoenix Raceway gate?",answer:"No entry or lane for limos, party buses or charters is published; Entry E is listed for rideshares and taxis. Our chauffeur unloads where race-day traffic staff direct and follows any instruction the track publishes for 2027."},{question:"What time do gates open at Phoenix Raceway?",answer:"The 2027 times are announced closer to the date. On the track’s October 2026 schedule, Sunday’s lots open at 6:00 a.m. and the gates at 8:00 a.m., with the Cup race at 12:00 p.m."},{question:"How far is Phoenix Raceway from Scottsdale?",answer:"About 31 miles and 44 minutes from Old Town Scottsdale by I-10 West without race traffic (Google Directions, measured September 24, 2026). The track is about six miles south of I-10 at Exit 131, Avondale Boulevard."},{question:"How long should I book a Sprinter for a NASCAR race day?",answer:"About 10 hours for Cup Sunday from Scottsdale, and about 9 for Saturday’s two races: the drive each way, arriving before the gates, the race, and the wait while the lots clear. If the race runs long, your chauffeur waits and extra time is billed hourly."},{question:"What is the Phoenix Raceway bag policy?",answer:"Up to 2 bags per person, each no larger than 18 by 18 by 14 inches, plus 1 soft-sided cooler up to 14 by 14 by 14 inches. No alcohol, glass, or hard or foam coolers through the grandstand gates."},{question:"Is IndyCar racing at Phoenix in 2027?",answer:"Yes. The NTT INDYCAR SERIES races at Phoenix Raceway on Saturday, March 13, 2027, on the same card as the NASCAR O’Reilly Auto Parts Series. The start time is announced closer to the date."},{question:"How long is Phoenix Raceway?",answer:"Phoenix Raceway is a 1-mile oval with an asphalt surface and banking from 0 to 11 degrees, by the track’s own figures."}],Wi={path:Ai,title:"Phoenix Raceway 2027: NASCAR and IndyCar parking and rides",metaTitle:"Phoenix Raceway 2027: Parking & Rides",description:"NASCAR and IndyCar race at Phoenix Raceway March 12–14, 2027. The official dates, free and paid parking, the rideshare entry, the drive from Scottsdale, and a chauffeured ride so nobody in the group drives or parks.",metaDescription:"March 12–14 dates, free parking, the rideshare entry, or a chauffeured ride",lastUpdated:br,lastUpdatedLabel:A(br),eyebrow:"Official dates: March 12–14, 2027",intro:"A race-day ride from Scottsdale Sprinters starts with the day your group is having: Cup Sunday with the crew, IndyCar Saturday, a client day in the suites or a VIP day in the infield. This guide uses only what Phoenix Raceway publishes, labels the October 2026 race-day schedule as October’s, and says plainly what is announced closer to the date. Scottsdale Sprinters is independent and not affiliated with Phoenix Raceway, NASCAR or INDYCAR.",sections:Mi,faqs:Ni,links:[{href:"/services/corporate-transportation-scottsdale",label:"Corporate transportation for client days"},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/guides/party-bus-alcohol-laws-arizona",label:"Party bus alcohol laws in Arizona"},{href:`/fleet/${ye}`,label:b(ye)},{href:`/fleet/${ge}`,label:b(ge)},{href:`/fleet/${be}`,label:b(be)},{href:"/pricing",label:"Published hourly pricing"}],sources:Ri},Ad=[Wi],Fr="2026-09-24",Oi="https://www.inningsfestival.com/",Ot="https://help.inningsfestival.com/article",Gi=`${Ot}/224-what-are-the-dates-hours-of-innings-festival`,Li=`${Ot}/229-community-information-page`,_i=`${Ot}/250-how-do-i-get-home-from-the-festival`,Bi=`${Ot}/196-what-is-the-bag-policy`,Ui="https://www.downtowntempe.com/get-around/parking",Hi="https://www.valleymetro.org/how-to-ride/destinations/destinations-tempe",fa={crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"],vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],big:["executive-sprinter-scottsdale","executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"]},ma={oldTown:15,kierland:28},qi=[...fa.crews,...fa.vip,...fa.big].filter(Oe),io=qi.map(e=>({slug:e,name:o[e],capacity:i[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours})),Y="ultra-luxury-party-sprinter-scottsdale",Te="maybach-jet-sprinter-scottsdale",bt="maybach-shuttle-sprinter-8",ga="premium-suv-scottsdale",Qe="limo-sprinter-13-scottsdale",zi="limo-sprinter-16-scottsdale",xa="party-bus-28-scottsdale",Dr="executive-sprinter-scottsdale",Vi="executive-mini-bus-26-scottsdale",Ji="executive-luxury-bus-29-scottsdale",Ir="motorcoach-56",u=e=>o[e],X=e=>i[e];function xr(e){return l(s[e].hourlyRateCents)}function Rr(e,t,a){return l(Math.round(s[e].hourlyRateCents*t/a))}function z(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Yi="At 10:30 p.m. the whole crowd leaves at once, the festival asks everyone to head to the nearest exit, and rideshare prices and waits can climb when that many people request a car together.",Zi=[{label:"Innings Festival official site: dates and venue",href:Oi},{label:"Innings Festival help center: dates and hours",href:Gi},{label:"Innings Festival help center: community information and road closures",href:Li},{label:"Innings Festival help center: getting home from the festival",href:_i},{label:"Innings Festival help center: bag policy",href:Bi},{label:"Downtown Tempe: parking in Downtown Tempe",href:Ui},{label:"Valley Metro: Tempe destinations (Tempe Beach Park/Town Lake)",href:Hi}],ji=[z("Where do you park for Innings Festival 2027?","Innings Festival has published no festival parking for 2027, so drivers use Downtown Tempe’s paid garages, lots and meters, more than 20,000 public spaces, some posting special event rates during events; with a chauffeured ride nobody in the group drives, parks or walks back to a garage after the 10:30 p.m. close.","The festival’s own help center covers entrances, re-entry, transit and the ride home, but for 2027 it lists no parking lot of its own. Its accessibility page says accessible parking locations, drop-off areas and entry procedures will be available closer to the festival. Until then, parking means the city’s downtown supply, not a festival lot.","Downtown Tempe, where the City of Tempe’s parking link leads, counts more than 20,000 paid public parking spaces across garages, lots and on-street zones, and more than a dozen paid garages and surface lots. During certain events some garages and lots post special event parking; where none is posted, standard rates apply. On-street meters are free on Sundays. Tempe TRiP shows availability in real time.","The catch is not the number of spaces. It is the closures around the park (the next answers), a walk from the garage to the entrance at Mill Avenue and Rio Salado Parkway, and the same walk back after close with everyone else. A chauffeured ride skips all three: the chauffeur drops the group near the entrance, as far as the closures and traffic staff allow, and is booked for the ride home."),z("Where is the Innings Festival rideshare and drop-off area?","The 2027 rideshare zone is not announced yet: the official help center says the 2027 information is not yet available, so no pickup spot is confirmed for February 26 to 28; a chauffeured ride unloads at a legal curb outside the closed streets, where police and event staff direct, and meets the group at a set time.","The festival publishes its rideshare instructions in the “How do I get home from the festival?” article. For 2027 that section reads, in effect, check back shortly. When it is posted, that zone is for rideshare cars. It is not a commercial-vehicle privilege, and no limo, charter or party-bus drop-off zone is published.","So a booked Sprinter, party bus or coach follows the current closures and the directions of Tempe police and event staff. The main entrance is at the northwest corner of Mill Avenue and Rio Salado Parkway; the secondary entrance is on West Rio Salado Parkway at West Lakeside Drive. The chauffeur unloads as close to those as the open streets allow, and the group walks the last stretch.","For the ride home, agree on one meeting point before anyone goes in, away from the exit crush. The festival names the Main Guest Services Tent as the meeting point for anyone separated inside. Outside, the transportation lead confirms where the vehicle is waiting before the group walks toward traffic."),z("When is Innings Festival 2027, and what time do the gates open?","Innings Festival 2027 runs Friday, February 26 through Sunday, February 28, 2027, at Tempe Beach Park & Arts Park; the gates open at 12 p.m. and the festival closes at 10:30 p.m. each of the 3 days, and guests may leave and re-enter as often as they like until 7 p.m.","The dates and daily hours come from the festival’s own help center, updated in September 2026: Friday, February 26, Saturday, February 27 and Sunday, February 28, 2027, opening at noon and closing at 10:30 p.m. each day. The countdown on this page counts to the first gate time, 12 p.m. on Friday, February 26, Arizona time.","The 2027 lineup and set times are not announced yet. The festival’s lineup and schedule pages still show last year’s, and its schedule article says 2027 information will come closer to the festival date. This guide names no artist. Plan the pickup around the gates and the close, then adjust once the schedule is out.","Re-entry is allowed until 7 p.m., local time. Each time, the wristband is scanned and the guest goes back through security. After 7 p.m., leaving means leaving for the night, so a group that wants dinner outside and the late sets inside should plan to be back through the gate before then."),z("Which roads close for Innings Festival, and where is it?","Innings Festival is at Tempe Beach Park & Arts Park, 80 West Rio Salado Parkway, Tempe, AZ 85281; for 2027 the festival lists Mill Avenue southbound closed between Washington Street and 2nd Street on all 3 festival days, starting at 10:30 a.m., and East Rio Salado Parkway closed between Ash Avenue and Mill Avenue.","The festival’s 2027 community page lists these closures. North Mill Avenue southbound, between Washington Street and West 2nd Street, closes on Friday, February 26, Saturday, February 27 and Sunday, February 28, starting at 10:30 a.m. and reopening at 11:59 p.m. East Rio Salado Parkway, between Ash Avenue and South Mill Avenue, closes on the same 3 days, starting at 8 a.m. and reopening at 11:59 p.m.","West Rio Salado Parkway eastbound, between South Hardy Drive and East Rio Salado Parkway, closes from 8 a.m. on Friday, February 26 until 5 a.m. on Monday, March 1. The westbound side of the same stretch closes earlier, from Wednesday, February 24; its reopening time is announced closer to the date. The walking and bike path between Tempe Center for the Arts and Hayden Ferry Lakeside closes from Monday, February 22 to Monday, March 1.","The City of Tempe posts its own event traffic notices closer to each event; its 2027 notice for the festival is not out yet. Your chauffeur plans the approach around the published closures and follows police and event staff on the day. Anyone driving themselves should expect the streets nearest the park to be closed and should not plan to reach the entrance by car."),z("Can you take the light rail or streetcar to Innings Festival?","Yes: Valley Metro’s A line stops at the Mill Ave/3rd St station for Tempe Beach Park, the Tempe streetcar stops at Tempe Beach Park/Rio Salado Parkway, and bus Route 48 stops at Ash Avenue/Rio Salado Parkway; the festival also points to 11 free park-and-rides, with no overnight parking.","The festival’s getting-home article lists Valley Metro rail, the local bus and the streetcar, and 11 free park-and-rides that reach rail stations in Phoenix, Tempe and Mesa. Overnight parking is not allowed at the park-and-rides. Valley Metro fares apply; the festival’s article and valleymetro.org list them.","Transit is a good answer for two or three people who are staying near a station. It is a harder answer for a group of 10 coming from a Scottsdale resort, or for a crew that wants to arrive together and leave together after a 10:30 p.m. close. That is where a chauffeured ride earns its keep."),z("Is a chauffeured ride worth it when Scottsdale is so close?",`The drive is short, about ${ma.oldTown} minutes from Old Town Scottsdale without event traffic, so the ride is not about distance: it is no parking, no rideshare wait at the 10:30 p.m. close, 1 vehicle that keeps the group together, and a set pickup, with nobody in the group driving.`,`From Old Town Scottsdale to Tempe Beach Park is about ${ma.oldTown} minutes by Google’s typical time, and about ${ma.kierland} from Kierland. Nobody needs a chauffeur for the miles. The value is what the evening does to those minutes: closed blocks around the park, a garage to find and pay for, and a walk back to it.`,Yi,"A booked vehicle turns that into a plan. One cabin carries everyone, so nobody is split across 3 rideshares or left to find their own way. The pickup time and place are set before the gates open. Nobody in the group has to drive, so nobody has to stop at one drink or leave early to get the car.","The honest limit: we cannot drive past closed streets or unload in a travel lane, and we cannot make the exit crowd move faster. The chauffeur is waiting where the open streets and traffic staff allow, and the group walks to it. For two people staying next to a station, the light rail may be the simpler choice."),z("What is the Innings Festival bag policy?","The 2027 bag policy allows a clutch or fanny pack up to 6 by 9 inches with no more than one pocket, a clear bag smaller than 12 by 6 by 12 inches, or an emptied hydration pack; every bag is searched, entry is an airport-style screening, and outside food, drinks, coolers and chairs are prohibited.","Hydration packs need not be clear, but they must be emptied of all liquid and have no more than two main compartments and one smaller one. The festival’s advice is to leave the bag at home for the quickest entry. All fans are subject to an airport-style search, which may include a pat-down and magnetometer screening. The policy is marked subject to change.","Prohibited items include outside food or beverage of any kind, alcohol included, coolers, glass, aerosols, chairs of any kind, umbrellas, tents and shade structures, selfie sticks and drones. Empty reusable water bottles, blankets, portable battery packs and non-aerosol sunscreen up to 3.4 ounces are allowed. The park is smoke free, and the festival is 100% cashless.","Anything the gate will not take can stay in the vehicle for the ride home when the vehicle is booked by the hour. Tell the reservations team what the group will carry, so the vehicle fits the bags as well as the people."),z("Which vehicle fits an Innings Festival group?",`Festival crews ride a Limo Party Sprinter or the ${X(xa)}-seat party bus; VIP guests lead with the ${u(Te)}, then the ${u(Y)}, our pick for the festival, the ${u(bt)} and the Suburban; big groups and company outings take the ${u(Dr)}, the mini bus, the mini coach or the ${X(Ir)}-seat motorcoach.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. Festival crews: the ${u(Qe)}, the ${u(zi)} and the ${u(xa)}. VIP guests: the ${u(Te)}, the ${u(Y)}, which seats ${X(Y)} at ${xr(Y)}/hr, the ${u(bt)} and the ${u(ga)}. Big groups and company outings: the ${u(Dr)}, the ${u(Vi)}, the ${u(Ji)} and the ${u(Ir)}.`,`A VIP party larger than the ${u(Te)} rides in two vehicles, one booking each for the same day and times: the ${u(Te)} with the ${u(bt)} seats ${X(Te)+X(bt)}, and with the ${u(ga)} it seats ${X(Te)+X(ga)}.`,"Count riders for each direction. The group that arrives at the noon gates is not always the group that leaves at 10:30 p.m. Anyone heading elsewhere after the festival comes off the return list before seats are assigned.",`Each booking covers one festival day. For all 3 days, book each day as its own ride; the same vehicle can be requested for each. For a per-person view: 13 riders sharing the ${u(Qe)} for 5 billed hours at ${xr(Qe)}/hr is about ${Rr(Qe,5,13)} each before tax; ${X(Y)} riders in the ${u(Y)} for 6 hours is about ${Rr(Y,6,X(Y))} each. That is arithmetic, not a flat festival fare.`),z("How should the pickup after Innings Festival work?","Use 2 checkpoints after Innings Festival: the group gathers at the meeting point it chose before going in, then the transportation lead confirms where the vehicle is waiting before anyone walks toward traffic, because at the 10:30 p.m. close the streets nearest the park are still closed and the 2027 rideshare zone is not yet announced.","Mill Avenue southbound and East Rio Salado Parkway stay closed until 11:59 p.m. on each festival day, so the vehicle waits on an open street, where police and event staff allow. It cannot stop wherever a map pin lands, and guests should not walk into a roadway to reach it.","If the group splits inside, the festival’s meeting point for separated guests is the Main Guest Services Tent. Anyone leaving early or going on elsewhere tells the transportation lead, so the return list stays right. If the night runs long, your chauffeur waits; extra time is billed hourly at the vehicle’s rate, and you can call or text us to extend.","For a multi-vehicle group, label each vehicle, its lead and its drop-off. A crew heading to Old Town and a VIP group heading to a resort should not rely on spotting a driver in a crowd."),z("How far ahead should Innings Festival transportation be booked?",`Availability varies by day and by vehicle, so no fixed lead time applies: request a quote with the rider count, the pickup area and which of the 3 festival days you need, and the reservations team confirms what is open across the ${io.length} vehicles listed, updating the plan as the festival announces its 2027 details.`,"The first request needs the day or days, the hotel or home, a likely passenger count, the arrival you want against the noon gates, and the return. A group does not need every name to begin. It does need to say which group is riding: a festival crew, VIP guests or a big group or company outing.",`During the final 48 hours, confirm addresses, phone numbers and the festival’s newest instructions, including the 2027 rideshare zone and the city’s traffic notice once they are posted. Reach the reservations team at ${C} or ${E}. A ride booking never includes a festival ticket or wristband.`)],Ki=[{question:"When is Innings Festival 2027?",answer:"Friday, February 26 through Sunday, February 28, 2027, at Tempe Beach Park & Arts Park in Tempe. The festival opens at 12 p.m. and closes at 10:30 p.m. each day."},{question:"What time does Innings Festival start?",answer:"The gates open at 12 p.m. (noon) on each festival day, and the festival closes at 10:30 p.m. The 2027 set times are announced closer to the date."},{question:"Where is Innings Festival?",answer:"At Tempe Beach Park & Arts Park, 80 West Rio Salado Parkway, Tempe, AZ 85281. The main entrance is at the northwest corner of Mill Avenue and Rio Salado Parkway; the secondary entrance is on West Rio Salado Parkway at West Lakeside Drive."},{question:"Where do you park for Innings Festival?",answer:"The festival has published no parking lot of its own for 2027. Drivers use Downtown Tempe’s paid garages, lots and meters; some garages post special event parking during events. With a chauffeured ride nobody drives or parks."},{question:"Where is the Innings Festival rideshare pickup?",answer:"The 2027 rideshare zone is not announced yet; the festival’s getting-home article says the information is coming. A chauffeured ride unloads and picks up where police and event staff allow, at a time set in advance."},{question:"Who is playing Innings Festival 2027?",answer:"The 2027 lineup is not announced yet. The festival’s lineup and schedule pages still show last year’s; check the official site for the 2027 announcement."},{question:"Can I leave Innings Festival and come back?",answer:"Yes, as often as you like until 7 p.m. local time. Your wristband is scanned and you go through security each time you re-enter."},{question:"What bags are allowed at Innings Festival?",answer:"A clutch or fanny pack up to 6 by 9 inches with no more than one pocket, a clear bag smaller than 12 by 6 by 12 inches, or a hydration pack emptied of liquid. Every bag is searched."},{question:"Can I take the light rail to Innings Festival?",answer:"Yes. The Valley Metro A line stops at the Mill Ave/3rd St station for Tempe Beach Park, and the Tempe streetcar stops at Tempe Beach Park/Rio Salado Parkway."},{question:"Can we book a ride for all three days?",answer:"Yes, one booking per day. Each festival day is its own ride, so a Friday-to-Sunday group books three rides, one for each day, and can ask for the same vehicle each time."}],Qi={path:"/guides/innings-festival-transportation",title:"Innings Festival 2027: parking, rideshare and getting there",metaTitle:"Innings Festival 2027 Parking & Rides",description:"Innings Festival 2027 runs February 26–28 at Tempe Beach Park & Arts Park. The official dates and gate times, the 2027 road closures, parking, rideshare, light rail and the bag policy, and a chauffeured ride from Scottsdale so nobody drives, parks or waits at close.",metaDescription:"Feb 26–28 dates, noon gates, road closures and light rail, or a chauffeured ride",lastUpdated:Fr,lastUpdatedLabel:A(Fr),eyebrow:"Official dates: February 26–28, 2027",intro:`An Innings Festival ride from Scottsdale Sprinters starts with the festival’s own 2027 facts, a rider count and one transportation lead. Festival crews ride a Limo Party Sprinter or the party bus; VIP guests lead with the ${u(Te)} and the ${u(Y)}; big groups and company outings take the executive Sprinter, the mini bus, the mini coach or the motorcoach. This guide uses only published facts, leaves the unannounced ones for closer to the date, and turns each festival day into a written pickup, drop-off and ride home.`,sections:ji,faqs:Ki,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:u(Y)},{href:"/fleet/limo-sprinter-13-scottsdale",label:u(Qe)},{href:"/fleet/party-bus-28-scottsdale",label:u(xa)},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/service-areas/tempe",label:"Tempe service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:Zi,fleetRows:io},Td=[Qi],Mr="2026-09-25",Xi="/guides/scottsdale-limo-service",ya={vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],nights:["pink-hummer-limo","limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale"],weddings:["chrysler-limo-10","executive-white-sprinter-scottsdale","executive-sprinter-scottsdale"]},ve="maybach-jet-sprinter-scottsdale",G="ultra-luxury-party-sprinter-scottsdale",At="maybach-shuttle-sprinter-8",Le="premium-suv-scottsdale",I="pink-hummer-limo",Re="limo-sprinter-13-scottsdale",Me="limo-sprinter-16-scottsdale",P="chrysler-limo-10",Tt="executive-white-sprinter-scottsdale",eh="executive-sprinter-scottsdale",th=[...ya.vip,...ya.nights,...ya.weddings].filter(Oe),Gt=th.map(e=>({slug:e,name:o[e],capacity:i[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours})),r=e=>o[e],S=e=>i[e],Nr=e=>l(s[e].hourlyRateCents);function wa(e,t){const{hourlyRateCents:a,minimumHours:n}=s[e];return l(a*So(t,n))}const ho=Gt.map(e=>e.hourlyRateCents),lo=l(Math.min(...ho)),co=l(Math.max(...ho)),Wr=[...new Set(Gt.map(e=>e.minimumHours))],uo=Wr.length===1?`a ${Wr[0]}-hour minimum on every limo here`:"the minimum hours shown for each limo",ah=Math.max(...Gt.map(e=>e.capacity)),rh=`${vo.toFixed(1)}-star Google rating across ${ko.toLocaleString("en-US")} reviews`;function ee(e,t,...a){return{question:e,answer:t,paragraphs:a}}const oh="https://www.scottsdaleaz.gov/codes-and-ordinances/transportation-safety-zone",nh=[{label:"City of Scottsdale, Transportation Safety Zone (Old Town)",href:oh}],sh=[ee("How much does a limo cost in Scottsdale?",`A Scottsdale limo from Scottsdale Sprinters is priced by the hour, from ${lo} to ${co} an hour across the limos on this page, with ${uo}: the vehicle’s published hourly rate times your billable hours, plus ${Ga}% Arizona sales tax at checkout, with no per-mile charge, no service fee and no booking fee.`,`Four hours in the ${r(P)} comes to ${wa(P,4)} before tax. Five hours in the ${r(I)} comes to ${wa(I,5)}. Every card on this page prints its vehicle’s own rate from the same grid, so the number you see is the number checkout uses.`,`Longer bookings earn free hours that come off automatically: book 7 to 11 hours and one hour is free, 12 to 14 hours and two are free, 15 hours or more and three are free. A seven-hour night in the ${r(G)} bills six hours, ${wa(G,7)} before tax.`,"A one-way ride is priced as a trip instead of by the hour, with no hourly minimum. Gratuity is optional and never added automatically."),ee("Which Scottsdale limo fits your group?",`Pick by who is riding: VIP and ultra-luxury parties lead with the ${r(ve)}, then the ${r(G)}, the ${r(At)} and the ${r(Le)}; nights out and bachelorettes ride the ${r(I)} or a Limo Party Sprinter; weddings, proms and executive groups take the ${r(P)} or an Executive Sprinter.`,`Seats, from the fleet grid: the ${r(I)} seats ${S(I)}, the ${r(Me)} ${S(Me)}, the ${r(G)} ${S(G)}, the ${r(Re)} ${S(Re)}, the ${r(Tt)} and the ${r(eh)} ${S(Tt)} each, the ${r(ve)} ${S(ve)}, the ${r(P)} and the ${r(At)} ${S(P)} each, and the ${r(Le)} ${S(Le)}.`,`The table lists each limo with its seats, hourly rate and minimum. The largest limo here seats ${ah}. For a bigger group we plan two or more vehicles and quote them together; a VIP party larger than the ${r(ve)} can ride it with the ${r(At)} or the ${r(Le)}, one booking each.`,"If your group is on the edge of a vehicle’s seats, tell us and we confirm the fit in writing before payment."),ee("What is the Pink Hummer Limo?",`The ${r(I)} is our one-of-one pink stretch Hummer, the bachelorette mobile: ${S(I)} guests on handmade custom leather seats behind privacy-tinted windows, with a lit wet bar, a champagne bar, star lighting and a custom sound system, at ${Nr(I)} an hour.`,"It is our most popular ride for women: bachelorettes first, then girls’ birthdays, prom and any night out that celebrates the women in it. Ambient lighting runs outside as well as in, and a partition separates the cabin from the chauffeur.","There is one Pink Hummer, so it books by the date. If a pink party bus is what you searched for, the pink party bus guide explains why the pink ride here is a stretch Hummer limousine rather than a bus."),ee("Do you have a classic stretch limo?",`Yes: the ${r(P)} is our classic stretch limousine, black outside with ambient lighting and privacy tint, up to ${S(P)} guests on classic leather seats, with a wet bar, a custom sound system and seventeen colour settings for the cabin lights, at ${Nr(P)} an hour.`,"It is the one for prom, anniversaries, date nights, concerts and the wedding exit: the long silhouette everybody turns to look at. A stretch limo is a sedan lengthened for a lounge cabin; the Pink Hummer is the same idea built on a Hummer, which is why it seats a bigger group."),ee("What is a Limo Party Sprinter?",`A Limo Party Sprinter puts limo-style seating, a wet bar and party lighting in a Mercedes Sprinter: the ${r(Re)} seats ${S(Re)} under fiber-optic roof lights, the ${r(Me)} is our largest Sprinter with a star-roof ceiling for ${S(Me)}, and the ${r(G)} is the top of the line.`,`The ${r(G)} adds fiber-optic lighting with eighteen modes, laser lights, a fog machine, automatic doors and an intercom to your chauffeur, for up to ${S(G)}. It is also ultra-luxury, so it rides with the VIP group on this page.`,"The Limo Party Sprinters ride with the nights-out group, never with a corporate or family booking. For executive groups and weddings that want the room without the party lighting, the Executive Sprinters carry reclining leather seats and space for bags."),ee("Where do Scottsdale limos pick up?","Anywhere in Scottsdale and the greater Phoenix area: your hotel, home, restaurant or venue, with every stop on an hourly booking included; in Old Town’s entertainment district, from 5 p.m. to 4 a.m. every night, hired vehicles load and unload only in the marked Passenger Convenience Areas.",`Old Town Scottsdale is where nights out start: dinner, the bars and the clubs, in the ${r(I)} or a Limo Party Sprinter. The City’s Transportation Safety Zone covers the entertainment district every night from 5 p.m. to 4 a.m.: through lanes stay clear, and hired vehicles stop only to load or unload at the marked Passenger Convenience Areas, so your chauffeur meets the group where the City allows a limo to load.`,`North Scottsdale books weddings at the resorts and desert venues along the 101, and dinners around Kierland and Scottsdale Quarter; the ${r(P)} and the ${r(Tt)} are the wedding picks. Central Scottsdale, Gainey Ranch and McCormick Ranch book anniversary dinners and small-group evenings in the ${r(Le)} or the ${r(ve)}. Paradise Valley estate events stage the vehicle at the property.`,"Stops on an hourly booking are complimentary, because you have already bought the time. On a one-way ride or a round trip, an added stop carries a fee shown on the quote."),ee("Do you offer limo service in Phoenix?","Yes: we run chauffeured limos throughout Phoenix and the Valley, from the Biltmore to downtown Phoenix, Tempe, Mesa, Chandler, Gilbert and Glendale, with the same vehicles, rates and chauffeurs as in Scottsdale.","The drive is part of the hours you book, and your chauffeur plans the route around the Valley’s freeway traffic, so a Phoenix dinner and a Scottsdale nightcap can share one booking. On summer evenings the cabin is cooled before the group boards.","For a Phoenix wedding, a Tempe or ASU celebration, or a concert downtown, pick the group above and the limos that fit it appear with their rates."),ee("Can you pick us up at Phoenix Sky Harbor in a limo?",`Yes. ${eo} We also pick up at Scottsdale Airport and Phoenix-Mesa Gateway, and your chauffeur tracks your flight.`,"Airport rides are priced as a one-way trip with no hourly minimum. The airport transportation page has the full detail, from greeters to luggage."),ee("Can you drink in a limo in Arizona?","Passengers 21 and over may bring their own alcohol, and we do not sell it; if anyone under 21 rides, no alcohol comes on that trip, which makes every prom ride alcohol-free, and there is no smoking, vaping or food inside any vehicle.","Arizona’s vehicle-for-hire open-container policy, A.R.S. § 4-251, is what allows adults to drink on board; the alcohol-laws guide covers the law itself. Anyone under 21 stays on soft drinks, and the chauffeur never drinks.","Prom rides follow a written zero-alcohol passenger policy, and a guardian contact can get pickup and drop-off updates; the prom night page has the full plan, from the photo stop to the ride home.")],ih=[{question:"How much does it cost to rent a limo in Scottsdale?",answer:`A limo is priced by the hour: the vehicle’s published hourly rate times your billable hours, from ${lo} to ${co} an hour across the limos on this page. There is no per-mile charge, no service fee and no booking fee. Arizona sales tax of ${Ga}% is added at checkout, and gratuity is optional. Pick the limo above and the price is on the page.`},{question:"How much is a limo for 2 hours, 4 hours or a whole night?",answer:`An hourly booking has ${uo}, so a two-hour ride books the minimum; a one-way ride is priced as a trip instead, with no hourly minimum. Bookings of 7 hours or more earn free hours that come off automatically, so a seven-hour night bills six.`},{question:"How many people fit in a limo?",answer:`It depends on the limo: the ${r(I)} seats ${S(I)}, the ${r(Me)} seats ${S(Me)}, the ${r(G)} seats ${S(G)}, the ${r(Re)} seats ${S(Re)} and the ${r(P)} seats ${S(P)}. If your group is on the edge, tell us and we confirm the fit in writing.`},{question:"Can you drink in a limo?",answer:"If everyone drinking is 21 or over, yes: bring your own, because we do not sell alcohol. Nobody under 21 drinks, and if anyone under 21 rides, no alcohol comes on that trip. There is no smoking, vaping or food inside the vehicle."},{question:"How much do you tip a limo driver?",answer:"Gratuity is optional, is never added automatically, and goes 100% to your chauffeur. Add it at checkout or hand it over in person."},{question:"Can we book a limo for prom?",answer:`Yes. Prom rides follow a written zero-alcohol passenger policy, and a guardian contact can get pickup and drop-off updates. The ${r(P)} is the classic prom stretch; the ${r(Tt)} carries a bigger group.`},{question:"What is the difference between a limo, a stretch limo and a limo Sprinter?",answer:`The ${r(P)} is the classic stretch: the long black silhouette, up to ${S(P)} guests. The ${r(I)} is a stretch Hummer that seats a bigger group. Our Limo Party Sprinters put limo-style seating, a wet bar and party lighting in a Mercedes Sprinter.`},{question:"Is Scottsdale Sprinters a reputable limo company?",answer:`Every chauffeur is background and MVR checked, drug screened and trained, and the company is licensed and insured with commercial coverage on every vehicle. Guests give us a ${rh}.`},{question:"Do you pick up at Phoenix Sky Harbor?",answer:`Yes: Phoenix Sky Harbor (PHX), Scottsdale Airport (SCF) and Phoenix-Mesa Gateway (AZA). ${eo} Your chauffeur tracks your flight.`},{question:"How far in advance should I book a limo?",answer:Oa},{question:"Do you serve Phoenix?",answer:"Yes. We run chauffeured limos throughout Scottsdale, Paradise Valley and the greater Phoenix area."},{question:"Can we decorate the limo or add a Just Married sign?",answer:"Yes, as priced add-ons you choose at checkout: Just Married signage, balloons and décor, a red carpet arrival and more. Anything vehicle-specific is confirmed in writing before payment."}],hh={path:Xi,title:"Limo service in Scottsdale and Phoenix",metaTitle:"Scottsdale Limo Service & Limo Rental",description:`Scottsdale limo service with a professional chauffeur on every booking: the ${r(I)}, the classic stretch ${r(P)}, the Limo Party Sprinters and the ${r(ve)}, each with its published hourly rate. Pick the group, see the price and reserve online, in Scottsdale and across Phoenix.`,metaDescription:"The Pink Hummer, a classic stretch, Limo Sprinters and the Maybach Jet, chauffeured, with the price on the page",lastUpdated:Mr,lastUpdatedLabel:A(Mr),intro:`Scottsdale limo service from Scottsdale Sprinters comes with a professional chauffeur on every booking, in Scottsdale and across Phoenix. Start with who is riding. VIP and ultra-luxury parties lead with the ${r(ve)}, then the ${r(G)}, the ${r(At)} and the ${r(Le)}. Nights out and bachelorettes ride the one-of-one ${r(I)} or a Limo Party Sprinter. Weddings, proms and executive groups take the classic stretch, the ${r(P)}, or an Executive Sprinter. Every limo here shows its published hourly rate, and you can reach the reservations team at ${C} or ${E}.`,sections:sh,faqs:ih,links:[{href:"/fleet/pink-hummer-limo",label:r(I)},{href:"/fleet/limo-sprinter-13-scottsdale",label:r(Re)},{href:"/fleet/limo-sprinter-16-scottsdale",label:r(Me)},{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:r(G)},{href:"/fleet/maybach-jet-sprinter-scottsdale",label:r(ve)},{href:"/guides/pink-party-bus-scottsdale",label:"Pink party bus or pink limo?"},{href:"/guides/party-bus-vs-limo-vs-sprinter",label:"Party bus vs limo vs Sprinter"},{href:"/guides/party-bus-alcohol-laws-arizona",label:"Arizona alcohol rules on board"},{href:"/services/wedding-transportation-scottsdale",label:"Wedding limo and transportation"},{href:"/experiences/prom-night",label:"Prom night limo"},{href:"/services/phoenix-airport-sprinter-van",label:"Phoenix airport limo pickups"},{href:"/service-areas/phoenix",label:"Phoenix service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:nh,fleetRows:Gt},$d=[hh],Or="2026-09-24",dh="https://www.m3ffest.com/",lh="https://www.m3ffest.com/faqs",ch="https://www.m3ffest.com/lineup-by-day",uh="https://www.m3ffest.com/ticket-types-1-1",ph="https://www.valleymetro.org/maps-schedules/b",fh="https://www.phoenix.gov/administration/departments/parks/activities-facilities/city-parks/steele-indian-school-park.html",ba={crews:["limo-sprinter-13-scottsdale","limo-sprinter-16-scottsdale","party-bus-28-scottsdale"],vip:["maybach-jet-sprinter-scottsdale","ultra-luxury-party-sprinter-scottsdale","maybach-shuttle-sprinter-8","premium-suv-scottsdale"],big:["executive-sprinter-scottsdale","executive-mini-bus-26-scottsdale","executive-luxury-bus-29-scottsdale","motorcoach-56"]},va={oldTown:22,kierland:27},mh=[...ba.crews,...ba.vip,...ba.big].filter(Oe),po=mh.map(e=>({slug:e,name:o[e],capacity:i[e],hourlyRateCents:s[e].hourlyRateCents,minimumHours:s[e].minimumHours})),Z="ultra-luxury-party-sprinter-scottsdale",$e="maybach-jet-sprinter-scottsdale",vt="maybach-shuttle-sprinter-8",ka="premium-suv-scottsdale",kt="limo-sprinter-13-scottsdale",fo="limo-sprinter-16-scottsdale",Ra="party-bus-28-scottsdale",Gr="executive-sprinter-scottsdale",gh="executive-mini-bus-26-scottsdale",yh="executive-luxury-bus-29-scottsdale",Lr="motorcoach-56",p=e=>o[e],te=e=>i[e];function _r(e){return l(s[e].hourlyRateCents)}function Br(e,t,a){return l(Math.round(s[e].hourlyRateCents*t/a))}function U(e,t,...a){return{question:e,answer:t,paragraphs:a}}const wh="When the last set ends, the crowd leaves at once, and rideshare prices and waits can climb when that many people request a car together.",bh=[{label:"M3F official site: M3F 2027 at Steele Indian School Park",href:dh},{label:"M3F official FAQs: dates, parking, bag policy, re-entry and box office",href:lh},{label:"M3F official lineup by day: Friday and Saturday, March 5–6",href:ch},{label:"M3F official passes: general admission, VIP and Club Pass",href:uh},{label:"Valley Metro: B line stops and schedule",href:ph},{label:"City of Phoenix: Steele Indian School Park",href:fh}],vh=[U("Where do you park for M3F 2027?","M3F has no official festival parking for 2027: its FAQ tells guests to use Valley Metro, rideshare, or to park at 4041 N Central Ave, the one address it names; with a chauffeured ride nobody in the group drives, parks or walks back to a car after the last set.","The festival’s own FAQ answers the parking question in three lines: there is no official festival parking; use public transport (Valley Metro) or rideshare services; or park at 4041 N Central Ave. It publishes no lot map, no rate, no operator and no capacity for that address, so this guide prints none either.","Steele Indian School Park is a busy city park in central Phoenix, and on a festival day the streets around it fill with people arriving from every direction. The festival’s own advice, to come by light rail or rideshare, says as much. Anyone who drives should plan the parking before leaving home, not on arrival.","A chauffeured ride takes parking off the list. The chauffeur drops the group near the entrance, where police and event staff allow, and is booked for the ride home. Nobody circles for a space, pays for one, or walks back to it at the end of the night, and nobody has to stay sober to drive."),U("Where is the M3F rideshare and drop-off area?","M3F has not posted a 2027 rideshare zone: its FAQ tells guests to use rideshare services but names no pickup spot, and no limo or charter drop-off is published for March 5 and 6; a chauffeured ride unloads where police and event staff direct and meets the group at a time set in advance.","When the festival posts a rideshare zone, that zone is for rideshare cars. It is not a commercial-vehicle privilege, and a booked Sprinter, party bus or coach follows its own instruction on the day: the directions of Phoenix police and event staff, and the closures in place around the park.","The festival does name one entrance: its bike valet is near the entrance at N Central Ave. The chauffeur unloads as close to the entrance as the open streets and traffic staff allow, and the group walks the last stretch.","For the ride home, agree on one meeting point before anyone goes in, away from the exit crush. There is no re-entry, so the group leaves once. Outside, the transportation lead confirms where the vehicle is waiting before the group walks toward traffic."),U("When is M3F 2027, and what time does it start?","M3F 2027 is Friday, March 5 and Saturday, March 6, 2027, at Steele Indian School Park in Phoenix; the gate and set times are not announced yet, and the festival box office opens at 12 p.m. on Friday and 11 a.m. on Saturday, closing at 11 p.m. both days.","Every current official source agrees on the dates: the festival’s 2027 lineup poster (Friday 03/05/27 and Saturday 03/06/27), its lineup-by-day, music and passes pages, and the ticket seller the site links. One FAQ line prints the year as 2026, but its question says 2027 and the weekdays are 2027’s: March 5, 2027 is a Friday. Some search results still show an old page title with March 6 and 7; the festival’s current pages all say March 5 and 6.","The gate times and set times for 2027 are not published. The only times on the festival’s site are the box office’s: open festival weekend at Steele Indian School Park, from 12 p.m. on Friday and from 11 a.m. on Saturday, closing at 11 p.m. each day. Those are the box office’s hours, not the gates’. The countdown on this page counts to Friday, March 5, Arizona time, and says so.","Plan the pickup around the sets you want to see once the festival posts its schedule, then adjust. Your chauffeur works to the time you set, and the reservations team updates the plan when the gate times are announced."),U("Where is M3F, and which entrance do you use?","M3F is at Steele Indian School Park, 300 E Indian School Rd, Phoenix, AZ 85012, the 72-acre park at Central Avenue and Indian School Road; the festival’s FAQ places its bike valet near the entrance at N Central Ave, and it publishes no other entrance for 2027.","The address comes from the festival’s FAQ, and the ticket seller and the City of Phoenix list the same one. The city calls Steele Indian School Park the premiere special event park in central Phoenix.","The festival’s FAQ mentions one entrance, on N Central Ave, near the bike valet. A festival map for 2027 is not posted yet; when it is, check which entrance your pass uses. How each pass enters is the festival’s to describe, not ours.","Children 12 and under get in free with a ticketed adult, and the ticket seller lists the event as all ages, so a family group can ride together. Tell the reservations team if a child seat is needed."),U("Can you take the light rail to M3F?","Yes: the festival’s FAQ points guests to Valley Metro, and the B line runs up Central Avenue past the park, stopping at the Indian School/Central Ave station (stop 10006); the festival also offers bike valet near its N Central Ave entrance, so a pair staying near a station can skip the car.","The festival’s parking answer names Valley Metro first. Valley Metro’s B line schedule lists the Indian School/Central Ave station, stop number 10006, on its route along Central Avenue. Valley Metro fares apply; its site lists them and the service hours.","Transit is a good answer for two or three people who are staying near a station. It is a harder answer for a group of 10 coming from a Scottsdale resort, or for a crew that wants to arrive together and leave together after the last set. That is where a chauffeured ride earns its keep."),U("Is a chauffeured ride worth it from Scottsdale?",`The drive is about ${va.oldTown} minutes from Old Town Scottsdale without event traffic, so the ride is not about distance: it is no festival parking to find, no rideshare wait after the last set, 1 vehicle that keeps the group together, and a set pickup, with nobody in the group driving.`,`From Old Town Scottsdale to Steele Indian School Park is about ${va.oldTown} minutes by Google’s typical time, and about ${va.kierland} from Kierland. Nobody needs a chauffeur for the miles. The value is what a festival day does to them: no festival lot, streets full of people, and the same crowd leaving together at the end.`,wh,"A booked vehicle turns that into a plan. One cabin carries everyone, so nobody is split across 3 rideshares or left to find their own way. The pickup time and place are set before anyone goes in. Nobody in the group has to drive, so nobody has to stop at one drink or leave early to fetch the car.","The honest limit: we cannot drive past closed streets or unload in a travel lane, and we cannot make the exit crowd move faster. The chauffeur is waiting where the open streets and traffic staff allow, and the group walks to it. For two people staying next to a station, the light rail may be the simpler choice."),U("What is the M3F bag policy?","The M3F bag policy allows clear plastic, vinyl or PVC bags up to 12 by 12 by 8 inches, fanny packs and wallets up to 5 by 7 inches that need not be clear, and empty single-pocket hydration packs; outside food and drink are not allowed, except empty water bottles.","Clear backpacks and handbags within 12 by 12 by 8 inches are allowed, as are small clutches, non-professional cameras, phones and GoPros, prescribed medication with a matching ID, sunglasses, hats, earplugs, sunscreen and bug spray. Water stations run throughout the festival, so bring the empty bottle.","Not allowed: totems, wagons, folding chairs and large backpacks; professional cameras and audio recording devices; outside food and drink; weapons and drugs; glass containers, lighters, drones and selfie sticks. The festival is fully cashless: every vendor takes credit and debit cards.","Anything the gate will not take can stay in the vehicle when it is booked by the hour. With no re-entry, though, it stays there until you leave for the night, so pack for the whole day before you go in."),U("Is there re-entry at M3F?","No: the M3F FAQ says there is no re-entry allowed, so each guest goes in once and leaves once on each of the 2 festival days; plan the arrival time, what to carry and the pickup before the group reaches the gate, because stepping out to the vehicle ends that guest’s day.","No re-entry changes how a day is planned. A group that wants dinner out before the late sets should eat before going in, or plan to leave for the night after dinner. Nobody runs back to the car for a jacket or a charger: what is not in the bag stays outside.","It also sets the shape of the booking. A vehicle booked by the hour waits for the whole group at the end; a group that splits, with some leaving early, can book a second pickup for the early leavers or keep one vehicle and one time for everyone. Tell the reservations team which you want."),U("Which vehicle fits an M3F group?",`Festival crews ride a Limo Party Sprinter or the ${te(Ra)}-seat party bus; VIP guests lead with the ${p($e)}, then the ${p(Z)}, our pick for M3F, the ${p(vt)} and the Suburban; big groups and company outings take the ${p(Gr)}, the mini bus, the mini coach or the ${te(Lr)}-seat motorcoach.`,`The table uses current published names, seated capacities, hourly rates and minimums, in three groups. Festival crews: the ${p(kt)}, the ${p(fo)} and the ${p(Ra)}. VIP guests: the ${p($e)}, the ${p(Z)}, which seats ${te(Z)} at ${_r(Z)}/hr, the ${p(vt)} and the ${p(ka)}. Big groups and company outings: the ${p(Gr)}, the ${p(gh)}, the ${p(yh)} and the ${p(Lr)}.`,`A VIP party larger than the ${p($e)} rides in two vehicles, one booking each for the same day and times: the ${p($e)} with the ${p(vt)} seats ${te($e)+te(vt)}, and with the ${p(ka)} it seats ${te($e)+te(ka)}.`,"Count riders for each direction. The group that arrives for the early sets is not always the group that leaves after the last one. Anyone heading elsewhere after the festival comes off the return list before seats are assigned.",`Each booking covers one festival day. For both days, book each day as its own ride; the same vehicle can be requested for each. For a per-person view: 13 riders sharing the ${p(kt)} for 5 billed hours at ${_r(kt)}/hr is about ${Br(kt,5,13)} each before tax; ${te(Z)} riders in the ${p(Z)} for 6 hours is about ${Br(Z,6,te(Z))} each. That is arithmetic, not a flat festival fare.`),U("How should the pickup after M3F work?","Use 2 checkpoints after M3F: the group gathers at the meeting point it chose before going in, then the transportation lead confirms where the vehicle is waiting before anyone walks toward traffic, because the 2027 rideshare zone and any charter pickup area are not yet announced.","The vehicle waits on an open street, where police and event staff allow. It cannot stop wherever a map pin lands, and guests should not walk into a roadway to reach it. Central Avenue carries both traffic and the light rail, so the exact spot is set on the day.","If the group splits inside, pick a landmark to regroup at before the last set, and charge phones before going in. Anyone leaving early or going on elsewhere tells the transportation lead, so the return list stays right. If the night runs long, your chauffeur waits; extra time is billed hourly at the vehicle’s rate, and you can call or text us to extend.","For a multi-vehicle group, label each vehicle, its lead and its drop-off. A crew heading to Old Town and a VIP group heading to a resort should not rely on spotting a driver in a crowd."),U("How far ahead should M3F transportation be booked?",`Availability varies by day and by vehicle, so no fixed lead time applies: request a quote with the rider count, the pickup area and which of the 2 festival days you need, and the reservations team confirms what is open across the ${po.length} vehicles listed, updating the plan as the festival announces its 2027 details.`,"The first request needs the day or days, the hotel or home, a likely passenger count, the arrival you want, and the return. A group does not need every name to begin. It does need to say which group is riding: a festival crew, VIP guests or a big group or company outing.",`During the final 48 hours, confirm addresses, phone numbers and the festival’s newest instructions, including the gate times and any rideshare zone once they are posted. Reach the reservations team at ${C} or ${E}. A ride booking never includes a festival ticket or pass: those are sold by the festival, final sale.`)],kh=[{question:"When is M3F 2027?",answer:"Friday, March 5 and Saturday, March 6, 2027, at Steele Indian School Park in Phoenix. The festival’s poster, lineup, passes and ticket pages all give those two days."},{question:"What time does M3F start?",answer:"The 2027 gate and set times are not announced yet. The festival box office opens at 12 p.m. on Friday and 11 a.m. on Saturday; those are its hours, not the gates’."},{question:"What is M3F?",answer:"M3F Music Festival is a two-day music and art festival at Steele Indian School Park in central Phoenix, with multiple stages and art installations. It also runs The Community Project, year-round programs for art, music and community."},{question:"Where is M3F?",answer:"At Steele Indian School Park, 300 E Indian School Rd, Phoenix, AZ 85012. The festival’s bike valet is near its entrance on N Central Ave."},{question:"Where do you park for M3F?",answer:"M3F has no official festival parking. Its FAQ says to use Valley Metro or rideshare, or to park at 4041 N Central Ave. With a chauffeured ride nobody drives or parks."},{question:"Is there a rideshare drop-off at M3F?",answer:"The festival tells guests to use rideshare services but has not posted a 2027 pickup zone. A chauffeured ride unloads and picks up where police and event staff allow, at a time set in advance."},{question:"Who is playing M3F 2027?",answer:"The 2027 lineup is on the festival’s own site, split into Friday and Saturday on its lineup-by-day page. Set times are not announced yet. This guide does not repeat the lineup."},{question:"What bags are allowed at M3F?",answer:"Clear plastic, vinyl or PVC bags up to 12 by 12 by 8 inches; fanny packs and wallets up to 5 by 7 inches, which need not be clear; and empty single-pocket hydration packs."},{question:"Can I leave M3F and come back?",answer:"No. The festival’s FAQ says there is no re-entry, so plan to go in once and leave once each day."},{question:"Can kids go to M3F?",answer:"Yes. Children 12 and under get in free with a ticketed adult, and the ticket seller lists the festival as all ages."},{question:"Can we book a ride for both days?",answer:"Yes, one booking per day. Each festival day is its own ride, so a Friday-and-Saturday group books two rides, one for each day, and can ask for the same vehicle each time."}],Sh={path:"/guides/m3f-festival-transportation",title:"M3F Festival 2027: parking, rideshare and getting there",metaTitle:"M3F Festival 2027 Parking & Rides",description:"M3F 2027 is Friday and Saturday, March 5–6, at Steele Indian School Park in Phoenix. The official dates, parking, rideshare, light rail, the bag policy and re-entry, and a chauffeured ride from Scottsdale so nobody drives, parks or chases a rideshare at the end.",metaDescription:"March 5–6 dates, no festival parking, light rail and bag rules, or a chauffeured ride",lastUpdated:Or,lastUpdatedLabel:A(Or),eyebrow:"Official dates: March 5–6, 2027",intro:`An M3F ride from Scottsdale Sprinters starts with the festival’s own 2027 facts, a rider count and one transportation lead. Festival crews ride a Limo Party Sprinter or the party bus; VIP guests lead with the ${p($e)} and the ${p(Z)}; big groups and company outings take the executive Sprinter, the mini bus, the mini coach or the motorcoach. This guide uses only published facts, leaves the unannounced ones for closer to the date, and turns each festival day into a written pickup, drop-off and ride home.`,sections:vh,faqs:kh,links:[{href:"/fleet/ultra-luxury-party-sprinter-scottsdale",label:p(Z)},{href:"/fleet/limo-sprinter-16-scottsdale",label:p(fo)},{href:"/fleet/party-bus-28-scottsdale",label:p(Ra)},{href:"/services/scottsdale-party-bus-rental",label:"Scottsdale party bus rental"},{href:"/service-areas/phoenix",label:"Phoenix service area"},{href:"/pricing",label:"Published hourly pricing"}],sources:bh,fleetRows:po},Pd=[Sh],Ur="2026-09-24",Ah="/guides/venues/talking-stick-resort-amphitheatre",De="ultra-luxury-party-sprinter-scottsdale",Sa="maybach-jet-sprinter-scottsdale",Th="maybach-shuttle-sprinter-8",$h="premium-suv-scottsdale",Ie="limo-sprinter-13-scottsdale",Aa="limo-sprinter-16-scottsdale",Ta="party-bus-28-scottsdale",xe="executive-sprinter-scottsdale",Ph="executive-white-sprinter-scottsdale",$a="executive-mini-bus-26-scottsdale",Pa="executive-luxury-bus-29-scottsdale",Ca="motorcoach-56",d=e=>o[e],ae=e=>i[e],Ea=e=>`${l(s[e].hourlyRateCents)} an hour with a ${s[e].minimumHours}-hour minimum`,Je="https://www.talkingstickresortamphitheatre.com",Ch=`${Je}/visit`,Eh=`${Je}/know-before-you-go`,Fh=`${Je}/faq`,Dh=`${Je}/upgrades/parking`,Ih=`${Je}/accessibility`,xh=`${Je}/shows`,Rh="https://www.livenation.com/venue/KovZpZAE6vJA/talking-stick-resort-amphitheatre-events",Mh="https://www.prnewswire.com/news-releases/phoenix-music-venue-to-be-renamed-talking-stick-resort-amphitheatre-301719437.html",Nh=[{label:"Talking Stick Resort Amphitheatre, plan your visit",href:Ch},{label:"Talking Stick Resort Amphitheatre, the need-to-know before you go",href:Eh},{label:"Talking Stick Resort Amphitheatre, frequently asked questions",href:Fh},{label:"Talking Stick Resort Amphitheatre, parking upgrades",href:Dh},{label:"Talking Stick Resort Amphitheatre, accessibility",href:Ih},{label:"Talking Stick Resort Amphitheatre, upcoming shows",href:xh},{label:"Live Nation, Talking Stick Resort Amphitheatre events",href:Rh},{label:"Live Nation, Phoenix music venue to be renamed Talking Stick Resort Amphitheatre (January 11, 2023)",href:Mh}],Ma=["January","February","March","April","May","June","July","August","September","October","November","December"],Wh=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];function Oh(e){const[t,a,n]=e.split("-").map(Number);return`${Wh[new Date(Date.UTC(t,a-1,n)).getUTCDay()]}, ${Ma[a-1]} ${n}, ${t}`}function Gh(e){return`${Oh(e.date)}: ${e.title} (show ${Zr(`${e.date}T${e.starts}:00-07:00`)}).`}function oe(e,t,...a){return{question:e,answer:t,paragraphs:a}}const V=La.filter(e=>e.date.startsWith("2026")),Fa=La.filter(e=>!e.date.startsWith("2026")),Lh=[oe("How does parking work at Talking Stick Resort Amphitheatre?","Talking Stick Resort Amphitheatre’s parking lots typically open 30 minutes before the scheduled gate time, and gates usually open 60 to 90 minutes before the show. Parking is sold show by show on the venue’s parking page, and its upgrades include Premier Parking, a short walk from the gates, and Easy Out Parking near the West Gate (Gate 2) for the fastest exit.","Reserved Premier Parking is a guaranteed space at the front of the Premier lot, held all night whether you arrive early or late; it is for cars only. The venue also sells an oversized space for a limousine or an RV in the Premier lot. Every upgrade is limited.","No tailgating is allowed, and no overnight parking: an unauthorized vehicle on site before or after an event is towed at the owner’s expense. Accessible parking is inside Gate 3 and Gate 6 off Encanto Boulevard, first come, first served, for a state-issued placard or plate; the venue suggests arriving when the lots open.","The venue’s pages publish no parking price: parking is sold per show, and the box office handles parking refunds and upgrades."),oe("Where is the drop-off and rideshare pickup at Talking Stick Resort Amphitheatre?","The venue’s drop-off and pick-up area is on the west side of Talking Stick Resort Amphitheatre, through Gate 3: tell parking staff you are dropping off and they show you the way. To pick up, arrive at least 45 minutes before the show ends, or you will not be able to enter. Rideshare riders meet their car on Palm Lane, on the southwest side of the venue.","That is the area a chauffeured group uses too. We tell parking staff we are dropping off, unload the group through Gate 3, and are back inside the pick-up area before the 45-minute cutoff, so the group walks out to its own vehicle instead of joining the rideshare line on Palm Lane.","A group that splits across cars also splits across lots, gates and exits. One vehicle arrives with everyone at once and leaves with everyone at once."),oe("Where is Talking Stick Resort Amphitheatre, and is it at Talking Stick Resort?","Talking Stick Resort Amphitheatre is at 2121 North 83rd Avenue, Phoenix, AZ 85035, in Maryvale on the west side of Phoenix. It is not at Talking Stick Resort: the venue says plainly that it is not the same location as the Talking Stick Resort & Casino, which is in Scottsdale. Talking Stick Resort is the amphitheatre’s name-in-title sponsor.","Live Nation, which runs the venue, renamed it in January 2023; it was the Ak-Chin Pavilion before that. The venue has hosted concerts for over 30 years.","By Google’s typical drive time, measured on September 24, 2026 without show traffic, the amphitheatre is 16 minutes from downtown Phoenix, 20 minutes from Phoenix Sky Harbor, 29 minutes from Old Town Scottsdale, 34 minutes from the Talking Stick Resort casino and 38 minutes from Kierland. Show nights add the venue’s own traffic to the last mile."),oe("What time do gates open at Talking Stick Resort Amphitheatre?","Gates at Talking Stick Resort Amphitheatre usually open 60 to 90 minutes before showtime, and the parking lots about 30 minutes before the gates. The exact gate and parking times for each show are posted on the venue’s Need-to-Know page closer to the date.","There are two main entry gates, the West Gate and the East Gate, and some shows open only one. The box office is open on show days only: the West Box Office from noon, the East Box Office about an hour before doors, card only.","Re-entry is not permitted: once you leave, you need a new ticket to come back in. Events are all ages unless the show says otherwise, and shows go on rain or shine, barring severe weather."),oe("What is the Talking Stick Resort Amphitheatre bag policy?","Only small clutches, wristlets or fanny packs up to 6 by 9 inches, or clear plastic bags up to 12 by 12 by 6 inches, are allowed inside Talking Stick Resort Amphitheatre. All bags are subject to search at entry, with metal detectors and sometimes a pat-down.","Not allowed: backpacks and other bags outside the policy, coolers of any size, outside food or drink except factory-sealed water, alcohol, glass, cans, metal hydroflasks, lawn chairs, strollers, laser pointers, selfie sticks and aerosol sunscreen. Factory-sealed, unfrozen water up to one gallon per person is allowed, and refill stations are inside.","The venue is cash-free: guest services swap cash for a card at no charge. Settle bags at the hotel; a group that is dropped off has no car in the lot to go back to during the show."),oe("How many people does Talking Stick Resort Amphitheatre hold, and how does the lawn work?","Live Nation describes Talking Stick Resort Amphitheatre as a 20,000-seat outdoor venue. The lawn is always first come, first served: a row or seat number on a lawn ticket is only for the box office’s tracking, and there are no assigned seats on the lawn.","Lawn chairs can be rented for most shows and are the only chairs allowed inside; blankets are not permitted at some shows. For a large party, the venue’s Premium Seating department sells VIP boxes, suites and clubs that hold more guests than the standard ticket limit.","For a group, the lawn decides the ride: arriving together at gate time is how a crew gets a spot together, and leaving together is how it gets home."),oe("Which vehicle fits a Talking Stick Resort Amphitheatre group?",`Concert crews ride the ${d(Ie)}, the ${d(Aa)} or the ${d(Ta)}. A VIP night takes the ${d(Sa)}, the ${d(De)}, the ${d(Th)} or the ${d($h)}. Corporate and big groups take the ${d(xe)}, the ${d(Ph)}, the ${d($a)}, the ${d(Pa)} or the ${d(Ca)}.`,`Seat counts are seated capacities from the fleet: the ${d(De)} seats ${ae(De)}, the ${d(Ie)} ${ae(Ie)}, the ${d(Aa)} ${ae(Aa)}, the ${d(Ta)} ${ae(Ta)} and the ${d(Sa)} ${ae(Sa)}. The ${d(xe)} seats ${ae(xe)}, the ${d($a)} ${ae($a)}, the ${d(Pa)} ${ae(Pa)} and the ${d(Ca)} ${ae(Ca)}.`,`Our pick for a night on the lawn is the ${d(De)}, ${Ea(De)}: fiber-optic lighting with eighteen modes, an ultra-premium sound system with subwoofers, a wet bar with champagne glass holders and a full partition with an intercom to your chauffeur. The ${d(Ie)} is ${Ea(Ie)}, and the ${d(xe)} is ${Ea(xe)}. Every rate prices the whole vehicle, before tax.`,"Count riders for the ride home as well as the ride there; the late list is the one that matters. For a group bigger than one vehicle, we plan two or more and quote them together."),oe("How should a group plan the ride to a Talking Stick Resort Amphitheatre show?","Plan backwards from the show time. Gates usually open 60 to 90 minutes before the show, so a pickup that lands the group at the Gate 3 drop-off around gate time leaves room for the lines, the bag check and a spot on the lawn.","The ride home is the part to plan hardest. The venue lets pickups into its pick-up area only until 45 minutes before the show ends, so your chauffeur is in place before the encore and the group walks straight out to its vehicle.",`Book by the hour and the vehicle is yours for the whole night, dinner before the show included, or book a ride there and a ride back. Reach the reservations team at ${C} or ${E} with the show, the date, the pickup area and the rider count.`)],_h=oe("What’s coming up at Talking Stick Resort Amphitheatre?",`Talking Stick Resort Amphitheatre lists ${V.length} more shows this fall, from ${V[0].label} on ${Ma[Number(V[0].date.slice(5,7))-1]} ${Number(V[0].date.slice(8))} to ${V[V.length-1].label} on ${Ma[Number(V[V.length-1].date.slice(5,7))-1]} ${Number(V[V.length-1].date.slice(8))}, and ${Fa.length===1?`one 2027 show so far, ${Fa[0].label}`:`${Fa.length} 2027 shows so far`}. As the venue’s show list gave them on September 24, 2026:`,...La.map(Gh),"Gate and parking times for each show are posted on the venue’s Need-to-Know page closer to the date. New shows are added to the venue’s calendar through the year, and it is the place to check before you book."),Bh=[{question:"Where do you park at Talking Stick Resort Amphitheatre?",answer:"In the venue’s own lots, which typically open 30 minutes before the gates. Parking is sold per show, with Premier Parking a short walk from the gates and Easy Out Parking by the West Gate (Gate 2) for the fastest exit. No tailgating and no overnight parking."},{question:"How much is parking at Talking Stick Resort Amphitheatre?",answer:"The venue’s pages publish no price: parking is sold per show on the venue’s parking page. Premier, Reserved Premier and Easy Out spaces cost more and are limited."},{question:"Where is the rideshare pickup at Talking Stick Resort Amphitheatre?",answer:"On Palm Lane, on the southwest side of the venue. Drop-off is on the west side through Gate 3; tell parking staff you are dropping off."},{question:"Can a limo or party bus drop off at Talking Stick Resort Amphitheatre?",answer:"Yes, in the venue’s drop-off and pick-up area on the west side through Gate 3, as parking staff direct. For the ride home the vehicle must be in the pick-up area at least 45 minutes before the show ends, or it cannot enter."},{question:"Is Talking Stick Resort Amphitheatre at Talking Stick Resort?",answer:"No. The amphitheatre is at 2121 North 83rd Avenue in Phoenix; the Talking Stick Resort & Casino is in Scottsdale, about 34 minutes’ drive away. The venue says they are not the same location."},{question:"What time do gates open at Talking Stick Resort Amphitheatre?",answer:"Usually 60 to 90 minutes before showtime, with the lots about 30 minutes before the gates. Exact times are posted for each show on the venue’s Need-to-Know page."},{question:"What is the Talking Stick Resort Amphitheatre bag policy?",answer:"Small clutches, wristlets or fanny packs up to 6 by 9 inches, or clear bags up to 12 by 12 by 6 inches. No backpacks, coolers or lawn chairs of your own."},{question:"Can you tailgate at Talking Stick Resort Amphitheatre?",answer:"No. The venue allows no tailgating and no overnight parking."},{question:"How many people does Talking Stick Resort Amphitheatre hold?",answer:"Live Nation describes it as a 20,000-seat outdoor venue, with a first-come, first-served lawn."},{question:"Can you leave and come back in at Talking Stick Resort Amphitheatre?",answer:"No. Re-entry is not permitted; leaving means a new ticket to come back in."}],Uh={path:Ah,title:"Talking Stick Resort Amphitheatre: Parking, Upcoming Shows and Concert Rides",metaTitle:"Talking Stick Amphitheatre Parking",description:"Talking Stick Resort Amphitheatre in Phoenix, not the Scottsdale casino: how the parking works, the Gate 3 drop-off and the Palm Lane rideshare pickup, gate times, the bag policy, the lawn, the upcoming shows, and a chauffeured ride so nobody drives or parks.",metaDescription:"Lots, gates, the Gate 3 drop-off and a chauffeured ride",lastUpdated:Ur,lastUpdatedLabel:A(Ur),eyebrow:"Phoenix · Maryvale",intro:"Scottsdale Sprinters’ short answer on Talking Stick Resort Amphitheatre: it is the outdoor concert venue at 2121 North 83rd Avenue in Phoenix, not the Talking Stick Resort casino in Scottsdale. Its lots typically open 30 minutes before the gates, and the gates usually 60 to 90 minutes before the show. The drop-off and pick-up area is on the west side through Gate 3, and rideshare pickup is on Palm Lane. For a group, one chauffeured vehicle replaces the lot, the pickup line and the drive home.",sections:[...Lh,_h],faqs:Bh,links:[{href:"/guides/venues/talking-stick-resort",label:"Talking Stick Resort group arrival guide"},{href:"/experiences/concert-stadium",label:"Concert and stadium transportation"},{href:"/service-areas/phoenix",label:"Phoenix service area"},{href:`/fleet/${De}`,label:d(De)},{href:`/fleet/${Ie}`,label:d(Ie)},{href:`/fleet/${xe}`,label:d(xe)},{href:"/pricing",label:"Published hourly pricing"}],sources:Nh},Cd=[Uh],It="2026-09-24";function $(e,t,...a){return{question:e,answer:t,paragraphs:a}}const Hh=Ao.filter(e=>Oe(e)).map(e=>({slug:e}));function Ha(e,t){const a=To(Hh,{occasionClass:e,headcount:t});if(a.mismatch)throw new Error(`Venue parking guide: no ${e} unit fits ${t??"any"} riders`);const n=[a.featured,a.companion,...a.rest].flatMap(c=>c?[c.slug]:[]);if(n.length<2)throw new Error(`Venue parking guide: fewer than 2 ${e} units are listed`);return n}const We=Ha(jr({occasion:"game day party"})),qe=Ha(jr({occasion:"corporate outing"})),Lt=Math.max(...We.map(e=>i[e])),ze=Ha("large_group",Lt+1),x=e=>o[e],Na=e=>i[e];function qh(e){return e.length<=1?e.join(""):`${e.slice(0,-1).join(", ")} and ${e[e.length-1]}`}const zh=4;function Da(e){return qh(e.slice(0,zh).map(t=>`${x(t)} up to ${Na(t)}`))}function Vh(e){const t=s[e],a=Qr({hourlyRateCents:t.hourlyRateCents,minimumHours:t.minimumHours,capacity:Na(e)},Nt);return`The ${x(e)} is ${l(t.hourlyRateCents)} an hour with a ${t.minimumHours}-hour minimum, so ${a.billedHours} billed hours come to ${a.fareLabel} before tax, about ${a.perPersonLabel} each when all ${Na(e)} seats are filled.`}const mo=[We[0],qe[0],ze[0]];function go(){return mo.map(e=>({href:`/fleet/${e}`,label:x(e)}))}function yo(){const e=mo;return[`Seats come from the published fleet. For game-day groups: ${Da(We)}. For client outings: ${Da(qe)}. For more than ${Lt} riders: ${Da(ze)}.`,`Every rate prices the whole vehicle by the hour, and here is a ${Nt}-hour booking in each lead vehicle. ${e.map(Vh).join(" ")}`,"Those figures are arithmetic from the published rates, not a quote. An hourly booking keeps the vehicle for the whole outing, so the drive each way counts toward the hours. A ride there and a separate ride back can be booked as a transfer instead of by the hour; the written quote shows how the drive is priced."]}const J="https://www.mlb.com/dbacks/ballpark",Jh=[{label:"Arizona Diamondbacks — Where to Park at Chase Field",href:`${J}/transportation/parking`},{label:"Arizona Diamondbacks — Chase Field A-to-Z Guide",href:`${J}/information/guide`},{label:"Arizona Diamondbacks — Chase Field Disability Access Guide",href:`${J}/disability-access-guide`},{label:"Arizona Diamondbacks — Know Before You Go",href:`${J}/information/know-before-you-go`},{label:"Arizona Diamondbacks — Driving Directions",href:`${J}/transportation/driving-directions`},{label:"Arizona Diamondbacks — Additional Traffic Information",href:`${J}/transportation/additional-information`},{label:"Arizona Diamondbacks — Valley Metro Rail",href:`${J}/transportation/valley-metro-rail`},{label:"Arizona Diamondbacks — Clear Bag Policy",href:`${J}/information/bag-policy`},{label:"Valley Metro — Destinations",href:"https://www.valleymetro.org/how-to-ride/destinations"},{label:"City of Phoenix — ParkPHX downtown parking tool",href:"https://www.phoenix.gov/newsroom/convention-center-news/3371.html"},{label:"Arizona Diamondbacks — 2027 Regular Season Schedule",href:"https://www.mlb.com/dbacks/schedule/2027-03"},{label:"MLB.com — MLB releases 2027 regular-season schedule",href:"https://www.mlb.com/dbacks/news/mlb-2027-schedule-released"},{label:"Arizona Diamondbacks — Chase Field Events",href:`${J}/events`},{label:"Arizona Diamondbacks — The Hondo Rodeo Fest at Chase Field",href:`${J}/events/upcoming/hondo-rodeo-fest`},{label:"MLB.com — Commissioner Rob Manfred on initial CBA proposals",href:"https://www.mlb.com/news/mlb-commissioner-rob-manfred-on-initial-cba-proposals"}],Xe=["January","February","March","April","May","June","July","August","September","October","November","December"],Yh={Sun:"Sunday",Mon:"Monday",Tue:"Tuesday",Wed:"Wednesday",Thu:"Thursday",Fri:"Friday",Sat:"Saturday"};function Ia(e){const t=L(e);return`${Yh[Xr(e)]}, ${Xe[t.month]} ${t.day}, ${t.year}`}function Zh(e,t){const a=L(e),n=L(t);return e===t?`${Xe[a.month]} ${a.day}`:a.month===n.month?`${Xe[a.month]} ${a.day}–${n.day}`:`${Xe[a.month]} ${a.day} – ${Xe[n.month]} ${n.day}`}function ot(e){return e.label.replace(/^.*\bvs\. /,"")}function jh(e){const t=[],a=n=>{const c=L(n);return Date.UTC(c.year,c.month,c.day)/864e5};for(const n of e){const c=t[t.length-1];c&&a(n.date)-a(c.last)<=2?(c.last=n.date,c.visitors.includes(ot(n))||c.visitors.push(ot(n))):t.push({first:n.date,last:n.date,visitors:[ot(n)]})}return t}function Kh(e){return e.length<=1?e.join(""):`${e.slice(0,-1).join(", ")} and ${e[e.length-1]}`}function Qh(){const e=Kr({items:Fo}),t=e[0],a=e[e.length-1],n=e.filter(g=>g.startsAt),c=n.length===e.length?"each with its first-pitch time below":n.length>0?"with first-pitch times announced for some of them so far":"and the team has not announced first-pitch times yet",N=jh(e).map(g=>`${Zh(g.first,g.last)} (${Kh(g.visitors)})`),ne=L(t.date).year;return $("When are the D-backs home games and concerts at Chase Field?",`The Arizona Diamondbacks play ${e.length} home games at Chase Field in ${ne}, from the home opener against the ${ot(t)} on ${Ia(t.date)} to the last home game against the ${ot(a)} on ${Ia(a.date)}, ${c}.`,`The home stands, in order: ${N.join("; ")}. Opening Day, Thursday, March 25, ${ne}, is on the road in San Diego, so the first game at Chase Field is the home opener.`,n.length>0?`Announced first pitches, in Arizona time: ${n.map(g=>`${Ia(g.date)}, ${g.label}, ${Zr(g.startsAt)}`).join("; ")}. The rest are added here as the Diamondbacks announce them. Gates open 90 minutes before first pitch Sunday through Friday and 2 hours before first pitch on Saturday, so give the reservations team your game date when you book and the chauffeur plans the pickup around it.`:"The Diamondbacks announce first-pitch times closer to the season, and they are added here as they are. Gates open 90 minutes before first pitch Sunday through Friday and 2 hours before first pitch on Saturday, so give the reservations team your game date when you book and the chauffeur plans the pickup around it.",`The one concert the Diamondbacks list for Chase Field as of ${A($o)} is the Hondo Rodeo Fest, November 13–15, 2026: each night a full rodeo, then a full-length concert, with Tim McGraw and Miranda Lambert on Friday, Blake Shelton and Turnpike Troubadours on Saturday, and Parker McCollum and Lynyrd Skynyrd on Sunday. Shows for ${ne} are announced by the ballpark closer to the date.`,"One caveat for the season: Major League Baseball’s labor agreement expires on December 1, 2026. If a new agreement is not in place in time, games can move, and this list follows the official schedule as MLB and the Diamondbacks publish it.")}const Xh=[$("Where do you park for Chase Field?","Chase Field has an attached 1,500-car garage just south of the ballpark on 4th Street that works first come, first served, and the Diamondbacks also offer pre-booked spaces through ParkWhiz, their preferred parking partner, so you can hold a spot before driving to the game.","The ballpark is at 401 East Jefferson Street in downtown Phoenix, bounded by 7th Street on the east, 4th Street on the west, Jefferson Street on the north and the Southern Pacific Railroad tracks on the south. The Diamondbacks’ traffic advice is to park in the same quadrant you drive in from. Arriving from the south, for example, means parking between 3rd Avenue and 9th Street, from Lincoln Street to Jefferson Street.","Payment is not the same everywhere. The Diamondbacks warn that some garages and lots around Chase Field take only credit cards while others take only cash, so carry both unless the space is prepaid. The City of Phoenix’s ParkPHX tool lists every public downtown parking facility in one place, with height limits, accessible spaces and reservations at participating facilities.","Downtown parking is not one system. The City of Phoenix runs its own garages through the Phoenix Convention Center, and the Diamondbacks’ pre-booking runs through ParkWhiz, so rates and payment rules differ by facility. Book or choose the space before you leave, not at the last light before the ballpark."),$("What should you know about the Chase Field Garage?","The Chase Field Garage is attached to the ballpark just south of it on 4th Street, holds 1,500 cars, takes high-profile vehicles at every entrance, sets aside 31 accessible spaces, and has its own entrance on Level 3 for Suite and 200-level seats, with accessible turnstiles.","All of its parking, the accessible spaces included, is first come, first served. When demand is high, the Diamondbacks say some garages accept only special parking passes, so a driver without one may need another garage. A sign at the booth shows when accessible parking in the Chase Field or Jefferson Street garage is full, before you pull in.","The Jefferson Street Garage is the second garage the team names. Both garages have bicycle racks at street level, which the Diamondbacks list among the places to lock a bike, because bicycles are not allowed inside the ballpark.","If the plan depends on the attached garage, pre-book or arrive early. The City of Phoenix, which runs the city-owned downtown garages, says spaces are in high demand during peak events."),$("Where is the Chase Field rideshare drop-off and pickup?","The Diamondbacks publish 2 rideshare points for pickup and drop-off, 5th Street north of Washington Street and Jackson Street east of 9th Street, plus a staffed drop-off on the south side of Jefferson Street just west of 7th Street, near Gate K, listed in the ballpark’s accessibility guide.","One rideshare point is north of the ballpark, past Washington Street; the other is east of it, beyond 9th Street on Jackson Street. Pick the one on the side you are heading home from and agree on it before the game. A group that splits between the two points is waiting in two places.","The Jefferson Street drop-off is staffed and has shaded benches for guests waiting on a ride. The driver who drops a guest there should ask for a Pick-Up Pass, which carries a map and directions back to the same spot after the game. Hold it up when traffic control detours you, so staff can direct you back to that lot.","None of these points is reserved for chauffeured vehicles: the Diamondbacks publish no separate limo or charter zone. A booked vehicle works from the published points and the instruction confirmed for the booking. The team also warns that traffic around the ballpark can be rerouted as conditions dictate, as it does for southbound 3rd Street at Washington Street."),$("Can you take light rail to Chase Field?","Yes, Valley Metro’s A line stops at 2 stations near the ballpark, 3rd Street and Washington and 3rd Street and Jefferson, with trains every 15 to 20 minutes, and the Diamondbacks list 13 light rail Park-and-Ride locations for fans who drive part of the way.","Buy the fare at any station with cash, credit or debit, or load the Valley Metro app or a Copper card before the game. The Diamondbacks suggest paying in advance to skip the lines after the game, and a daily fare cap means you stop paying once you reach it.","Valley Metro also lists 2 bus connections for Chase Field: Route 1 on Washington Street and Route 7 on 7th Street. The Diamondbacks’ Park-and-Ride list runs from 19th Avenue and Dunlap to Gilbert Road and Main Street, and the Valley Metro app plans the trip from any of them.","Rail suits a couple or a small party staying near a station. A larger group coming from Scottsdale resorts has more steps: getting everyone to a Park-and-Ride, onto one train and back again after the final out."),$("How much time and hassle does parking at Chase Field add?","Driving yourself adds 3 jobs to the game: getting a space before the garage or lot fills, paying the way that facility accepts, and leaving by the Diamondbacks’ quadrant exit routes after the final out, alongside everyone else leaving the ballpark at the same time.","Arrival comes first. Gates open 90 minutes before first pitch Sunday through Friday and 2 hours before first pitch on Saturday, and the city says downtown garages are in high demand during peak events. Pre-booking through ParkWhiz or ParkPHX removes the search, not the drive.","Then comes the exit. The Diamondbacks route traffic by quadrant after the game. From the southeast quadrant, south of Jefferson and east of 4th Street, drivers go south to Lincoln Street and then east to 7th Street. From the southwest quadrant they go south to Lincoln, which becomes Grant, and west to 7th Avenue. North of Washington, 3rd and 7th Avenues lead to the freeways.","The drive in has its own warnings. From north central Phoenix the team calls 7th Street the least preferred route because of heavy use, and it calls the 3rd Street HOV exit the least preferred during arrival. None of it is hard, but all of it falls on whoever drives, who also has to stay fit to drive home."),$("Why does a chauffeured drop-off beat parking at Chase Field?","A chauffeured drop-off removes 3 costs of driving: the group steps out at the drop-off point confirmed for the booking instead of walking in from wherever a space was found, nobody sits in a garage exit line after the game, and one vehicle carries everyone, so nobody has to be the designated driver.","It is not a way around traffic control. After the game every vehicle, ours included, moves with the downtown traffic plan, and the chauffeur meets the group at the agreed point once it is reachable. What changes is who does the work: the chauffeur handles the route in, the drop-off, the timing of the pickup and the route out.","One vehicle also keeps a group together. Separate cars mean separate garages, separate exits and separate arrival times. A Sprinter or bus arrives with everyone at once, which matters when the plan includes dinner or a hotel pickup before first pitch.","The trade-off is timing. A pickup runs on the traffic plan and the chauffeur’s approach, not on the minute you walk out, so agree on the pickup point in advance and message the chauffeur once the whole group is together."),$("Which vehicle fits a Chase Field group, and what does it cost?",`Match the vehicle to the group: game-day friends start with the ${x(We[0])} or the ${x(We[1])}, a client outing starts with the ${x(qe[0])} or the ${x(qe[1])}, and a group larger than ${Lt} moves up to the ${x(ze[0])} or the ${x(ze[1])}.`,...yo()),$("How should a group plan the Chase Field arrival and pickup?","Plan 4 things before leaving the hotel: an arrival inside the gate window, which opens 90 minutes before first pitch Sunday through Friday and 2 hours before on Saturday, one agreed pickup point, one person who messages the chauffeur, and bags that pass the clear bag policy.","The clear bag policy decides what leaves the vehicle. It allows one clear bag up to 12 by 6 by 12 inches or a one-gallon clear bag, plus a small clutch up to 4.5 by 6.5 inches, and no backpacks. A group that is dropped off has no car in the garage to leave a bag in, so settle bags at the hotel. The Diamondbacks’ locker partner, Mobile Locker Company, stores non-approved bags for a fee.","For the return, choose the rideshare point on the side you will leave from, or the Jefferson Street drop-off when a guest needs the accessible entrance, and share it with the whole group before first pitch. When the game ends, gather first, then message the chauffeur once with the group count, rather than having several people send pins.",`Guests who have difficulty walking to their seats can ask any Chase Field staff member for a complimentary wheelchair escort from the gates or drop-off areas to their seats; the Diamondbacks say no advance request is needed. For a change of plan on the day, call the reservations team at ${C} or email ${E}.`),Qh()],ed=[{question:"How much is parking at Chase Field?",answer:"The Diamondbacks do not publish one parking price. Garages and lots around the ballpark set their own rates, and some take only cards while others take only cash. To see a price before you go, pre-book through ParkWhiz, the team’s preferred parking partner, or compare downtown garages on the City of Phoenix’s ParkPHX."},{question:"Where is the best place to park for Chase Field?",answer:"The Chase Field Garage is attached to the ballpark, just south of it on 4th Street, with 1,500 spaces on a first come, first served basis. Otherwise the Diamondbacks advise parking in the same quadrant you drive in from, and pre-booking through ParkWhiz holds a space before you leave."},{question:"Is there free parking near Chase Field?",answer:"The Diamondbacks publish no free parking. Their alternative to a garage is light rail: they list 13 Park-and-Ride locations, and trains stop at 3rd Street and Washington or 3rd Street and Jefferson, within walking distance of the ballpark."},{question:"Where is the rideshare pickup at Chase Field?",answer:"At 5th Street north of Washington Street, or Jackson Street east of 9th Street. Agree on one with your group before the game."},{question:"Where is accessible parking and drop-off at Chase Field?",answer:"The attached garage has 31 spaces for a valid disabled plate or placard, first come, first served. The staffed drop-off is on the south side of Jefferson Street, just west of 7th Street, near Gate K. Ask for a Pick-Up Pass to get back to it after the game."},{question:"What time do Chase Field gates open?",answer:"90 minutes before first pitch Sunday through Friday, and 2 hours before first pitch on Saturday. The Diamondbacks post special gate times for some dates in their A-to-Z guide."},{question:"Can a chauffeured Sprinter drop our group at Chase Field?",answer:"Yes, at a point the live traffic plan allows. The Diamondbacks publish two rideshare points and a staffed drop-off on Jefferson Street but no separate limo or charter zone, so the chauffeur confirms the drop-off for your booking and vehicle."}],Ed={path:"/guides/venues/chase-field",title:"Chase Field Parking Guide: Garages, Rideshare & Drop-Off",metaTitle:"Chase Field Parking & Drop-Off Guide",description:"Where to park for Chase Field: the attached 1,500-car garage, ParkWhiz pre-booking, the two rideshare points, light rail stations and gate times, and how a chauffeured group drop-off compares.",metaDescription:"The 1,500-car garage, ParkWhiz pre-booking, light rail stops and gate times",lastUpdated:It,lastUpdatedLabel:A(It),intro:"Scottsdale Sprinters’ short answer on Chase Field parking: use the attached 1,500-car Chase Field Garage on 4th Street, which is first come, first served, or pre-book a nearby space through ParkWhiz, the Diamondbacks’ preferred parking partner, and carry a card and cash because some lots take only one. Rideshare pickups use 5th Street north of Washington Street or Jackson Street east of 9th Street, and light rail stops at 3rd Street and Washington or 3rd Street and Jefferson. For a group, one chauffeured vehicle replaces the garage, the payment and the drive out after the final out.",sections:Xh,faqs:ed,links:[...go(),{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published pricing"}],sources:Jh},Se="https://www.statefarmstadium.com",td=[{label:"State Farm Stadium — Directions and Parking",href:`${Se}/plan-your-visit/directions-parking`},{label:"State Farm Stadium — 2025 Cardinals parking map",href:`${Se}/assets/img/2025-Cardinals-Parking-Map-db3cd0d2f1.png`},{label:"State Farm Stadium — 2025 event parking map (concerts, soccer, dirt shows)",href:`${Se}/assets/img/2025-Stadium-Event-Parking-Map-fb2439fd59.png`},{label:"State Farm Stadium — A-Z Guide",href:`${Se}/a-z-guide`},{label:"State Farm Stadium — ADA and Accessibility",href:`${Se}/ada-accessibility`},{label:"State Farm Stadium — Safety and Clear Bag Policy",href:`${Se}/clear-bag-policy`},{label:"Fiesta Sports Foundation — 2026-27 Vrbo Fiesta Bowl parking map",href:"https://www.fiestasportsfoundation.org/documents/2026/8/14/26-27_VFB_Parking_Map_FINAL.pdf"},{label:"Fiesta Sports Foundation — Vrbo Fiesta Bowl A-Z Guide",href:"https://www.fiestasportsfoundation.org/sports/2019/12/6/vrbo-fiesta-bowl-a-z-guide.aspx"},{label:"Valley Metro — West Valley destinations",href:"https://www.valleymetro.org/how-to-ride/destinations/destinations-west-valley"},{label:"State Farm Stadium — Upcoming events",href:`${Se}/events`}],wo=["January","February","March","April","May","June","July","August","September","October","November","December"],ad={Sun:"Sunday",Mon:"Monday",Tue:"Tuesday",Wed:"Wednesday",Thu:"Thursday",Fri:"Friday",Sat:"Saturday"};function He(e){const t=L(e);return`${wo[t.month]} ${t.day}, ${t.year}`}function Wa(e){if(!e.orDate)return`${ad[Xr(e.date)]}, ${He(e.date)}`;const t=L(e.date),a=L(e.orDate);return t.month===a.month&&t.year===a.year?`${wo[t.month]} ${t.day} or ${a.day}, ${a.year}`:`${He(e.date)} or ${He(e.orDate)}`}function Hr(e,t){if(t.length===1)return`${e} on ${Wa(t[0]).replace(/^\w+, /,"")}`;if(t.length===2&&L(t[0].date).year===L(t[1].date).year){const[c,N]=t.map(ne=>He(ne.date));return`${e} on ${c.replace(/, \d{4}$/,"")} and ${N}`}const a=t[t.length-1],n=a.orDate?Wa(a):He(a.date);return`${t.length} ${e} from ${He(t[0].date)} to ${n}`}function qr(e){return`${Wa(e)}, ${e.label}, ${Do(e).replace(/^Day and /,"day and ")}`}function rd(){const e=Kr({items:Io}),t=Po.map(g=>({series:g,items:e.filter(_t=>_t.series===g.id)})).filter(g=>g.items.length>0),[a,...n]=t,c=Co({items:e}),N=n.map(({series:g,items:_t})=>Hr(g.article?`${g.article} ${g.label}`:g.label,_t)),ne=N.length>1?`${N.slice(0,-1).join(", ")} and ${N[N.length-1]}`:N.join("");return $("When are the Cardinals home games and concerts at State Farm Stadium?",`Our ${L(c.start).year}-${String(L(c.end??c.start).year).slice(2)} date list for State Farm Stadium has ${Hr(a.series.label,a.items)}${ne?`, plus ${ne}`:""}, each with its kickoff or show time below.`,`${a.series.label}, in Arizona time: ${a.items.map(qr).join("; ")}.`,...n.length?[`Also at the stadium: ${n.flatMap(({items:g})=>g.map(qr)).join("; ")}.`]:[],`These dates and times are as State Farm Stadium and the Arizona Cardinals listed them on ${A(Eo)}. Start times can change, so check the event’s own page before the day. Give the reservations team your date when you book, and the chauffeur plans the pickup around that start: on Cardinals game days the lots open 4 hours before kickoff, and the gates open 2 hours before kickoff for NFL games.`)}const od=[$("Where do you park at State Farm Stadium?","State Farm Stadium recommends buying parking in advance through SeatGeek and describes event-day parking in 2 colors, red Preferred Parking entered only at Maryland Avenue and 95th Avenue and blue General Parking, where staff fill lots by capacity and traffic flow, and every parking area takes credit cards only.","On the stadium’s 2025 Cardinals parking map, the red Preferred lots, West Preferred and North Preferred, sit beside the stadium, and East Preferred is marked as its own lot on the east side. For the red lots, leave Loop 101 at Cardinals Way when coming from the south. From the north, leave at Glendale Avenue, head west to 99th Avenue and then east on Maryland Avenue. The stadium suggests searching Red Lot - State Farm Stadium on Waze.","General Parking is reached from Glendale Avenue or Cardinals Way off Loop 101, or from 91st and 99th Avenues. You do not pick the lot: parking staff and Glendale police direct each car to the closest lot with room, so follow the message boards and their instructions.","On Cardinals game days the lots open 4 hours before kickoff. Parking in Sportsman’s Park, the lots around the stadium, serves pre-sold permit holders and single-game visitors, and the Black Lot is set aside for same-day parking without a pre-sold permit. Other events set their own hours, so check that event’s page."),$("Which lots are on the State Farm Stadium parking map?","The stadium’s 2025 Cardinals parking map names its lots by area and color, among them West Preferred, North Preferred, East Preferred, West, Great Lawn, East, Lot F, Oversized, Yellow, Blue, Pink and the Black lot, and it prints exit routes to Northern Avenue and Indian School Road.","Exits depend on where you came from. Guests in the Pink, Blue, Yellow, Grey and Green lots who arrived from the north leave by Northern Avenue, and guests in the Green and Grey lots who arrived from the south leave by Indian School Road. Southbound Loop 101 drivers heading for the Black lot follow its own route, entering from Camelback Road onto Montebello Avenue.","RVs and other oversized vehicles park only in the designated oversized lot, on event days only, and never overnight. On Cardinals game days that is Lot F. It opens 4 hours and 30 minutes before kickoff, needs a Lot F Oversized Vehicle mobile pass, takes one vehicle per space and fits vehicles up to 45 feet.","Some events publish a map of their own. The 2026-27 Vrbo Fiesta Bowl map labels the Black and Blue lots gameday only and shows a West Bus area; our Fiesta Bowl guide covers that game’s parking and transportation."),$("Where is the State Farm Stadium rideshare drop-off and pickup?","Rideshare drop-off and pickup, and drop-offs by family or friends, all use the Black Lot south of the stadium across Cardinals Way, and on Cardinals game days the stadium’s 2025 map marks that rideshare lane westbound only, with the eastbound lane of Cardinals Way closed.","The stadium asks guests to check the event’s own page for updates. The Fiesta Bowl’s guide for last season’s game told guests to walk back to the Black Lot after the game, request the ride there and meet the car in the lot. Build that walk into the plan, and remember that every rideshare guest is using the same point.","No limo or charter lane is published. The Black Lot is the stadium’s named point for drop-off and pickup, so it is the planning anchor for a chauffeured group. The exact spot for your vehicle, and especially for a bus, comes from the event’s traffic plan and the instruction confirmed for the booking.","Guests with mobility needs have another option. Every Sportsman’s Park lot has ADA spaces, and a courtesy cart runs from designated ADA parking to the plaza security checkpoints. It runs from 3 hours before kickoff to 1 hour after on Cardinals days, and from 2 hours before major events to 1 hour after."),$("Can you get to State Farm Stadium without driving?","Valley Metro lists 1 connection for the Westgate Entertainment District beside the stadium, bus Route 70 on Glendale Avenue, and no light rail, so without your own car the practical options are rideshare to the Black Lot, a taxi or a booked vehicle.","The Fiesta Bowl’s guide also points to a bus stop at Glendale Avenue and 95th Avenue and to Valley Metro’s schedules. Check the current Route 70 timetable for your date before relying on it for the ride home.","Parking in the neighborhoods is not an option either. The same guide notes that the City of Glendale prohibits parking in undesignated areas or on residential streets, and that police do not let event traffic reach the stadium through local neighborhoods, so use the arterial streets.","The stadium’s own A-Z guide is direct about the ride home: never drink and drive, and use a designated driver, a rideshare service or a taxi. A booked vehicle follows that advice for a whole group at once."),$("What are the State Farm Stadium tailgating rules?","Tailgating is allowed in the carparks once they open, 4 hours before kickoff on Cardinals game days, with these rules: stay in 1 stall, keep the tailgate behind your vehicle, weight tents above ground, do not save spaces, arrive together, and pack up before carparks close 1 hour after the event.","Keep equipment out of neighboring stalls, walkways and aisles, and use above-ground weights rather than stakes for tents. Saving a space for friends who come later is not allowed: a group that wants to tailgate together has to arrive together.","On Cardinals game days the team adds its own guidelines, and post-game tailgating is prohibited. Events such as the Fiesta Bowl publish their own rules for game day, so read the current version for the date you are going.","Tailgating is built around a parked vehicle, one stall and the space behind it. A group arriving by drop-off has no stall. If the plan includes a tailgate, tell the reservations team, because the vehicle then has to stay parked, which needs its own parking arrangement and, for a bus, the oversized-lot rule above."),$("How much time and hassle does parking at State Farm Stadium add?","On a Cardinals game day, the stadium’s map encourages fans to arrive within the first 2 hours after the lots open, which is 4 to 2 hours before kickoff, then staff direct each car to a lot with room, parking is card-only, and the map sets exit routes by lot after the game.","Arriving early is the stadium’s advice, not a rule, but the gates open 2 hours before kickoff for NFL games. A car that arrives when the lots open therefore waits about 2 hours before anyone can go in.","After the game, carparks close 1 hour after the event, and the 2025 Cardinals map sends drivers out by Northern Avenue or Indian School Road depending on the lot and the direction they came from. On game day, dial 511 and press star 7 for Cardinals traffic information from the Arizona Department of Transportation.","All of that falls on whoever drives, who also has to stay fit to drive home after the game."),$("Why does a chauffeured drop-off beat parking at State Farm Stadium?","A chauffeured drop-off removes 3 parts of the day: the group steps out at the Black Lot or the point confirmed for the booking instead of walking from an assigned lot, nobody waits in a lot exit line after the game, and one vehicle carries everyone, so nobody has to be the designated driver.","It does not skip traffic. Every vehicle leaving the stadium, ours included, moves with the event traffic plan, and the chauffeur meets the group at the agreed point when the plan allows. The difference is that the group walks to one meeting point and rides home, instead of walking to a lot, finding the car and joining the exit.","It also changes the timing. A group that is dropped off does not have to be there when the lots open, so it can plan from the gate time, 2 hours before kickoff for NFL games, instead of the 4-hour lot window.","The trade-off is that no car in the lot means nowhere to leave a bag. The clear bag policy allows clear plastic, vinyl or PVC bags up to 12 by 6 by 12 inches, including clear backpacks and fanny packs, and small non-clear bags up to 4.5 by 6.5 inches. Coolers are prohibited, and once you leave the stadium there is no re-entry."),$("Which vehicle fits a State Farm Stadium group, and what does it cost?",`Match the vehicle to the group: a game-day group of friends starts with the ${x(We[0])} or the ${x(We[1])}, client hospitality starts with the ${x(qe[0])} or the ${x(qe[1])}, and anything over ${Lt} riders moves up to the ${x(ze[0])} or the ${x(ze[1])}.`,...yo(),"State Farm Stadium is in Glendale, on the far side of Phoenix from Scottsdale, so the drive each way is longer than a trip downtown. Tell the reservations team your pickup address and kickoff time, and the quote will show the hours that trip needs."),rd()],nd=[{question:"How much is parking at State Farm Stadium?",answer:"It depends on the event and the lot. The stadium recommends buying parking in advance through SeatGeek, its official parking maps print the rates, and every parking area takes credit cards only."},{question:"Where is the best place to park at State Farm Stadium?",answer:"The red Preferred lots, West Preferred and North Preferred, sit beside the stadium and are entered only at Maryland Avenue and 95th Avenue. General Parking is assigned by staff to the closest lot with room, and on Cardinals days the Black Lot takes same-day parking without a pre-sold permit."},{question:"What time does parking open at State Farm Stadium?",answer:"On Cardinals game days, 4 hours before kickoff, with the oversized Lot F at 4 hours and 30 minutes. Other events list their own times on the event page, and stadium gates open 2 hours before kickoff for NFL games."},{question:"Where is rideshare pickup at State Farm Stadium?",answer:"In the Black Lot, south of the stadium across Cardinals Way. It is also the drop-off and pickup point for family and friends."},{question:"Can you tailgate at State Farm Stadium?",answer:"Yes, in the carparks once they open: one stall per vehicle, tailgate behind your vehicle, weight tents above ground, no saved spaces, and arrive together. Carparks close 1 hour after the event, and post-game tailgating is prohibited at Cardinals games."},{question:"Is there free parking near State Farm Stadium?",answer:"The stadium publishes no free parking, and the Fiesta Bowl’s official guide notes that the City of Glendale prohibits parking in undesignated areas or on residential streets. A drop-off at the Black Lot is the way to arrive without a parking space."},{question:"Where do RVs and oversized vehicles park at State Farm Stadium?",answer:"In the designated oversized lot, on event days only. On Cardinals game days that is Lot F, which opens 4 hours and 30 minutes before kickoff, needs a Lot F Oversized Vehicle mobile pass and fits vehicles up to 45 feet."},{question:"Can a chauffeured Sprinter drop our group at State Farm Stadium?",answer:"Yes, at the point the event’s traffic plan allows. The Black Lot is the stadium’s published drop-off and pickup point, and no separate limo or charter zone is published, so the chauffeur confirms the drop-off for your booking and vehicle."}],Fd={path:"/guides/venues/state-farm-stadium",title:"State Farm Stadium Parking Guide: Lots, Rideshare & Drop-Off",metaTitle:"State Farm Stadium Parking & Drop-Off",description:"Where to park at State Farm Stadium: Preferred and General lots, the Black Lot rideshare drop-off, Cardinals lot hours, tailgating rules and oversized parking, and how a chauffeured group drop-off compares.",metaDescription:"Preferred and General lots, the Black Lot drop-off, hours and tailgating rules",lastUpdated:It,lastUpdatedLabel:A(It),intro:"Scottsdale Sprinters’ short answer on State Farm Stadium parking: buy a space in advance through SeatGeek, as the stadium recommends, pay by credit card because every parking area is cashless, and expect staff to direct you to a lot unless you hold Preferred Parking, which is entered only at Maryland Avenue and 95th Avenue. Rideshare and family drop-off and pickup use the Black Lot south of the stadium, and on Cardinals game days the lots open 4 hours before kickoff. For a group, one chauffeured vehicle replaces the lot, the card reader and the drive out.",sections:od,faqs:nd,links:[{href:"/guides/fiesta-bowl-transportation",label:"Fiesta Bowl parking and transportation guide"},{href:"/guides/venues/desert-diamond-arena",label:"Desert Diamond Arena parking and concerts, across Maryland Avenue"},...go(),{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published pricing"}],sources:td},zr="2026-09-24",je="https://mortgagematchupcenter.com";function re(e,t,...a){return{question:e,answer:t,paragraphs:a}}const xt="executive-sprinter-scottsdale",Rt="limo-sprinter-16-scottsdale",Mt="ultra-luxury-party-sprinter-scottsdale",Ne=e=>o[e],Vr=e=>i[e];function sd(e){const t=s[e],a=Qr({hourlyRateCents:t.hourlyRateCents,minimumHours:t.minimumHours,capacity:Vr(e)},Nt);return`The ${Ne(e)} is ${l(t.hourlyRateCents)} an hour with a ${t.minimumHours}-hour minimum, so ${a.billedHours} billed hours come to ${a.fareLabel} before tax, about ${a.perPersonLabel} each when all ${Vr(e)} seats are filled.`}const id=[{label:"Mortgage Matchup Center — Transportation & Parking",href:`${je}/plan-your-visit/transportation-parking/`},{label:"Mortgage Matchup Center — Accessibility and ADA Information",href:`${je}/venue/accessibility-ada-information/`},{label:"Mortgage Matchup Center — official venue site (bag policy, door times, parking)",href:`${je}/`},{label:"Mortgage Matchup Center — naming rights announcement (October 2, 2025)",href:`${je}/news/phoenix-suns-and-phoenix-mercury-announce-landmark-naming-rights-partnership-with-mortgage-matchup/`},{label:"Mortgage Matchup Center — Private Events",href:`${je}/private-events/`},{label:"Phoenix Suns — 2026-27 schedule",href:"https://www.nba.com/suns/schedule"},{label:"NBA — Phoenix to host NBA All-Star 2027",href:"https://pr.nba.com/phoenix-to-host-nba-all-star-2027/"},{label:"Live Nation — Mortgage Matchup Center events",href:"https://www.livenation.com/venue/KovZpZAE617A/mortgage-matchup-center-events"}],hd=[re("Where do you park for Mortgage Matchup Center?","Mortgage Matchup Center points guests to the several garages and lots within walking distance and asks them to buy parking in advance through ParkWhiz; event parking generally opens about 30 minutes before doors, parking has no in-and-out privileges, and availability, pricing and access vary by event.","The arena is at 201 E. Jefferson Street, on the southeast corner of 1st Street and Jefferson in downtown Phoenix. Its site also lists more than 700 on-site parking spaces, including designated parking for guests with disabilities, with rates that vary by event, and it sends guests to the Mortgage Matchup Center Parking Office at 602-379-2003 for event pricing.","Public garages downtown are typically open all day, but for an event the arena says to plan on parking from about 30 minutes before doors open, unless that event says otherwise. Because parking has no in-and-out privileges, a group that parks early for dinner nearby cannot move the car and come back.","Valet is not open to the public. The arena reserves it for select guests and membership areas, from about 2 hours before the event, at the Ra Ra Room Valet on Jackson Street between 1st and 2nd Streets, the Annexus Valet on Jackson Street between 2nd and 3rd Streets, and inside the Jefferson Street Garage on the 2nd floor, reached from the garage’s 4th Street entrance. Everyone else is asked to buy parking in advance through ParkWhiz."),re("Where is the drop-off and pickup at Mortgage Matchup Center?","The arena publishes one drop-off and pickup for a game or event: 3rd Street just south of Jefferson, at the green curb; the will-call drop-off is on 1st Street just north of Madison, and no vehicle may be parked or left unattended in a drop-off zone.","For rideshare, the arena lists four Lyft drop-off points: 1st Street and Jefferson at the arena plaza, S 2nd Street by The Ryan, S 3rd Street by the Phoenix Convention Center, and E Jefferson Street by Hotel Palomar and the Arrogant Butcher. After the event, Lyft pickups are at S 3rd Street and E Jefferson Street, by the Phoenix Convention Center.","No separate limo or charter zone is published. A chauffeured group uses the published drop-off on 3rd Street or the point event staff direct on the night. Because no vehicle may wait in a drop-off zone, the chauffeur clears the curb after unloading and comes back when the group is together.","Agree on the pickup before the game or show, and share it with everyone. After the final buzzer or the encore, gather first, then message the chauffeur once with the group count, rather than several people sending pins from inside the arena."),re("Can you take light rail to Mortgage Matchup Center?","Yes: Valley Metro Rail stops at 3rd St/Jefferson, right by the arena, and the arena’s own directions also use the Downtown Phoenix Hub, about 0.3 mile’s walk away, and 3rd St/Washington for riders coming west from Gilbert Rd/Main St.","Southbound from Metro Parkway, the arena says to exit at the Downtown Phoenix Hub’s 1st Ave platform and walk about 0.3 mile, or transfer at the Hub’s Jefferson St platform and exit at 3rd St/Jefferson. Northbound from Baseline/Central Ave, exit at the Hub’s Central Ave platform and walk, or make the same transfer. Eastbound from the Hub, board at the Jefferson St platform and exit at 3rd St/Jefferson.","The arena adds that its bus stops and light rail stations are all on accessible routes to and from the building.","Rail suits a couple staying near a station. A group coming from a Scottsdale resort has more steps: getting everyone to a station, onto one train, and back again together after the game or the show."),re("How do you drive to Mortgage Matchup Center from Scottsdale?","From North Phoenix and Scottsdale, the arena’s own route is State Route 51 south to the Interstate 10 East interchange, the Washington/Jefferson Street exit, right on Washington Street to 3rd Street, then left on 3rd Street to the arena and its drop-off.","From the East Valley and Tempe, take Interstate 10 west to Washington/Jefferson Street, turn left on Washington Street to 3rd Street, then left on 3rd Street. From the west, the arena routes drivers along Jefferson Street to 1st Street, where the arena stands on the corner.","The drive is the easy part. The parking, the no in-and-out rule and the walk back to the car after the game fall on whoever drives, who also has to stay fit to drive home."),re("What is the bag policy at Mortgage Matchup Center?","The arena asks guests to arrive without bags when they can: small clutches and crossbody bags are permitted, purses, medical bags and diaper bags are allowed within 14 x 14 x 6 inches with extra screening, and standard backpacks are not permitted inside.","Guests without bags, or with a clutch smaller than 4 x 6 inches, can use the Evolv express entry lanes, which the arena recommends for the quickest way in. Some concerts and special events run modified item rules, so check your event, or ask the arena at feedback@phxses.com before you go.","A group that is dropped off has no car in a garage to leave a backpack in, so settle bags before pickup. Door times vary by event as well: the arena posts them on each event’s page."),re("Is Footprint Center now Mortgage Matchup Center?","Yes: on October 2, 2025, the Suns and the Mercury announced that their downtown Phoenix arena, home to more than 100 sporting and entertainment events a year, is named Mortgage Matchup Center; before that it was Footprint Center, and it is the same building.","The address is unchanged: 201 E. Jefferson Street. The NBA’s 2024 release awarding Phoenix the 2027 All-Star Game still names it Footprint Center, home of the Phoenix Suns, and guests search for it under both names, so this guide uses both.","On its private-events page the arena calls itself the newly renovated, 18,000 capacity arena."),re("What is on at Mortgage Matchup Center this season?","The Suns open their 2026-27 home schedule against the Golden State Warriors on Saturday, October 24, 2026, their last regular-season home game is Friday, April 9, 2027, and the NBA All-Star Game comes to the arena on Sunday, February 21, 2027, with concerts on the nights between.","The home opener tips off at 7 p.m. Most Suns home games do too, and a few start in the afternoon or at another evening time, so check the tip-off for your game. Concerts fill the nights between games. The arena’s calendar includes Kacey Musgraves on October 17, Gorillaz on October 23, Doja Cat on October 29, Don Omar on November 8, Banda MS on November 28 and Trans-Siberian Orchestra on December 6, then Hans Zimmer on March 30 and Niall Horan on May 20, 2027.","The Mercury’s 2027 home dates and the All-Star weekend schedule are announced closer to the date. Door times vary by event, so check the event’s own page before you set a pickup time."),re("Which vehicle fits a Mortgage Matchup Center group, and what does it cost?",`Match the vehicle to the night: a game-night crew or a company outing starts with the ${Ne(xt)}, a concert crew with the ${Ne(Rt)}, and a courtside or suite party with the ${Ne(Mt)}.`,`Every rate prices the whole vehicle by the hour. Here is a ${Nt}-hour booking in each lead vehicle. ${[xt,Rt,Mt].map(sd).join(" ")}`,"Those figures are arithmetic from the published rates, not a quote. An hourly booking keeps the vehicle for the whole night, so the drive each way counts toward the hours. A ride there and a separate ride back can be booked as a transfer instead; the written quote shows how the drive is priced."),re("How should a group plan the night at Mortgage Matchup Center?","Plan 4 things before pickup: a ready time worked back from the event’s door time, one agreed pickup point on 3rd Street after the game or show, one person who messages the chauffeur for the group, and bags that pass the arena’s bag policy.","Guests who need a wheelchair escort can ask any guest service representative at the entrances or the guest services office in the main north pavilion, or text 602-379-7668 from 30 minutes before doors until the end of the event. Mobility devices can be checked in the Guest Services Office.",`For a change of plan on the day, call the reservations team at ${C} or email ${E}.`)],dd=[{question:"How much is parking at Mortgage Matchup Center?",answer:"The arena publishes no single price: parking rates vary by event. Buy in advance through ParkWhiz to see the price before you drive, or call the Mortgage Matchup Center Parking Office at 602-379-2003."},{question:"Where do you park for Mortgage Matchup Center?",answer:"In the garages and lots within walking distance, bought in advance through ParkWhiz, as the arena recommends. Event parking generally opens about 30 minutes before doors, with no in-and-out privileges."},{question:"Where is the drop-off at Mortgage Matchup Center?",answer:"On 3rd Street just south of Jefferson, at the green curb, for games and events. Vehicles cannot be parked or left unattended in the drop-off zone."},{question:"Where is the rideshare pickup at Mortgage Matchup Center?",answer:"At S 3rd Street and E Jefferson Street, by the Phoenix Convention Center."},{question:"Where is Mortgage Matchup Center?",answer:"At 201 E. Jefferson Street, Phoenix, AZ 85004, on the southeast corner of 1st Street and Jefferson in downtown Phoenix."},{question:"What was Mortgage Matchup Center called before?",answer:"Footprint Center. The Suns and the Mercury announced the Mortgage Matchup Center name on October 2, 2025."},{question:"How many people does Mortgage Matchup Center hold?",answer:"The arena describes itself as an 18,000 capacity arena on its private-events page."},{question:"Can a chauffeured Sprinter drop our group at Mortgage Matchup Center?",answer:"Yes, at the published drop-off on 3rd Street or where event staff direct. No separate limo or charter zone is published, and no vehicle may wait at the curb, so the chauffeur returns when your group is ready."}],Dd={path:"/guides/venues/footprint-center",title:"Mortgage Matchup Center Parking Guide: Drop-Off & Rides at the Former Footprint Center",metaTitle:"Mortgage Matchup Center Parking Guide",description:"Where to park for Mortgage Matchup Center, formerly Footprint Center: garages and ParkWhiz, the 3rd Street drop-off, rideshare and light rail, the bag policy, the Suns schedule, and how a chauffeured group ride compares.",metaDescription:"Garages, the 3rd Street drop-off and rideshare",lastUpdated:zr,lastUpdatedLabel:A(zr),intro:"Scottsdale Sprinters’ short answer on Mortgage Matchup Center, formerly Footprint Center: buy parking ahead through ParkWhiz for the garages and lots within walking distance, plan on parking from about 30 minutes before doors, and remember there is no in-and-out. The arena’s drop-off and pickup for games and events is on 3rd Street just south of Jefferson, at the green curb, and light rail stops at 3rd St/Jefferson. For a group, one chauffeured vehicle replaces the garage, the walk back to the car and the drive home.",sections:hd,faqs:dd,links:[{href:`/fleet/${xt}`,label:Ne(xt)},{href:`/fleet/${Rt}`,label:Ne(Rt)},{href:`/fleet/${Mt}`,label:Ne(Mt)},{href:"/fleet",label:"Browse the fleet"},{href:"/pricing",label:"See published pricing"}],sources:id},Id={path:R.path,title:R.h1,metaTitle:"Scottsdale Arabian Horse Show 2027",description:R.description,metaDescription:"WestWorld lots, drop-off, rideshare and hotel pickups for February 11–21",intro:R.intro,lastUpdated:R.lastUpdated,lastUpdatedLabel:R.lastUpdatedLabel,heroImage:R.image,heroAlt:R.imageAlt,sections:[...R.sections.map(e=>({question:e.heading,answer:e.lead,paragraphs:e.paragraphs})),{question:R.faqHeading,answer:R.faqLead,paragraphs:[]}],faqs:R.faqs,links:[...R.moneyLinks,{href:"/guides/venues/westworld-of-scottsdale",label:"WestWorld of Scottsdale venue guide"}],sources:R.sources};export{Id as A,md as B,Ed as C,bd as D,pd as F,yd as G,wd as H,Td as I,Dd as M,gd as N,Lo as P,Fd as S,Cd as T,vd as W,kd as a,Sd as b,Ad as c,$d as d,Pd as e,Xo as f,vn as g,Nn as h,os as i,Ts as j,Ls as k,ti as l,Si as m,Wi as n,fd as o,Qi as p,hh as q,Sh as r,Uh as s};
